ll power(ll a,ll b){
	ll res = 1;
	while(b>0){
		if(b&1){
			res = res*a%MOD;
		}
		a=a*a%MOD;
		b = b >> 1;
	}
	return res;
}

ll gyaku(ll a){
	return power(a,MOD-2);
}

ll kaijou(ll a){
	ll res = 1;
	for(int i = 1;i<=a;i++){
		res = res*i%MOD;
	}
	return res;
}

ll comb(ll a,ll b){
	return kaijou(a)*gyaku(kaijou(b))%MOD*gyaku(kaijou(a-b))%MOD;
}

