    ll n, m, k;
    cin >> n >> m >> k;

    Combination com(200005);

    mint ans = 0;
    for (int i = 1; i < n; i++) ans += i * (n - i) * m * m;
    for (int i = 1; i < m; i++) ans += i * (m - i) * n * n;
    ans *= com.C(n * m - 2, k - 2);

    cout << ans << "\n";
    return 0;
}

