			(ySum += ((n - i) * i) % mod) %= mod;
		}
		ll m2 = m * m % mod;
		(ySum *= m2) %= mod;
		//1...n * (m-1) * n * 1;
		//2...n * (m-2) * n * 2;
		sum += ySum;
	}
	(sum *= f.cmb(n * m - 2, k - 2) % mod) %= mod;
