ll pl(ll a, ll b) {
    a %= mod, b %= mod;
    return (a+b) % mod;
}
ll mu(ll a, ll b) {
    a %= mod, b %= mod;
    return (a*b) % mod;
}
ll pow_mod(ll a, ll b) {
    if (b == 0) return 1;
    ll k = pow_mod(a, b/2);
    k = mu(k, k);
    if (b & 1) k = mu(k, a);
    return k;
}
ll di(ll a, ll b) {
    return mu(a, pow_mod(b, mod-2));
}
ll nCk(ll n, ll k) {
    ll X = 1, Y = 1;
    for (int a = n, b = k; b > 0; a--, b--) {
        X = mu(X, a);
        Y = mu(Y, b);
    }
    return di(X, Y);
}
