    ll base = ans;
    // N*M
    for (int i = 1; i < N; ++i) {
        temp = M * M * (i + 1) * i / 2;
        ans = ans + temp;
        ans %= mod;
        temp = base * (2 * i + 1);
        ans = ans + temp;
        ans %= mod;
