int fat[maxn], ifat[maxn], sum[maxn];
void init(){
	fat[0] = 1;
	for(int i = 1; i < maxn; i++) fat[i] = mul(fat[i - 1], i);
       	ifat[maxn - 1] = inv(fat[maxn - 1]);	
