	for(int i = 1; i < maxn; i++){
		sum[i] = sum[i - 1] + i;
		if(sum[i] >= mod) sum[i] -= mod;
	}
}
int ncr(int n, int k){
	if(n < k) return 0;
	return mul(fat[n], mul(ifat[k], ifat[n - k]));
}
