        now = now * N * N % mod;
        now = now * dm % mod;
        sum = (sum + now) % mod;
    }
    for(ll dn = 1; dn < N; dn++) {
        ll now = N - dn;
        now = now * M * M % mod;
        now = now * dn % mod;
        sum = (sum + now) % mod;
    }
    cout << sum * factor % mod << endl;
    return 0;
}

