const int MAX = 510000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

void _main()
{
    COMinit();

    ll N, M, K;
    cin >> N >> M >> K;

    ll ansX = 0;
    for (ll i = 1; i < M; ++i)
    {
        ansX += i * (M - i) * (N * N);
        ansX %= MOD;
    }
    ansX *= COM(N * M - 2, K - 2);
    ansX %= MOD;

    ll ansY = 0;
    for (ll i = 1; i < N; ++i)
    {
        ansY += i * (N - i) * (M * M);
        ansY %= MOD;
    }
    ansY *= COM(N * M - 2, K - 2);
    ansY %= MOD;

    cout << (ansX + ansY) % MOD << endl;
}

