//aのp乗を求める
ll jou(ll a,ll p)
{
	ll ret=1;
	ll b2[40];
	b2[0]=a;
	for(int i=1;i<40;i++)
	{
		b2[i]=b2[i-1]*b2[i-1];
		b2[i]%=MOD;
		if(b2[i]<0)
			b2[i]+=MOD;
	}

	for(ll bit=0;bit<40;bit++)
	{
		ll tmp=(p&(1LL<<bit));
		if(tmp>0)
		{
			ret*=b2[bit];
			ret%=MOD;
			if(ret<0)
				ret+=MOD;
		}
	}
	return ret;
}

int main()
{
