		kai[i]=kai[i-1]*i;
		kai[i]%=MOD;
		if(kai[i]<0)
			kai[i]+=MOD;
	}
	//逆元
	for(int i=0;i<200001;i++)
		gyaku[i]=jou(kai[i],MOD-2);

	for(int i=0;i<n*m;i++)
	{
