long long int mpow(long long int x, long long int n, long long int mod){
  long long int ans = 1;
  while(n!=0){
    if(n&1) ans = ans * x % mod;
    x = x * x % mod;
    n = n >> 1;
  }
  return ans;
}

long long int nCr(long long int n, long long int r, long long int mod){
  vector<long long int> fac(n+1);
  vector<long long int> ifac(n+1);
  fac[0] = 1;
  ifac[0] = 1;
  for(long long int i = 0; i<n; i++){
    fac[i+1] = fac[i] * (i+1) % mod;
    ifac[i+1] = ifac[i] * mpow(i+1, mod-2, mod) % mod;
  }
  if(n==0 && r==0) return 1;
  if(n<r || n<0) return 0;
  long long int tmp = ifac[n-r] * ifac[r] % mod;
  return tmp * fac[n] % mod;
}

