struct Combination
{
    void init(ll n)
    {
        mNumTbl.resize(n + 1);
        mInverseNumTbl.resize(n + 1);
        mNumTbl[0] = 1;
        mInverseNumTbl[0] = 1;
        FOR(i, n + 1, 1)
        {
            mNumTbl[i] = (mNumTbl[i - 1] * i) % MOD;
        }
        FOR(i, n + 1, 1)
        {
            mInverseNumTbl[i] = modpow(mNumTbl[i]);
        }
    }

    ll get(ll n, ll r)
    {
        if (n < r || n < 0)
            return 0;
        return (((mNumTbl[n] * mInverseNumTbl[r]) % MOD) * mInverseNumTbl[n - r]) % MOD;
    }

    //! バイナリ方で累乗を計算
    ll modpow(ll n)
    {
        ll s = 1, p = n;
        for (ll i = 0; (1LL << i) <= MOD - 2; ++i, p = (p * p) % MOD)
        {
            if (((MOD - 2) & (1 << i)) == 0)
                continue;
            s *= p;
            s %= MOD;
        }
        return s;
    }

    vector<ll> mInverseNumTbl;
    vector<ll> mNumTbl;
};

int main()
{
    ll N, M, K;
    cin >> N >> M >> K;
    ll D = N * M;
    Combination cmb;
    cmb.init(D + 5);
    ll T = cmb.get(D - 2, K - 2);
    ll ans = 0;
    REP(i, D)
    {
        ll x = i % M;
        ll y = i / M;
        ll rn = (M - x) * (M - x - 1) / 2;
        ll ln = x * (x + 1) / 2;
        ll n = N - y;
        ll s = (n * rn + (n - 1) * ln + n * (n - 1) * M / 2) % MOD;

        ans = (ans + s * T % MOD) % MOD;
    }
    cout << ans << endl;
    return 0;
}

