int nCr(int n, int r) {
    if(r > n) return 0;
    int ans = fact[n];
    ans = mul(ans, ifact[n-r]);
    ans = mul(ans, ifact[r]);
    return ans;
}

int nPr(int n, int r) {
    if(r > n) return 0;
    int ans = fact[n];
    ans = mul(ans, ifact[n-r]);
    return ans;
}

