        for_(d,1,X) {
            lint add = ((X - d) * Y * Y) % MOD;
            add = (d * add) % MOD;
            ret = (ret + add) % MOD;
        }
        return ret;
    };

    lint ans = (func(N, M) + func(M, N)) % MOD;
    ans = (ans * comb.compute(N * M - 2, K - 2)) % MOD;
    cout << ans << endl;
}

