const int mod = 1e9 + 7;

int sm(int a) {
    if(a%2 == 0) {
        return a/2*(a+1)%mod;
    } else {
        return (a+1)/2*a%mod;
    }
}

int pow(int a, int b) {
    if(b == 0) return 1;
    if(b%2) return a*pow(a, b-1)%mod;
    return pow(a*a%mod, b/2)%mod;
}

int ncr(int a, int b) {
    int ret = 1;
    for(int i = 0; i < b; ++i) {
        int num = a-i;
        ret = (ret*num)%mod;
    }
    int denom = 1;
    for(int i = 1; i <= b; ++i) {
        denom = (denom*i)%mod;
    }
    ret *= pow(denom, mod-2);

    return ret;
}

