    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < m; ++j) {
            int left = sm(j);
            int right = sm(m-j-1);
            int rows_below = n-i-1;
            int below = (left+right)*rows_below + m*sm(rows_below);
            ans += right + below;
            ans %= mod;
        }
    }

    int picks = ncr(n*m-2, k-2)%mod;
    ans = (ans*picks)%mod;

    cout << ans << endl;

    return 0;
}

