const int MAX = 2000005;
const ll mod = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];
void COMinit(){
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for(int i = 2; i < MAX; i++){
        fac[i] = fac[i-1] * i % mod;
        inv[i] = mod - inv[mod%i] * (mod/i) % mod;
        finv[i] = finv[i-1] * inv[i] % mod;
    }

}
long long COM(int n, int k){
    if(n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n-k] % mod) % mod;
}


int main(){
    ll N, M, K; cin >> N >> M >> K;
    COMinit();

    ll ans = 0;
    for(int d=1; d<=N-1; d++){
        ans += d*(N-d)%mod*M%mod*M%mod*COM(N*M-2, K-2)%mod;
        ans %= mod;
    }

    for(int d=1; d<=M-1; d++){
        ans += d*(M-d)%mod*N%mod*N%mod*COM(N*M-2, K-2)%mod;
        ans %= mod;
    }

    cout << ans << endl;
}

