int modpow(int a, int n) {
	int r = 1;
	while (n) r = r * ((n % 2) ? a : 1) % mod, a = a * a%mod, n >>= 1;
	return r;
}

int comb(int P, int Q) {
	if (P < 0 || Q<0 || Q>P) return 0;
	int p = 1, q = 1;
	Q = min(Q, P - Q);
	for (int i = 1; i <= Q; i++) p = p * P%mod, q = q * i%mod, P--;

	return p * modpow(q, mod - 2) % mod;
}
