/* 
NxMのマス目にK個コマを置いた時の
コマ同士のマンハッタン距離の総和を
全てのコマの置き方について合計

XとYは独立なのでまずXについて考える
ある2つのコマの組み合わせを考えると、
それ以外のコマの置き方の組合わせは Combination(N*M-2, K-2) = tmp1
距離がdとなる2つのコマの組み合わせは (N-d) * M * M = tmp2
よってXの総和は tmp1 * (すべてのdについてのtmp2の合計)
*/
int main() {
	// 入力
	ll N,M,K;cin>>N>>M>>K;

	// 解法
    COMinit();

    ll X = 0;
    REP(d,N){
        X += d * (N-d) * M * M;
        X %= MOD;
    }
    X *= COM(N*M-2, K-2);
    X %= MOD;


    ll Y = 0;
    REP(d,M){
        Y += d * (M-d) * N * N;
        Y %= MOD;
    }
    Y *= COM(N*M-2, K-2);
    Y %= MOD;
    ll ans = X + Y;
    ans %= MOD;

	//出力
	cout << ans << endl;
}

