const int MOD = 1000000007;

ll mp(ll a,int b) {
	ll ans = 1;
	while (b) {
		if (b % 2)
			ans *= a;
		a *= a;
		a %= MOD;
		ans %= MOD;
		b /= 2;
	}
	return ans;
}

ll modwari(ll a, ll b) {
	a %= MOD;
	return (a * mp(b, MOD - 2))%MOD;
}

ll nCk(ll n, int k) {
	ll ans = 1;
	for (int i = 0;i < k;i++) {
		ans *= n - i;
		ans = modwari(ans, i + 1);
	}
	return ans;
}

