mint nCrMod(ll n, ll r)
{
    if (n < r || n < 0 || r < 0)
    {
        return 0;
    }
    r = min(r, n - r);
    mint a = 1;
    for(ll i= n-r+1; i<=n; i++)
    {
        a *= i;
    }

    a /= factMod(r);
    return a;
}

mint nHrMod(ll n, ll r)
{
    return nCrMod(n + r - 1, r);
}

template<class T>
constexpr auto modK_belowN(T k, T MOD, T n)
{
    return (n + MOD - k - 1) / MOD;
}


void solve(){
    ll N,M,K; cin >> N >> M >> K;

    mint res = 0;
    mint c = nCrMod(N*M-2, K-2);

    rep(i,N){
        rep(j,M){
            if(i==0&&j==0) continue;
            mint val = i+j;
            if(i>0&&j>0) val *= 2;
            val *= (N-i); 
            val *= (M-j);
            val *= c; 
            res += val;
        }
    }

    cout << res.n << endl;
}

