ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  assert(fact[2] == 2);
  ll ret = fact[n];
  if (rfact[r] == 0) {
    rfact[r] = mod_inverse(fact[r], M);
  }
  ret = (ret*rfact[r]) % M;
  if (rfact[n - r] == 0) {
    rfact[n - r] = mod_inverse(fact[n - r], M);
  }
  ret = (ret*rfact[n - r]) % M;
  return ret;
}

ll nHr(ll n, ll r) {
  return nCr(n+r-1, r);
}


ll calc(ll h, ll w, ll k) {
    ll sum = 0;
    for (int diff = 1; diff < h; diff++) {
        sum += (ll)diff * nCr((h * w - 2) % MOD, k - 2) % MOD * w % MOD * h % MOD * (h - diff) % MOD;
        sum %= MOD;
    }
    return sum;
}

