ll NUM = pow(10,9) + 7;

vector<ll> fact, fact_inv;

// 繰り返し二乗法
ll power(ll a, ll b){
	ll res=1;
	while(b>0){
		if(b&1) res=res*a%NUM;
		a=a*a%NUM;
		b>>=1;
	}
	return res;
}
void make_fact(int n){
	fact.resize(n+1);
	fact_inv.resize(n+1);
	fact[0] = fact[1] = 1;
	for(int i(2);i<=n;++i){
		fact[i] = (fact[i-1] * i)%NUM;
	}
	fact_inv[n]=power(fact[n], NUM-2);
    for(int i(n-1);i>0;--i){
		fact_inv[i]=fact_inv[i+1]*(i+1)%NUM;
	}
}

ll nCr(ll n, ll r){
	return (fact[n]*fact_inv[r])%NUM*fact_inv[n-r]%NUM;
}

int main(){
	int N,M,K;
	cin >> N >> M >> K;
	ll ans(0);
	rep(i,M){
		ans = (ans + i * (M-i) % NUM * N % NUM * N % NUM ) % NUM;
	}
	rep(i,N){
		ans = (ans + i * (N-i) % NUM * M % NUM * M % NUM ) % NUM;
	}
	make_fact(M*N);
	if(K > 2){
		ans = ans*nCr(M*N-2, K-2)%NUM;
	}
	cout << ans << endl;
	return 0;
}

