template <uint64_t N>
class Combination {
  using _Tp = long long;
public: 
  array<_Tp, N> fac, finv, inv;

  constexpr
  Combination() {
    init();     
  }

  constexpr
  void init() {
    fac[0] = fac[1] = 1;        
    finv[0] = finv[1] = 1;      
    inv[1] = 1; 
    for(int i = 2; i < N; i++){    
      fac[i] = fac[i-1] * i % MOD;      
      inv[i] = MOD - inv[MOD%i] * (MOD/i) % MOD;        
      finv[i] = finv[i-1] * inv[i] % MOD;       
    }
  }

  // n!! * k!^(-1) * ((n - k)!)^(-1)   
  constexpr
  _Tp comb(_Tp n, _Tp k) const {
    if (n < k) return 0;        
    if (n < 0 || k < 0) return 0;       
    return fac[n] * (finv[k]* finv[n - k] % MOD) % MOD; 
  }

  constexpr
  _Tp operator ()(_Tp n, _Tp k) const {
    return comb(n, k);
  }
};

int main() {
  int n, m, k;
  cin >> n >> m >> k;
  constexpr int num = 200200;
  Combination<num> comb;

  ll ans1 = 0, ans2 = 0;
  for (int i = 1; i < n; ++i) {
    ans1 += (i * (n - i)) % MOD;
    ans1 %= MOD;
  }

  ans1 = ans1 * m * m % MOD;

  for (int i = 1; i < m; ++i) {
    ans2 += (i * (m - i)) % MOD;
    ans2 %= MOD;
  }

  ans2 = ans2 * n * n % MOD;

  cout << ((ans1 + ans2) * comb(n*m - 2, k - 2)) % MOD << endl;
}

