ll mpow(ll x, ll y, ll m) {
    if (y == 0)
        return 1;
    else if (y%2 == 1)
        return x * mpow(x, y-1, m)%m;
    else
        return mpow(x*x%m, y/2, m)%m;
}

// mod inverse 法mにおけるxの逆数
ull minverse(ull x, ull m) {
    return mpow(x, m-2, m);
}

ll c2(ll n, ll k, ll m) {
    if (n == 0 && k == 0) return 1;
    if (k > n) return 0;
    if (n <= 0) return 0;
    if (n == k) return 1;

    ll res = 1;
    for (ll x = n-k+1; x <= n; x++) {
        res = res * x;
        if (m != -1) res %= m;
    }
    for (ll x = 1; x <= k; x++) {
        if (m == -1) res = res/x;
        else      res = (res * minverse(x, m)) % m;
    }
    return res;
}

