        E_y %= MOD;
    }
    E_y *= inv(C_mod(n * m, 2));
    E_y %= MOD;

    ll E = (E_x + E_y) % MOD; //2つ駒を置いたときのコストの期待値
    E *= C_mod(k, 2);
