ll cal_comb(ll a, ll b, ll mod) {
  if (b > a-b) return cal_comb(a, a-b, mod);
  ll bunsi = 1;
  ll bunbo = 1;
  for (int i = 0; i < b; ++i) {
    bunsi *= (a - i);
    bunsi %= mod;
    bunbo *= (i + 1);
    bunbo %= mod;
  }
  return bunsi * modinv(bunbo, mod) % mod;
}

