template<typename T>
T modPow(T base, T p, T mod)
{
    T ret = 1;
    T cur = base;
    T cp = 1;
    while (cp <= p) {
        if (p & cp) {
            ret = (ret * cur) % mod;
        }
        cur = cur * cur % mod;
        cp *= 2;
    }
    return ret;
}

