// sigma_全ての組み合わせ sigma_i sigma_j |x_i - x_j| 
// => sigma_i sigma_j sigma_全ての組み合わせ |x_i - x_j| 
int f(ll n, ll m, ll k){
    ll t = 0;
    for (ll len=1; len<n; len++){ // ある2点を決める。その時の長さをlenとする
        t += (len * (n-len))%MOD;
        t %= MOD;
    } 
    t *= c3(n*m-2, k-2, MOD); // 残りk-2は自由に選ぶ
    t %= MOD;
    t *= (m * m) % MOD; // yについては2点とも自由に選べる
    t %= MOD;
    return t;
}

