int modPow(int x, int n, int mod)
{
	int ret = 1;
	int mul = x;
	while ( n > 0 ) {
		if ( n & 1 ) ret = (int64_t)ret * mul % mod;
		mul = (int64_t)mul * mul % mod;
		n >>= 1;
	}
	return ( ret );
}

int modInv(int x, int mod)
{
	return ( modPow(x, mod - 2, mod) );
