template<uint_fast64_t modulus>
class modInt{
    using u64 = uint_fast64_t;

private:
    u64 num;

    u64 _power(u64 _x, u64 _n){
        u64 res = 1;
        while(_n > 0){
            if(_n & 1){
                res = res * _x % modulus;
            }
            _x = _x * _x % modulus;
            _n >>= 1;
        }
        return res;
    }

public:
    modInt(){
        num = 0;
    }

    modInt(u64 x){
        num = x % modulus;
    }

    u64 get(void){
        return num;
    }

    void print(void){
        cout << num << endl;
        return;
    }

    void print(char c){
        cout << num << c;
    }

    modInt &operator+=(const modInt &rhs){
        num += rhs.num;
        if(num >= modulus){
            num -= modulus;
        }
        return *this;
    }

    modInt &operator-=(const modInt &rhs){
        if(num < rhs.num){
            num += modulus;
        }
        num -= rhs.num;
        return *this;
    }

    modInt &operator*=(const modInt &rhs){
        num = num * rhs.num % modulus;
        return *this;
    }

    modInt &operator/=(const modInt &rhs){
        num = num * _power(rhs.num, modulus - 2) % modulus;
        return *this;
    }

    modInt operator+(const modInt &rhs){
        return modInt(*this) += rhs;
    }

    modInt operator-(const modInt &rhs){
        return modInt(*this) -= rhs;
    }

    modInt operator*(const modInt &rhs){
        return modInt(*this) *= rhs;
    }

    modInt operator/(const modInt &rhs){
        return modInt(*this) /= rhs;
    }
};

