ll inv[MAX],fact[MAX],ifact[MAX];

void pre()
{
	fact[0] = fact[1] = ifact[0] = ifact[1] = inv[1] = 1;
	for(int i = 2;i < MAX;i++)
	{
		inv[i] = mul(MOD - (MOD / i),inv[MOD % i],MOD);
		fact[i] = mul(i,fact[i - 1],MOD);
		ifact[i] = mul(ifact[i - 1],inv[i],MOD);
	}
}

ll nCr(ll a,ll b)
{
	if(a < b) return 0;
	ll ans = 1;
	for(ll i = 0;i < b;i++)
		ans = mul(ans,(a - i),MOD);
	ans = mul(ans,ifact[b],MOD);
	return ans;
}

