namespace Numeric {
    template<typename T, typename N> 
    T pow(T a, N n) {
        T r(1);
        while (n > 0) {
            if (n & 1) { r *= a; }
            a *= a; n >>= 1;
        }
        return r;
    }
    template<int mod>
    struct IntMod {
        int value;
        IntMod(int value_ = 0) : value(value_) {
            if (value >= mod) value -= mod;
            if (value < 0) value += mod;
        }
        IntMod& operator+=(IntMod num) {
            value += num.value;
            if (value >= mod) value -= mod;
            return *this;
        }
        IntMod& operator-=(IntMod num) {
            value -= num.value;
            if (value < 0) value += mod;
            return *this;
        }
        IntMod operator+(IntMod num) const { return IntMod(*this) += num; }
        IntMod operator-(IntMod num) const { return IntMod(*this) -= num; }
        IntMod operator*(IntMod num) const { return IntMod(int(value * 1LL * num.value % mod)); }
        IntMod& operator*=(IntMod num) { return *this = *this * num; }
        IntMod operator/(IntMod num) const { return *this * pow(num, mod-2); }
        IntMod& operator/=(IntMod num) { return *this = *this / num; }
    };
    template<int mod> bool operator<(IntMod<mod> a,IntMod<mod> b) { return a.value < b.value; }
    template<int mod>
    std::ostream& operator<<(std::ostream& os, const IntMod<mod>& num) {
        return os << num.value;
    }
}

const int mod = (int)1e9+7, N = 200200;
using namespace Numeric;
using Int = IntMod<mod>;
Int fact[N], ifact[N];
Int C(int n, int k) {
    if (k < 0 || k > n) return 0;
    return fact[n] * ifact[n-k] * ifact[k];
}
void init() {
    fact[0] = 1;
    for (int i = 1; i < N; i++) fact[i] = fact[i-1] * i;
    ifact[N-1] = Int(1) / fact[N-1];
    for (int i = N-2; i >= 0; i--) ifact[i] = ifact[i+1] * (i+1);
    for (int i = 0; i < N; i++) {
        assert(C(i,i) == Int(1));
    }
}
Int fast(int n, int m, int k) {
    Int answ(0);
    for (int drow = 0; drow < n; drow++) {
        // last + drow == n - 1
        int last = n - 1 - drow;
        answ += Int(last+1) * drow * m * m * C(n*m-2,k-2);
    }
    for (int dcol = 0; dcol < m; dcol++) {
        // last + dcol == m - 1
        int last = m - 1 - dcol;
        answ += Int(last+1) * dcol * n * n * C(n*m-2,k-2);
    }
    return answ;
}
Int slow(int n, int m, int k) {
    assert(m == 1);
    Int answ(0);
    vi idx;
    for (int mask = 1; mask < (1 << n); mask++) {
        if (__builtin_popcount(mask) != k) continue;
        idx.clear();
        for (int bit = 0; bit < n; bit++)
            if ((mask >> bit) & 1) idx << bit;
        for (int i = 0; i < isz(idx); i++) {
            for (int j = i+1; j < isz(idx); j++) {
                answ += idx[j] - idx[i];
            }
        }
    }
    return answ;
}
void brute() {
    for (int n = 2; n <= 20; n++) {
        for (int k = 2; k <= n; k++) {
            auto ft = fast(n,1,k);
            auto sl = slow(n,1,k);
            if (ft != sl) {
                watch(n,k,ft,sl);
            }
            assert(fast(n,1,k) == slow(n,1,k));
        }
        std::cout << "n = " << n << ": OK" << std::endl;
    }
    std::exit(0);
}
int main() {
    init();
    //brute();
    int n,m,k;
    while (std::cin >> n >> m >> k) {
        std::cout << fast(n,m,k) << std::endl;
    }
    return 0;
}

