  for(i = 1; i <= n * m; ++i) fact[i] = mul(fact[i - 1], i);
  c = mul(fact[n * m - 2], mul(rev(fact[k - 2]), rev(fact[n * m - k])));
  for(i = 0; i < n; ++i) for(j = 0; j < m; ++j) {
    now = m * sum(i) + n * sum(j);
    now += sum(n - 1 - i) * m + sum(m - 1 - j) * n;
    now = mul(now, c);
    ans += now;
    ans %= mod;
  }
  ans = mul(ans, rev(2));
  printf("%lld", ans);
  return 0;
}

