const bool multiple_queries = false;

void solve(){
    /*
    *** 注意 ***
    ・マイナスの整数の除算が0 (マイナスのときはCeil関数になる)になって，マイナスの判定ができていない．
    ・MODの逆元を取るときは素数か否かに注意．
    ・Queue, stack, deque等で必ず`empty`なら飛ばすようにする．
    ・set, multisetで`RE`を起こすときは初期段階で解法に影響が出ないようなダミーをsetに入れておくとエラーを回避できる．
    ・掛け算のOverflow注意．(x * y > 10^18　-> x > 10^18 / y) のような形で判定するとよい．
    ・総和を取る公式 (1+2+...+n = n * (n + 1) / 2)の計算時等で最終的には10^18に収まる場合は`/2`の順序を早める．
    ・Bit演算をするときに`a ^ b != c`のような式は代入演算子になったりするので注意． (ABC150F)
    ・aborted (core dumped) のエラーが出ているときは変数の二重宣言やベクトルの区間外参照を確認．
    ・`tuple`のコンパイルエラーは`make_tuple(a, b, c, ...)`で回避．
    ・グラフの最短経路と木の最短経路は同じDFSでも更新方法に注意. (ABC148E)
    ・Running Errorの１つとして，関数の返り値のタイプが定義されているのに何も返していないことが考えられる．
    ・Running Errorとしてベクトルサイズが0であるにもかかわらずsortをしている場合がある．
    ・境界条件は必ず試す．
    ・Overflow不等式: (前提条件：a, b, c > 0)
        1. a * b <= c -> a <= c / b
        2. a * b <  c -> a <= c / b && (c % b || a != c / b)
        3. c <= a * b -> (c + b - 1) / b <= a
        4. c <  a * b -> (c + b - 1) / b <= a && (c % b || a != c / b)
    */
    // generate_array(size, min, max);
    ll n, m, k; in3(n, m, k);
    mint ans = 0;
    mint coef = combination(n * m - 2, k - 2, MOD);

    auto func = [&](ll x, ll y) -> mint{
        // x, x - 1, ..., 1, 0, 1, 2, ..., m - x
        mint vx = x * (x + 1) / 2 + (m - x - 1) * (m - x) / 2;
        mint vy = y * (y + 1) / 2 + (n - y - 1) * (n - y) / 2;
        mint ret = vx * n + vy * m;
        return ret;
    };

    rep(y, n) rep(x, m) ans += func(x, y);
    ans = (ans * coef) / 2;
    prl(ans);

    // ### DEBUG PART ###
    auto naive_solver = [&](){
    };
    #ifdef _LOCAL
        naive_solver();
    #endif
}

