const ll MOD = 1e9 + 7;
const ll MAX_NM = 2 * 1e5 + 2;

ll factorial[MAX_NM];

ll calc_pow(ll x, ll y) {
    ll z = 1;
    while (y > 0) {
        if (y & 1) {
            z = (z * x) % MOD;
        }
        x = (x * x) % MOD;
        y /= 2;
    }
    return z;
}

ll calc_comb(ll x, ll y) {
    ll div_num = (factorial[x - y] * factorial[y]) % MOD;
    return (factorial[x] * calc_pow(div_num, MOD - 2)) % MOD;
}

