ll POW(ll a, ll b, ll mod)
{
	ll s = 1;
	while (b != 0)
	{
		if (b & 1) s = s * a % mod;
		a = a * a % mod;
		b >>= 1;
	}
	return s % mod;
}

ll Lucas(ll n, ll k, ll p)        //C (n, k) % p
{
	ll ret = 1;
	while (n && k)
	{
		ll nn = n % p, kk = k % p;
		if (nn < kk) return 0;  //inv (f[kk]) = f[kk] ^ (p - 2) % p
		ret = ret * f[nn] * POW(f[kk] * f[nn - kk] % p, p - 2, p) % p;
		n /= p, k /= p;
	}
	return ret;
}
