const ll mod = 1e9 + 7;

ll power_mod(ll a, ll power){
    ll value = 1;

    while(power != 0){
        if(power & 1) value = (value * a) % mod;
        a = (a * a) % mod;
        power = power >> 1;

    }

    return value % mod;
}

//https://qiita.com/ofutonfuton/items/92b1a6f4a7775f00b6ae

ll combination(int n, int r){
    ll numerator = 1;
    ll denomenator = 1;

    rep(i, r){
        numerator *= n - i;
        numerator %= mod;
        denomenator *= power_mod(i + 1, mod - 2);
        denomenator %= mod;
    }

    return (numerator * denomenator) % mod;
}

int main(void){
    int N, M, K;

    scanf("%d %d %d", &N, &M, &K);
    ll cost = 0;
    ll comb = combination(N * M - 2, K - 2);

    For(d, 1, N){
        cost += d * (N - d) * M * M;
        cost %= mod;
    }

    For(d, 1, M){
        cost += d * (M - d) * N * N;
        cost %= mod;
    }

    cout << (cost * comb)% mod << endl;

    return 0;
}

