const i64 MAX = 510000;

i64 fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD % i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
i64 COM(i64 n, i64 k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

mint s(i64 x) {
    return mint((x * (x + 1) / 2) % MOD);
}

i64 extGCD(i64 a, i64 b, i64 & x, i64 & y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    i64 d = extGCD(b, a % b, y, x); // 再帰的に解く
    y -= a / b * x;
    return d;
}

// 負の数にも対応した mod (a = -11 とかでも OK) 
inline i64 mod(i64 a, i64 m) {
    return (a % m + m) % m;
}


int main() {
    i64 n, m, k;
    cin >> n >> m >> k;
    COMinit();
    mint ans = 0, cnt = 1;
    for (i64 i = 0; i < n; ++i) {
        for (i64 j = 0; j < m; ++j) {
            mint x = (s(m - j - 1) + s(j)) * n;
            mint y = (s(n - i - 1) + s(i)) * m;
            mint z = mint(COM(n * m - 2, k - 2)) * (x + y);
            ans += z;
        }
    }
    cout << ans * mint(2).inv() << endl;
}

