#define MOD ((ll)pow(10LL, 9LL) + 7LL)

ll solve(ll &incr, ll n, ll i)
{
    ll licr = 0LL;
    licr += n * i;
    licr %= MOD;
    srep (distance, 1LL, n) {
        licr += (i + distance) * 2LL * (n - distance);
        licr %= MOD;
    }

    incr += licr;
    incr %= MOD;

    return incr;
}

