	for (int i = 2; i <= 200000; ++i) {
		kai[i] = (kai[i - 1] * i) % MOD;
		kai_inv[i] = mod_inverse(kai[i]);
	}
	LL ans = (cal(N, M, K) + cal(M, N, K)) % MOD;
	cout << ans << endl;
}

