            ans += M * ((a * (a + 1)) / 2 + (b * (b + 1)) / 2);
            ans += N * ((c * (c + 1)) / 2 + (d * (d + 1)) / 2);
            ans %= mod;
        }
    }
    ans *= modinv(2, mod);
    ans %= mod;
    cout<<(ans * COM(N * M - 2, K - 2)) % MOD<<endl;
}

