long modinv(long a) {
    long  b = MOD, u = 1, v = 0;
    while (b) {
        long  t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;
    return u;
}

template< typename T >
T binomial(T N, T K) {
  if(K < 0 || N < K) return 0;
  T ret = 1;
  for(T i = 1; i <= K; ++i) {
    ret *= N--;
    ret%=MOD;
    ret *=modinv(i);
    ret%=MOD;
  }
  return ret%MOD;
}

