    for (int i = 1; i <= n - 1; ++i)
    {
        ret += ((((n - i) * m) % mod) * m % mod) * i % mod;
        ret %= mod;
    }


    for (int i = 1; i <= m - 1; ++i)
    {
        ret += ((((m - i) * n) % mod) * n % mod) * i % mod;
        ret %= mod;
    }

    ll comb = calc(n * m - 2ll, k - 2, mod);

    cout << (ret * comb) % mod << endl;

    return 0;
}

