	for(int i = 2; i <= MN; i++) Inv[i] = 1ll * (mod - mod / i) * Inv[mod % i] % mod;
	for(int i = 1; i <= MN; i++) inv[i] = 1ll * Inv[i] * inv[i - 1] % mod;

	printf("%d\n", (solve(n, m) + solve(m, n)) % mod);

