void solve(){
    // generate_array(size, min, max);
    ll n, m, k;
    in3(n, m, k);
    mint coef = combination(n * m - 2, k - 2, MOD);
    mint ans = 0;
    auto func = [&](ll i, ll X, ll Y) -> mint{
        mint val = i * (i + 1) / 2 + (X - 1 - i) * (X - i) / 2;
        val *= Y; val *= Y;
        return val * coef;
    };
    rep(i, n) ans += func(i, n, m);
    rep(i, m) ans += func(i, m, n);

    ans *= modinv(2, MOD);
    prl(ans);

