// Fermat の小定理を用いた F_mod 上での逆元計算x^(mod-2), 蟻本p115
ll Inverse(ll x){
    ll res = 1;
    int n = mod - 2;
    while(n > 0){
        if(n & 1){
            res = res * x % mod;
        }
        x = x * x % mod;
        n >>= 1;
    }
    return res;
}

int main() {
    int N, M, K;
    cin >> N >> M >> K;
    // N <= M にする
    if(N > M){
        int t = N;
        N = M;
        M = t;
    }
    // コストは任意の2点間のマンハッタン距離の総和

    // 階乗計算, iの階乗 = fact[i}
    vector<ll>fact(N*M);
    fact[0]=1;
    for(int i=1; i<N*M; i++){
        fact[i] = fact[i-1] * i % mod;
    }

    // 任意の2点間のマンハッタン距離に(N*M-2)_C_(K-2)をかけたものが求める総和
    // マンハッタン距離ごとに計算
    ll ans = 0;
    ll temp;
    // 1*M
    for (int i = 1; i < M; ++i) {
        temp = i * (M - i) % mod;
        ans = ans + temp;
        ans %= mod;
    }

    ll base = ans;
    // N*M
    for (int i = 1; i < N; ++i) {
        temp = i + 1;
        temp = temp * i;
        temp %= mod;
        temp = temp * Inverse(2);
        temp %= mod;
        temp = temp * M % mod;
        temp = temp * M % mod;
        ans = ans + temp;
        ans %= mod;
        temp = base * 2 % mod;
        temp = temp * i % mod;
        ans = ans + temp;
        ans %= mod;
        ans = ans + base;
        ans %= mod;
    }
    ans = ans * fact[N*M-2];
    ans %= mod;
    ans = ans * Inverse(fact[K-2] * fact[N*M-K] % mod);
    ans %= mod;
    cout << ans;
    return 0;
}

