ll mexp(ll x, ll y)
{
    if(!y) return 1;
    if(y & 1) return x * mexp(x*x%mod, y>>1) % mod;
    else return mexp(x*x%mod, y>>1);
}
ll binom(ll a, ll b)
{
    if(a < b) return 0;
    ll ret = 1;
    ret = fac[a];
    ret *= ifac[a-b];
    ret %= mod;
    ret *= ifac[b];
    ret %= mod;
    return ret;
}
