long long power_mod(long long x, long long power)
{
    long long result = 1;

    while(power > 0)
    {
        if(power%2)
            result = (result*x)%MOD;

        x = (x*x)%MOD;
        power = power >> 1;
    }

    return result;
}

long long inverse(long long n)
{
    return power_mod(n, MOD - 2);
}

