// factorial(mod) n!
ll fact(ll n, int MOD) {
	ll res = 1;
	while (n > 1) {
		res = res * n % MOD;
		n--;
	}
	return res;
}

// power(mod) x^n
ll pow(ll x, ll n, int MOD) {
	ll res = 1;
	while (n > 0) {
		if (n & 1) res = res * x % MOD;
		x = x * x % MOD;
		n >>= 1;
	}
	return res;
}

// inverse(mod) x^(-1)
ll inv(ll x, int MOD) {
	return pow(x, MOD - 2, MOD);	
}

// permutation(mod) nPr
ll permu(int n, int r, int MOD) {
	if (r < 0 || n < r) return 0;
	else {
		ll res = fact(n, MOD);
		res = res * inv(fact(n - r, MOD), MOD) % MOD;
		return res;
	}
}

// combination(mod) nCr
ll combi(int n, int r, int MOD) {
	ll res = permu(n, r, MOD);
	res = res * inv(fact(r, MOD), MOD) % MOD;
	return res;	
}

