        ans += i * (N-i) * M*M * fact % MOD;
        ans %= MOD;
    }
    // y 方向
    FOR(i, 1, M){
        ans += i * (M-i) * N*N * fact % MOD;
        ans %= MOD;
    }
    cout << ans << endl; 

    return 0;
}

