    for (int i = 0; i < N; i++) {
      a += arithmeticSum(N - i, i + 1, 1) - (i + 1) * (N - i) % MOD + MOD;
      a %= MOD;
    }
    a = a * M % MOD * M % MOD;
    ll b = 0;
    for (int i = 0; i < M; i++) {
      b += arithmeticSum(M - i, i + 1, 1) - (i + 1) * (M - i) % MOD + MOD;
      b %= MOD;
    }
    b = b * N % MOD * N % MOD;
    res = (res + a) % MOD;
    res = (res + b) % MOD;
    res = res * choose(N * M - 2, K - 2) % MOD;
    cout << res << endl;
  }
  return 0;
}

