const int MAXN = 222222;

vl fact(MAXN);
vl rfact(MAXN);

ll mod_pow(ll x, ll p, ll M = MOD) {
  ll a = 1;
  while (p) {
    if (p % 2)
      a = a*x%M;
    x = x*x%M;
    p /= 2;
  }
  return a;
}

ll mod_inverse(ll a, ll M = MOD) {
  return mod_pow(a, M - 2, M);
}

void set_fact(ll n, ll M = MOD) {
  fact[0] = fact[1] = rfact[0] = rfact[1] = 1;
  for (ll i = 2; i <= n; i++) {
    fact[i] = i * fact[i - 1] % M;
    rfact[i] = mod_inverse(fact[i], M);
  }
}

//http://drken1215.hatenablog.com/entry/2018/06/08/210000
//nが大きくfactが計算できないときのほかの計算方法について書いてある
ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  ll ret = fact[n];
  ret = (ret*rfact[r]) % M;
  ret = (ret*rfact[n - r]) % M;
  return ret;
}

ll solve (ll h, ll w, ll k) {
  ll rn = h * (w - 1);
  ll ln = h;
  ll rs = (h * (w - 1) * w / 2) % MOD;
  ll ls = 0;

  ll res = 0;
  rep (j, w) {
    res = (res + rs + ls) % MOD;
    rs -= rn;
    ls += ln;
    rn -= h;
    ln += h;
  }
  res = res * h % MOD;
  (res *= nCr(h*w - 2, k - 2)) %= MOD;
  return res;
}

int main() {
  int h, w, k;
  cin >> h >> w >> k;

  set_fact(h*w + 10);

  ll ans = solve(h, w, k);
  ans = (ans + solve(w, h, k)) % MOD;
  ans = ans * mod_inverse(2) % MOD;
  cout << ans << endl;
}

