ll extgcd(ll a, ll b, ll& x, ll& y){
    ll d = a;
    if(b != 0){
        d = extgcd(b, a % b, y, x);
        y -= (a / b) * x;
    }else{
        x = 1;
        y = 0;
    }
    return d;
}
ll mod_inverse(ll a){//逆元
    ll x,y;
    extgcd(a, MOD, x, y);
    return (MOD + x % MOD) % MOD;
