    if(r < 0 || r < 0) return 0;
    n %= MOD, r %= MOD;
    ll a, b, c;
    a = kai(n);
    b = mod_inverse(kai(n-r));
    c = mod_inverse(kai(r));
    return a * b % MOD * c % MOD;
}

