}

//n! mod p
long long my_fact(const int n, const int p)
{
    long long r=1;
    for(int i=2; i<=n; i++)
        r = (r * i) % p;
    return r;
}

long long my_inverse(const int n, const int p)
{
    return my_pow(n, p-2, p);
}

//nCk mod p
long long my_comb(const int n, const int k, const int p)
{
    long long a = my_fact(n, p);
    long long b = my_inverse(my_fact(k, p), p);
    long long c = my_inverse(my_fact(n-k, p), p);
    //printf("%lld %lld\n", b, c);
    return (((a * b) % p) * c) % p;
}

//sum(|x_i - x_j|), 1 < i, j < n
long long sum_of_abs(const int m, const int n, const int p)
{
    long long sx=0, sy=0;
    for(int i=0; i<m; i++){
        sx = (sx + i * (m-i)) % p;
    }
    for(int i=0; i<n; i++){
        sy = (sy + i * (n-i)) % p;
    }
    long long N = (n * n) % p;
    long long M = (m * m) % p;
    return ( (sx * N) % p + (sy * M) % p ) % p;
}

