struct mint
{
	lint n;
	mint()
	{
		n = 0;
	}
	mint(lint a)
	{
		n = a % mod;
	}
	mint& operator+=(mint a)
	{
		n += a.n;
		n %= mod;
		return *this;
	}
	mint& operator-=(mint a)
	{
		n += mod;
		n -= a.n;
		n %= mod;
		return *this;
	}
	mint& operator*=(mint a)
	{
		n *= a.n;
		n %= mod;
		return *this;
	}
	mint& operator%=(mint a)
	{
		n %= a.n;
		return *this;
	}
	mint& operator++()
	{
		n++;
		n %= mod;
		return *this;
	}
	mint& operator--()
	{
		n += mod;
		n--;
		n %= mod;
		return *this;
	}
};

mint operator+(mint a, mint b)
{
	a += b;
	return a;
}
mint operator-(mint a, mint b)
{
	a -= b;
	return a;
}
mint operator*(mint a, mint b)
{
	a *= b;
	return a;
}

