	ll ans = 0;
	ans += a*(1+a+b)*(b+1)/2;
	ans += b*(1+b+c)*(c+1)/2;
	ans += c*(1+c+d)*(d+1)/2;
	ans += d*(1+d+a)*(a+1)/2;
	//print(ans)
	return ans%MOD;
}

