ll inv_2, inv_6;
const int mod = 1e9 + 7;

ll mod_pow(ll x, ll n, ll mod) {
  if (n == 0) return 1;
  ll ret = (n & 1) ? x : 1;
  ll half = mod_pow(x, n / 2, mod);
  ret *= half * half % mod;
  return ret % mod;
}

void init(int f_max = 200000) {
  fact.resize(f_max + 1);
  ifact.resize(f_max + 1);
  fact[0] = 1;
  for(ll i = 1; i <= f_max; i++) {
    fact[i] = (fact[i - 1] * i) % mod;
  }
  ifact[f_max] = mod_pow(fact[f_max], mod - 2, mod);
  for(ll i = f_max - 1; i >= 0; i--) {
    ifact[i] = (ifact[i + 1] * (i + 1)) % mod;
  }
  inv_2 = mod_pow(2, mod - 2, mod);
  inv_6 = mod_pow(6, mod - 2, mod);
}

ll comb(ll n, ll k) {
  return fact[n] * ifact[n - k] % mod * ifact[k] % mod;
}

int main() {
  init();
  ll N, M, K;
  cin >> N >> M >> K;
  ll sum = 0;
  sum += (M * M % mod * N % mod * N % mod * (1 + N) % mod * inv_2 % mod + mod - M * M % mod * N % mod * (N + 1) % mod * (2 * N % mod + 1) % mod) % mod;
  sum %= mod;
  sum += (N * N % mod * M % mod * M % mod * (1 + M) % mod * inv_2 % mod + mod - N * N % mod * M % mod * (M + 1) % mod * (2 * M % mod + 1) % mod) % mod;
  sum %= mod;
  cout << sum * comb(N * M - 2, K - 2) % mod << endl;
}

