using mint = ModInt<1000000007>;

// nCrで用いる
vector<mint> fact, factinv;
// nCrで用いる 予め計算しておく
void nCr_compute_factinv(int N) {
	N = min(N, mint::Mod - 1);
	fact.resize(N + 1);
	factinv.resize(N + 1);
	fact[0] = 1;
	rep(i, 1, N + 1) fact[i] = fact[i - 1] * i;
	factinv[N] = fact[N].inverse();
	for (int i = N; i >= 1; i--)
		factinv[i - 1] = factinv[i] * i;
}
mint nCr(int n, int r) {
	if (n >= mint::Mod)
		return nCr(n % mint::Mod, r % mint::Mod) *
		nCr(n / mint::Mod, r / mint::Mod);
	return r > n ? 0 : fact[n] * factinv[n - r] * factinv[r];
}

mint nHr(int n, int r) { return r == 0 ? 1 : nCr(n + r - 1, r); }


signed main(signed argc, char *argv[]) {
	cin.tie(0);
	ios::sync_with_stdio(false);
	cout << fixed << setprecision(12);

	int N, M, K; cin >> N >> M >> K;
	int X = N * M;
	nCr_compute_factinv(X);

	vector<vector<int>>dp(N, vector<int>(M));
	auto dp2 = dp;
	rep(i, 0, N) {
		rep(j, 0, M) {
			dp[i][j] = i + j;
			dp2[i][j] = i + 1 + j + 1;
		}
	}
	rep(i, 1, N) {
		dp[i][0] += dp[i - 1][0];
		dp2[i][0] += dp2[i - 1][0];
	}
	rep(i, 1, M) {
		dp[0][i] += dp[0][i - 1];
		dp2[0][i] += dp2[0][i - 1];
	}
	rep(i, 1, N) {
		rep(j, 1, M) {
			dp[i][j] += dp[i - 1][j] + dp[i][j - 1] - dp[i - 1][j - 1];
			dp2[i][j] += dp2[i - 1][j] + dp2[i][j - 1] - dp2[i - 1][j - 1];
		}
	}

	auto dist = [&](int x, int y) {
		int a = x / M;
		int b = x % M;
		int c = y / M;
		int d = y % M;
		return abs(a - c) + abs(b - d);
	};
	auto ff = [&](int x, int y) {
		int id = x * M + y;
		mint ret = 0;
		rep(x, id + 1, X) {
			ret += dist(id, x);
		}
		ret *= nCr(X - 2, K - 2);
		return ret;
	};
	auto f = [&](int x, int y) {
		mint ret = 0;
		int a = N - 1 - x, b = M - 1 - y;
		ret = dp[a][b];
		if (x + 1 < N and y - 1 >= 0) {
			int aa = (x + 1);
			int bb = y - 1;
			ret += dp2[N - aa - 1][bb];
		}
		ret *= nCr(X - 2, K - 2);
		return ret;
	};

	mint ans = 0;
	rep(i, 0, N) {
		rep(j, 0, M) {
			ans += f(i, j);
		}
	}
	cout << ans << endl;

	return 0;
}

