//繰り返し２乗法を用いたpow。MOD版。
long long modPow(long long x, long long y){
    long long r=1, a=x%MOD;
    while(y > 0){
        if((y&1) == 1) r = (r*a) % MOD;
        a = (a*a) % MOD;
        y /= 2;
    }
    return r;
}

//--------------------------------
//ここからはMODが素数の場合のみ可

//--------------------------------
//MODでの逆元。
long long modInverse(long long x){
    return modPow(x, MOD-2);
}

//--------------------------------
//MODでの割り算。
long long modDivision(long long p, long long q){
    return (p*modInverse(q)) % MOD; //((p%MOD)*modInverse(q)) % MOD の方が安全？
}

LL C(LL n, LL k) {
  if(memo[k]) return memo[k];
  if(k > n) return 0;
  if(k == 0 || n == 0) return 1;
  long long p=1, q=1;
  for(int i=1; i<=k; i++){
      q = (q*i) % MOD;
      p = (p*((n-i+1+MOD)%MOD))%MOD;
  }
  memo[k] = modDivision(p, q);
  return memo[k];
}

void solve() {
  cin >> n >> m >> k;
  LL res = 0;

  LL ysum = 0;
  REP(i, n) {
    ysum = (ysum + i*(i+1)/2%MOD) % MOD;
  }

  REP(i, m) {
    LL _ysum = ysum;
    if(i > 0) _ysum = _ysum*2%MOD;
    LL l = ((_ysum + i*n%MOD*n%MOD) % MOD) * (m-i) % MOD;
    res = (res + l * C(n*m-2, k-2) % MOD ) % MOD;
  }
  cout << res << endl;
}

