typedef long long ll;

// (N*M)C(K)  (N*M-2)C(K-2) * (|x-x|+|y-y|)
// 2C0

ll M = 1000000007;

ll mod(ll x) {
  return (x + M) % M;
}

ll inv(ll x) {
  ll m = M-2;
  ll r = 1;
  ll y = x;
  while (m > 0) {
    if (m & 1) r = mod(r * y);
    y = mod(y * y);
    m >>= 1;
  }
  return r;
}

ll combi(int n, int k) {
  ll p = 1;
  for (int i = n; i > n-k; i--) {
    p = mod(p * i);
  }
  ll q = 1;
  for (int i = k; i > 0; i--) {
    q = mod(q * i);
  }
  return mod(p * inv(q));
}

int main() {
  int N, M, K;
  scanf("%d%d%d", &N, &M, &K);
  ll c = combi(N*M-2, K-2);
  ll s = 0;
  ll xs = 0;
  for (int x1 = 0; x1 < M; x1++) {
    for (int x2 = x1 + 1; x2 < M; x2++) {
      xs = mod(xs + abs(x1 - x2));
    }
  }
  //printf("xs=%lld\n", xs);
  ll xxs = 0;
  for (int x1 = 0; x1 < M; x1++) {
    for (int x2 = 0; x2 < M; x2++) {
      xxs = mod(xxs + abs(x1 - x2));
    }
  }
  //printf("xxs=%lld\n", xxs);
  for (int y1 = 0; y1 < N; y1++) {
    s = mod(s + xs);
    for (int y2 = y1 + 1; y2 < N; y2++) {
      s = mod(mod(s + xxs) + mod(mod(M*M) * abs(y1-y2)));
    }
  }
  ll ans = mod(c * s);
  printf("%lld\n", ans);
}

