const ll MOD = 1e9+7;
const int index = 2*1e5+1;

ll add(ll a,ll b){
      return ((a%MOD)+(b%MOD))%MOD;
}

ll mul(ll a,ll b){
      return ((a%MOD)*(b%MOD))%MOD;
}

ll power(ll a,ll b){
      if(b==0) return 1;
      else if(b%2==0){
            ll ret=power(a,b/2);
            return ((ret%MOD)*(ret%MOD))%MOD;
      }
      else return ((power(a,b-1)%MOD)*(a%MOD))%MOD;
}
ll dive(ll a,ll b){
      return ((a%MOD)*(power(b,MOD-2)%MOD))%MOD;
}

ll frac[index+1];
void calc(){ //main関数内にcalc();を入れること
      frac[0]=1;
      rep0(i,index){
            frac[i+1]=mul(frac[i],i+1);
      }
}

