#define MOD 1000000007

template <long long mod>
class Mod
{
public:
    long long value;
    Mod(long long x = 0)
    {
        set_value(x);
    }

    void set_value(const long long x)
    {
        this->value = x % mod;
    }

    friend ostream &operator<<(ostream &os, const Mod &x)
    {
        os << x.value;
        return os;
    }

    bool operator<(const long long x)
    {
        return this->value < x;
    }

    bool operator<(Mod x)
    {
        return *this < x.value;
    }

    bool operator<=(const long long x)
    {
        return this->value <= x;
    }

    bool operator<=(Mod x)
    {
        return *this <= x.value;
    }

    bool operator>(const long long x)
    {
        return this->value > x;
    }

    bool operator>(Mod x)
    {
        return *this > x.value;
    }

    bool operator>=(const long long x)
    {
        return this->value >= x;
    }

    bool operator>=(Mod x)
    {
        return *this >= x.value;
    }

    bool operator==(const long long x)
    {
        return this->value == x;
    }

    bool operator==(Mod x)
    {
        return *this == x.value;
    }

    Mod &operator=(const long long x)
    {
        set_value(x);
        return *this;
    }

    Mod &operator=(const Mod x)
    {
        *this = x.value;
        return *this;
    }

    Mod &operator+=(const long long x)
    {
        this->value = (this->value + x) % mod;
        return *this;
    }

    Mod &operator+=(const Mod x)
    {
        *this += x.value;
        return *this;
    }

    Mod &operator-=(const long long x)
    {
        this->value = (this->value - x) % mod;
        return *this;
    }

    Mod &operator-=(const Mod x)
    {
        *this -= x.value;
        return *this;
    }

    Mod &operator*=(const long long x)
    {
        this->value = (this->value * x) % mod;
        return *this;
    }

    Mod &operator*=(const Mod x)
    {
        *this *= x.value;
        return *this;
    }

    Mod &operator/=(const long long x)
    {
        long long a = x;
        long long b = mod;
        long long u = 1;
        long long v = 0;
        while (b)
        {
            long long t = a / b;
            a -= t * b;
            swap(a, b);
            u -= t * v;
            swap(u, v);
        }
        u %= mod;
        if (u < 0)
            u += mod;
        *this *= Mod(u);
        return *this;
    }

    Mod &operator/=(const Mod x)
    {
        *this /= x.value;
        return *this;
    }

    Mod operator+(const long long x) const
    {
        return Mod(*this) += x;
    }

    Mod operator+(const Mod x) const
    {
        return Mod(*this) += x;
    }

    Mod operator-(const long long x) const
    {
        return Mod(*this) -= x;
    }

    Mod operator-(const Mod x) const
    {
        return Mod(*this) -= x;
    }

    Mod operator*(const long long x) const
    {
        return Mod(*this) *= x;
    }

    Mod operator*(const Mod x) const
    {
        return Mod(*this) *= x;
    }

    Mod operator/(const long long x) const
    {
        return Mod(*this) /= x;
    }

    Mod operator/(const Mod x) const
    {
        return Mod(*this) /= x;
    }

    Mod &operator++()
    {
        *this += 1;
        return *this;
    }

    Mod &operator--()
    {
        *this -= 1;
        return *this;
    }

    Mod operator++(auto)
    {
        Mod ret(*this);
        ++*this;
        return ret;
    }

    Mod operator--(auto)
    {
        Mod ret(*this);
        --*this;
        return ret;
    }
};

template <typename T, typename U>
T calcCombination(T x, U y)
{
    if (x < y)
    {
        return 0;
    }

    if ((x - y) < y)
    {
        T y = x - y;
    }

    T ans = 1;
    for (T i = 1; i <= y; i++)
    {
        ans *= x;
        ans /= i;
        x--;
    }
    return ans;
}

int main()
{
    Mod<MOD> N(0);
    Mod<MOD> M(0);
    Mod<MOD> K(0);
    cin >> N.value >> M.value >> K.value;

    Mod<MOD> ans(0);
    Mod<MOD> coef(calcCombination(N * M - 2, K - 2));
    for (Mod<MOD> i = 1; i < N; i++)
    {
        ans += (N - i) * M * M * i * coef;
    }

    for (Mod<MOD> i = 1; i < M; i++)
    {
        ans += (M - i) * N * N * i * coef;
    }
    cout << ans << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX = 510000;
const int MOD = 1000000007;

long long fac[MAX], finv[MAX], inv[MAX];

// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
    }
}

// 二項係数計算
long long COM(int n, int k){
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
    COMinit();
