	int64_t ans{}, tmp{};
	for (int i{1}; i + 1 <= N; i++)
		tmp = (tmp + i * (N - i) % mod) % mod;
	tmp = tmp * M % mod * M % mod;
	ans = tmp;

	tmp = 0;
	for (int i{1}; i + 1 <= M; i++)
		tmp = (tmp + i * (M - i) % mod) % mod;
	tmp = tmp * N % mod * N % mod;
	ans = (ans + tmp) % mod;

	ans = ans * combi.getCombi((N * M - 2) % mod, (K + mod - 2) % mod) % mod;
	printf("%lld\n", ans); 

	return 0;
}

