ll manhattan(ll n)
{
	ll ans=0;
	for(ll i=1;i<=n;i++)
	{
		for(ll j=i+1;j<=n;j++)
		{
			ans+=j-i;
			ans%=mod;
		}
	}
 	return ans;
}
ll modexp(ll a,ll b)
{
	if(a==0)return 0;
	if(b==0)return 1;
	if(a==1)return 1;
	if(b%2==0)
	{
		ll val=modexp(a,b/2);
		return(val*val)%mod;
	}
	return (a*modexp(a,b-1))%mod;
}
