ll calcFactional( ll size, 
	vector<ll>& fac, vector<ll>& inv, vector<ll>& facInv, ll mod )
{
	for( ll i = 2; i < size; ++i )
	{
		fac[i] = fac[i - 1] * i % mod;
		inv[i] = mod - inv[mod % i] * ( mod / i ) % mod; // 逆元計算
		facInv[i] = facInv[i - 1] * inv[i] % mod;
 	}
}

ll combinationValue( ll n, ll k, ll mod )
{
	vector<ll> fac( n + 1, 1 ), inv( n + 1, 1 ), facInv( n + 1, 1 );
	calcFactional( n + 1, fac, inv, facInv, mod );

	if( n < k  || n < 0 || k < 0) return 0;
	return fac[n] * ( facInv[k] * facInv[n - k] % mod ) % mod;
 }

int main()
{
