	ll comb = 0;

	REP(i,n) comb = ( comb + (i * (n-i)%cMOD) * (m * m%cMOD) ) % cMOD;
	REP(i,m) comb = ( comb + (i * (m-i)%cMOD) * (n * n%cMOD) ) % cMOD;

	comb = comb * combinationValue( n * m - 2, k-2, cMOD ) % cMOD;

	cout << comb << endl;

	return 0;
}

