/* v-v-v-v-v-v-v-v-v Main Part v-v-v-v-v-v-v-v-v */
class Combination {
    int powmod(int a, int p) {
        int ans = 1;
        int mul = a;

        for (; p > 0; p >>= 1, mul = (mul * mul) % mod) {
            if ((p & 1) == 1) ans = (ans * mul) % mod;
        }

        return ans;
    }
public:
    int N;
    int mod;
    vector<int> fact;
    vector<int> revFact;

    Combination(int n, int m) : N(n), mod(m), fact(n+1), revFact(n+1) {
        fact[0] = 1;
        for (int i = 1; i <= N; i++) {
            fact[i] = fact[i-1] * i;
            fact[i] %= mod;
        }

        // Fermat's little theorem
        revFact[N] = powmod(fact[N], mod - 2);

        for (int i = N-1; i >= 0; i--) {
            revFact[i] = revFact[i+1] * (i+1);
            revFact[i] %= mod;
        }
    }

    int get(int a, int b) {
        if (a < 0 || b < 0) return 0;
        if (b > a) return 0;
        return (((fact[a] * revFact[b]) % mod) * revFact[a-b]) % mod;
    }
};

signed main() {
    int N, M, K;
    cin >> N >> M >> K;

    Combination comb = Combination(N * M, MOD);

    map<int, int> m; // 距離keyの組がvalue個ある
    for (int i = 0; i < N; i++) {
        for (int ii = 0; ii < N; ii++) {
            for (int j = 0; j < M; j++) {
                for (int jj = 0; jj < M; jj++) {
                    if (i == ii && j == jj) continue;
                    int d = abs(i - ii) + abs(j - jj);
                    m[d]++;
                }
            }
        }
    }

    int ret = 0;
    for (int d = 1; d <= N + M - 2; d++) {
        ret += d * (m[d] / 2);
        ret %= MOD;
    }
    ret *= comb.get(N * M - 2, K - 2);
    ret %= MOD;

    cout << ret << endl;
    return 0;
}

