    ll res = power(x , y/2);
    if(y&1)
        return (((res*res)%Mod)*x)%Mod;
    else
        return (res*res)%Mod;
}

ll nCr(ll n , ll r){
    ll res = 1;
    r = max(r , n-r);
    for(int i = r+1 ;i <= n ; i++){
        res *= i;
        if(res >= Mod)
            res %= Mod;
    }
    for(int i = 1 ;i <= n-r ; i++){
        res *= power(i , Mod-2);
        if(res >= Mod)
            res %= Mod;
    }
    return res;
}


