			r = (r*a) % MOD, b--;
		else
			a = (a*a) % MOD, b /= 2ll;
	return r;
}

inline ll inv(ll x) {
	return pw(x, MOD-2);
}

inline ll bin(ll n, ll k) {
	return (fac[n] * ifac[k] % MOD) * ifac[n-k] % MOD;
}

int main() {
	fac[0] = ifac[0] = 1;
	for (ll i = 1; i < MAXN; i++)
		fac[i] = fac[i-1] * i % MOD, ifac[i] = inv(fac[i]);
	ll n, m, k; scanf("%lld %lld %lld", &n, &m, &k);
	ll ans = 0, dx = 0, dy = 0;
	for (ll i = 1; i < n; i++)
		dx = (dx + i * (n-i) % MOD) % MOD;
	dx = dx * (m*m%MOD) % MOD;
	for (ll i = 1; i < m; i++)
		dy = (dy + i * (m-i) % MOD) % MOD;
	dy = dy * (m*m%MOD) % MOD;
	ans = (ans*bin(n*m-2, k-2)) % MOD;
	prl(ans);
    return 0;
}

