	ll cn = n*m - 2;
	for(ll i=1; i<=cn; i++){
		p *= i;
		p %= mod;
	}

	for(ll i=1; i<=cn-ck; i++){
		q *= i;
		q %= mod;
	}
	for(ll i=1; i<=ck; i++){
		q *= i;
		q %= mod;
	}

	ll ans = 0;
	ll ot = 0;
	for(ll i=1; i<=n; i++){
		ans += ot * m;	
		ans %= mod;

		ot += i * m;
		ot %= mod;
	}

	ot = 0;
	for(ll i=1; i<=m; i++){
		ans += ot * n;
		ans %= mod;

		ot += i * n;
		ot %= mod;
	}

	ans *= p;
	ans %= mod;
	ans *= mypow(q, mod-2);
	ans %= mod;

	cout << ans << endl;
}

