class Combination{
public:
    ll N;
    ll mod;
    vector<ll> fact;

    Combination(ll n, ll m) : N(n), mod(m), fact(n+1){
        fact.at(0) = 1;
        for(ll i=1; i<=N; i++){
            fact.at(i) = i * fact.at(i-1) % mod;
        }
    }

    ll POW(ll a, ll b){
        ll res = 1;
        while(b > 0){
            if(b & 1){
                res = res * a % mod;
            }
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }

    ll combin(ll n, ll k){
        if(n < 0 || k < 0 || n < k){
            return 1;
        }
        return fact.at(n) * POW(fact.at(k) * fact.at(n-k) % mod, mod - 2) % mod;
    }
};

