long long int nCr(long long int n, long long int r, long long int mod) {
  vector<vector<long long int>> v(n+1, vector<long long int>(n+1, 0));
  for(int ii=0; ii<v.size(); ii++){
    v[ii][0] = 1;
    v[ii][ii] = 1;
  }
  for(int ii=1; ii<v.size(); ii++) {
    for (int jj=1; jj<ii; jj++) {
      v[ii][jj] = (v[ii-1][jj-1] + v[ii-1][jj]) % mod;
    }
  }
  return v[n][r] % mod;
}

