long long qpow(long long a, long long b, int MOD) {
    if (b == 0) return 1;
    long long res = 1;
    while (b) {
        if (b & 1) res = (res * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return res;
}

const int MOD = 1e9 + 7;
const int maxn = 2e6;
int fac[maxn + 5];
int invfac[maxn + 5];
void init() {
    fac[0] = 1;
    for (int i = 1; i <= maxn; i++) fac[i] = 1LL * fac[i - 1] * i % MOD;
    invfac[maxn] = (int)(qpow(fac[maxn], MOD - 2, MOD));
    for (int i = maxn - 1; i >= 0; i--) invfac[i] = 1LL * invfac[i + 1] * (i + 1) % MOD;
}
int C(int n, int k) {
    assert(0 <= k && n >= k);
    int tmp = (int)(1LL * invfac[k] * invfac[n - k] % MOD);
    return (int)(1LL * fac[n] * tmp % MOD);
}

int main() {
    cin.tie(nullptr);
    ios::sync_with_stdio(false);

    int n, m, k;
    cin >> n >> m >> k;
    init();
    LL ans = 0;
    for (int i = 0; i < n; i++) {
        int d = n - 1 - i;
        LL cur = 1LL * d * (d + 1) / 2;
        cur = (cur * m) % MOD;
        cur = (cur * m) % MOD;
        ans = (ans + cur) % MOD;
    }
    for (int j = 0; j < m; j++) {
        int d = m - 1 - j;
        LL cur = 1LL * d * (d + 1) / 2;
        cur = (cur * n) % MOD;
        cur = (cur * n) % MOD;
        ans = (ans + cur) % MOD;
    }
    ans = (ans * C(n * m - 2, k - 2)) % MOD;
    cout << ans << '\n';

    return 0;
}

