//関数名：mod_pow
//概要：modつき指数関数
//第一引数a：指数の底
//第二引数b：指数
//第三引数mod：法となる値
//戻り値：a^b(m mod)
long long mod_pow(long long a, long long b, long long mod){
    if(b == 0) return 1;
    if(b % 2 == 0){
        long long d = mod_pow(a,b/2,mod);
        return (d*d)%mod;
    }else return a%mod*mod_pow(a,b-1,mod)%mod;
}

//関数名：mod_combination
//概要：modつき二項係数
//第一引数n：組み合わせの全体
//第二引数r：何個取り出すか
//第三引数mod：法となる値
//戻り値：nCr(m mod)
//計算量O(nlog(mod))
long long mod_combination(long long n,long long r,long long mod){
    if(r > n) return 0;
    if(n == r || r == 0) return 1;
    long long fact1 = 1,fact2 = 1;
    for(long long i = n; i >= n-r+1; i--) fact1 = fact1*i%mod;
    for(long long i = r; i >= 1; i--) fact2 = fact2*i%mod;
    return fact1*mod_pow(fact2,mod-2,mod)%mod;
}


int main(){
    ll n,m; cin >> n >> m;
    ll k; cin >> k;
    ll ans = 0;
    ll comb = mod_combination(n*m-2,k-2,MOD);
    for(ll d = 1; d < n; d++){
        ans += d*(n-d)*m%MOD*m%MOD*comb%MOD;
        ans %= MOD;
    }
    for(ll d = 1; d < m; d++){
        ans += d*(m-d)*n%MOD*n%MOD*comb%MOD;
        ans %= MOD;
    }
    cout << ans << endl;
}

#include <iostream>
#include <stdio.h>
using namespace std;

const int MX = 200005, MOD = 1E9 + 7;

int m, n, k;
long long ans = 0;
long long ngt[MX]; // tinh n giai thua
long long ive[MX]; // tinh nghich dao modulo cua ive[i]
long long kgt[MX]; // tinh nghich dao modulo cua k giai thua (tinh tich nghich dao modolu tu 1 -> k)
long long d[MX];   // tong do "chenh lech" cua (1, 1) -> (1, max(n, m))
long long c[MX];   // mang tong (de hieu :]]] )

void gener()
{
    ngt[0] = kgt[0] = 1;
    ngt[1] = kgt[1] = ive[1] = 1;
    for (int i = 2; i <= m * n; i++)
    {
        ngt[i] = ngt[i - 1] * i % MOD;
        ive[i] = MOD - MOD / i * ive[MOD % i] % MOD;
        kgt[i] = kgt[i - 1] * ive[i] % MOD;
    }
}

void solve()
{
    for (int i = 1; i <= max(m, n); i++)
    {
        c[i] = (c[i - 1] + (i - 1)) % MOD;
        d[i] = (c[i] + d[i - 1]) % MOD;
    }
    ans += d[m] * n % MOD * n % MOD;
    ans += d[n] * m % MOD * m % MOD;
}

int main()
{
    scanf("%d%d%d", &n, &m, &k);
    gener();
    solve();
    cout << ans * ngt[m * n - 2] % MOD * kgt[k - 2] % MOD * kgt[m * n - k] % MOD;
}

