            i64 y = (((s(n - i - 1) + s(i)) % MOD * m) % MOD);
            i64 z = (COM(n * m - 2, k - 2) * (x + y)) % MOD;
            ans = (ans + z) % MOD;
        }
    }
    cout << (ans * modinv(2, MOD)) % MOD << endl;
}

