	if (x > n || y > m) return 0;
	if (k == 1)
		return inc(inc(inc(qzh1[a][b], -qzh1[x - 1][b]), -qzh1[a][y - 1]), qzh1[x - 1][y - 1]);
	if (k == 2)
		return inc(inc(inc(qzh2[a][b], -qzh2[x - 1][b]), -qzh2[a][y - 1]), qzh2[x - 1][y - 1]);
} 
