    while (y > 0) { 
        if (y & 1) 
            res = (res*x)%mod; 
        y = y>>1;
        x = (x*x)%mod; 
    } 
    return res%mod; 
}

ll distancesum(ll arr[], ll n) 
{ 
    // sorting the array. 
    sort(arr, arr + n); 

    // for each point, finding the distance. 
    ll res = 0, sum = 0; 
    for (int i = 0; i < n; i++) { 
        res = (res + ((arr[i] * i)% mod - sum)) % mod; 
        sum = (sum + arr[i]) % mod; 
    } 
    return res; 
} 

ll totaldistancesum(ll x[], ll y[], ll n) 
{ 
    return (distancesum(x, n) + distancesum(y, n)) % mod; 
} 


