using namespace std;

ll comb(ll n, ll r) {
    ll num = 1, den = 1;
    for (ll i = 0; i < r; i++) {
        num *= (n - i);
        num %= mod;
        den *= (r - i);
        den %= mod;
    }

    ll power = mod - 2, x = den;
    ll ans = 1;
    while (power) {
        if (power % 2) {
            ans *= x;
            ans %= mod;
        }

        power /= 2;
        x = (x * x) % mod;
    }

    return (num * ans) % mod;

}


