int main() {
  int n, m, k;
  scanf("%d%d%d", &n, &m, &k);

  int l = n * m - 2;
  fracs[0] = 1;
  for (int i = 1; i <= l; i++)
    fracs[i] = fracs[i - 1] * i % MOD;

  ll ans = (calc(n, m) + calc(m, n)) % MOD * nck(l, k - 2) % MOD;
  printf("%lld\n", ans);

  return 0;
}

