const int N = 2e5+1;
ll f[N], inv[N];
inline ll cb(ll n, ll k)
{
  if (n < k || n < 0 || k < 0) return 0;
  return f[n] * inv[k] % mod * inv[n-k] % mod;
}
void init()
{
  f[0] = 1;
  for (ll i = 1; i < N; ++i) f[i] = f[i-1] * i % mod;
  inv[N-1] = inverse(f[N-1]);
  for (int i = N-1; i >= 1; --i) inv[i-1] = inv[i] * i % mod;
}
