mint fac[MAXR+1],finv[MAXR+1],inv[MAXR+1];

//テーブルの作成
void COMinit() {
    fac[0]=fac[1]=mint(1);
    finv[0]=finv[1]=mint(1);
    inv[1]=1;
    FOR(i,2,MAXR){
        fac[i]=mint(fac[i-1]*mint(i));
        inv[i]=mint(mint(MOD)-inv[MOD%i]*mint(MOD/i));
        finv[i]=finv[i-1]*inv[i];
    }
}

// 二項係数の計算
mint COM(ll n,ll k){
    if(n<k)return 0;
    if(n<0 || k<0)return 0;
    return fac[n]*finv[k]*finv[n-k];
}

