// O(k)
ll modnCk_bigN(int N, int K){
  if (N < K) return 0;
  if (K == 0) return 1;
  ll ret = N;
  inv[1] = 1;
  for (int k=2; k<=K; k++){
    inv[k] = MOD - inv[MOD%k] * (MOD/k) % MOD;
    ret = ret * ((N-k+1) * inv[k] % MOD) % MOD;
  }
  return ret;
}

int main(int argc, const char * argv[]) {
