ll MOD = 1000000007;

ll K, N, M;
ll fact[100001], factinv[100001];

ll modpow(ll a, ll b) {
	ll ret = 1, kakeru = a;
	while (b > 0) {
		if (b & 1)ret *= kakeru, ret %= MOD;
		kakeru *= kakeru, kakeru %= MOD;
		b >>= 1;
	}
	return ret;
}

void setfact() {
	fact[0] = 1, fact[1] = 1;
	for (int i = 2; i <= 100000; i++) {
		fact[i] = fact[i - 1] * i;
		fact[i] %= MOD;
	}
	factinv[100000] = modpow(fact[100000], MOD - 2);
	for (int i = 100000 - 1; i >= 1; i--) {
		factinv[i] = factinv[i + 1] * (i + 1);
		factinv[i] %= MOD;
	}
	factinv[0] = 1;
}

ll comb(ll a, ll b) {
	ll ret = fact[a];
	ret *= factinv[b], ret %= MOD;
	ret *= factinv[a - b], ret %= MOD;
	return ret;
}

