inline ll cmb(ll n, ll k) {
  if(k < 0 || n < k) return 0;
  return fac[n] * invfac[k] % MOD * invfac[n-k] % MOD;
}

int main(void) {
  fac[0] = 1;
  REP(i, N*2) {
    fac[i+1] = fac[i] * (i+1) % MOD;
  }
  invfac[N*2] = mypow(fac[N*2], MOD-2);
  for(int i = N*2; i > 0; --i) {
    invfac[i-1] = invfac[i] * i % MOD;
  }
