      if(i != 0 && i != d) {
        num = (num + max(0LL, (n-i) * (m-d+i))) % MOD;
      }
    }
    res = (res + num * d) % MOD;
  }
  cout << res * cmb(n*m-2, k-2) % MOD << endl;
  return 0;
}

#include <iostream>
