#define lld long long

using namespace std;

const lld MODULO = 1e9 + 7;
const int N = 2e5 + 5;
int n, m, t;
lld d[N], s[N], k[N], res, p, q;
vector <lld> F[N];
lld tu[N];
lld ma[N];
int u, a;

void gener() {
    for (int i = 1; i <= m; i++) {
        k[i] = (k[i - 1] + (i - 1)) % MODULO;
        d[i] = (k[i] + d[i - 1]) % MODULO;
        s[i] = (s[i - 1] + k[i] * 2) % MODULO;
    }
}

void Clear() {
    for (int i = 0; i <= n; i++)
        for (int j = 0; j <= m; j++)
            F[i].push_back(0);
    for (int i = 1; i <= m; i++)
        F[1][i] = d[i];
    for (int i = 1; i <= n; i++)
        F[i][1] = d[i];
}

void print() {
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j <= m; j++)
            cout << F[i][j] << ' ';
        cout << '\n';
    }
}

void prepa() {
    gener();
    Clear();
    for (int i = 2; i <= n; i++)
        for (int j = 2; j <= m; j++) {
            lld temp = ((d[i] * j * j) % MODULO + (s[j] * k[i]) % MODULO + (d[j] * i) % MODULO) % MODULO;
            F[i][j] = temp;
        }
}

void born()
{
    if (p - q >= q)
    {
        for (int i = p - q + 1; i <= p; i++) tu[++u] = i;
        for (int i = 1; i <= q; i++)         ma[++a] = i;
    }
    else
    {
        for (int i = q + 1; i <= p; i++) tu[++u] = i;
        for (int i = 1; i <= p - q; i++) ma[++a] = i;
    }
}

lld gcd(lld a, lld b)
{
    lld tmp;
    while(b != 0)
    {
        tmp = a % b;
        a = b;
        b = tmp;
    }
    return a;
}

void decrease()
{
    for (int i = 1; i <= u; i++)
        for (int j = 1; j <= a; j++)
        {
            if (tu[i] == 1) continue;
            lld temp = gcd(tu[i], ma[j]);
            if (temp == ma[j])
            {
                tu[i] /= ma[j];
                swap(ma[j], ma[a]);
                a--; j--;
            }
            else
            {
                tu[i] /= temp;
                ma[j] /= temp;
            }
        }
}

void solve() {
    q = t - 2;
    p = n * m - 2;
    born();
    decrease();
    lld kCn = 1;
    for (int i = 1; i <= u; i++)
        kCn = (kCn * tu[i]) % MODULO;
    cout << (kCn * F[n][m] ) % MODULO;
}

int main()
{
    //freopen("a.inp", "r", stdin);
    scanf("%d%d%d", &n, &m, &t);
        prepa();
        solve();
    return 0;
}

