    // X座標から求める
    reps(d, M - 1) {
        int xCombi = mod_mul(mod_mul(M - d, N), N);
        ans = mod_add(ans, mod_mul(d, xCombi));
    }
    // Y座標から求める
    reps(dy, N - 1) {
        int yCombi = mod_mul(mod_mul(N - dy, M), M);
        ans = mod_add(ans, mod_mul(dy, yCombi));
    }

    cout << mod_mul(ans, combi) << endl;
    return 0;
}

