//ax + by = gcd(a, b) = d
// 扩展欧几里德算法
/**
 *	a*x + b*y = 1
 *	如果ab互质，有解
 *	x就是a关于b的逆元
 *	y就是b关于a的逆元
 *	 
 *	证明： 
 *		a*x % b + b*y % b = 1 % b
 *		a*x % b = 1 % b
 *		a*x = 1 (mod b)
 */
inline void ex_gcd(LL a, LL b, LL &x, LL &y, LL &d){
    if (!b) {d = a, x = 1, y = 0;}
    else{
        ex_gcd(b, a % b, y, x, d);
        y -= x * (a / b);
    }
}

// 求a关于p的逆元，如果不存在，返回-1 
// a与p互质，逆元才存在 
inline LL inv_mod(LL a, LL p = mod){
    LL d, x, y;
    ex_gcd(a, p, x, y, d);
    return d == 1 ? (x % p + p) % p : -1;
}

inline LL comb_mod(LL m, LL n) {
	LL ret;

	if(m > n) swap(m, n);

	ret = (fac[n] * inv_mod(fac[m], mod)) % mod;
	ret = (ret * inv_mod(fac[n - m], mod)) % mod;

	return ret;
}

void add_mod(LL &a, LL b) {
    a = (a + b) % mod;
}

void mul_mod(LL &a, LL b) {
    a = (a * b) % mod;
}

