const int N=2e5+5;
int mod=1e9+7;
int fact[N],invfact[N];

int power(int base,int exp)
{
	if(exp==0)
		return 1;
	if(exp&1)
		return ((base%mod)*power((base*base)%mod,exp/2))%mod;
	else
		return power((base*base)%mod,exp/2)%mod;
}

void precompute()
{
	fact[0]=1;
	fact[1]=1;
	for(int i=2;i<N;i++)
	{
		fact[i]=((fact[i-1]%mod)*(i%mod))%mod;
	}
	invfact[N-1]=power(fact[N-1],mod-2)%mod;
	for(int i=N-2;i>=0;--i)
	{
		invfact[i]=(invfact[i+1]*(i+1))%mod;
	}
}

int ncr(int a,int b)
{
	if(b>a)
		return 0;
	int temp=0;
	temp=fact[a]%mod;
	temp*=invfact[b];
	temp%=mod;
	temp*=invfact[a-b];
	temp%=mod;
	return temp%mod;
}

