typedef long long ll;

const ll MOD = 1e9 + 7;

class ECellDistance {
public:
	void solve(std::istream& in, std::ostream& out) {
	    int N, M, K;
	    in >> N >> M >> K;

	    ll answer = 0;
	    answer += calcSumOfX(N, M, K);
	    answer += calcSumOfX(M, N, K);
	    answer %= MOD;
	    out << answer << "\n";
	}

private:
    ll calcSumOfX(const int X, const int Y, const int K) {
	    ll sum = 0;
	    const ll combinationOfOthers = combination(X * Y - 2, K - 2, MOD);
        REP(d,1,X) {
            ll combinationOfPair = (ll)(X-d) * Y * Y % MOD;
            sum += (d * combinationOfOthers % MOD) * combinationOfPair % MOD;
            sum %= MOD;
        }
        return sum;
	}
};


int main() {
	ECellDistance solver;
	std::istream& in(std::cin);
	std::ostream& out(std::cout);
	solver.solve(in, out);
	return 0;
}

