using point = complex<double>;
using ll = int64_t;

ll mod = 1000000007;

ll mod_pow(ll x, ll n, ll mod)
{
    if (n == 0)
        return 1;
    ll ret = mod_pow(x * x % mod, n / 2, mod);
    if (n % 2 == 1)
        ret = ret * x % mod;
    return ret;
}

ll nCr_mod(ll n, ll r, ll mod)
{
    if (n < r)
        return 0;
    r = min(r, n - r);
    ll ret = 1;
    for (int i = 0; i < r; i++) {
        ret = (ret * (n - i)) % mod;
        // ret /= i+1;
        ret = (ret * mod_pow(i + 1, mod - 2, mod)) % mod;
    }
    return ret;
}

ll solveX(ll n, ll m, ll k)
{
    ll ret = 0;

    ll l = nCr_mod(n * m - 2, k - 2, mod);

    for (int d = 1; d < n; d++) {
        ret += ((d * (n - d) % mod) * m % mod) * m % mod;
        ret %= mod;
    }
    ret *= l;
    ret %= mod;

    return ret;
}

int my_main(int argc, char** argv)
{
    ios::sync_with_stdio(false);
    cin.tie(0);

    ll n, m, k;
    cin >> n >> m >> k;

    ll ret = 0;
    ret = solveX(n, m, k);
    ret += solveX(m, n, k);
    ret %= mod;

    cout << ret << endl;

    return 0;
}

