	{
		return 0;
	}
	r = mmin(r, n - r);
	mint a = 1;
	if (n < finvtbl.size() && n < facttbl.size())
	{
		a *= facttbl[n];
		a *= finvtbl[r];
		a *= finvtbl[n - r];
		return a;
	}
	else
	{
		repb(i, n - r + 1, n)
		{
			a *= i;
		}
		a *= factModInv(r);
		return a;
	}
}
mint nHrMod(lint n, lint r)
