struct mset
{
  vector<mint> fact;  // n! (mod MOD)
  vector<mint> ifact; // k!^{M-2} (mod MOD)
  mset(int n) : fact(n + 1), ifact(n + 1)
  {
    fact[0] = 1;
    for (int i = 1; i <= n; ++i)
      fact[i] = fact[i - 1] * i;
    ifact[n] = fact[n].inv();
    for (int i = n; i >= 1; --i)
      ifact[i - 1] = ifact[i] * i;
  }
  mint perm(int n, int k)
  { // nPk (mod MOD)
    if (k < 0 || n < k)
      return 0;
    return fact[n] * ifact[n - k];
  }
  mint comb(int n, int k)
  { // nCk (mod MOD)
    if (k < 0 || n < k)
      return 0;
    return fact[n] * ifact[k] * ifact[n - k];
  }
};

