    ll int MOD;
    ll int *fac, *finv, *inv;
    Combination(ll int max_n,ll int mod): MAX_N(max_n+1),MOD(mod){ //make table
        fac = new ll int[MAX_N];finv = new ll int[MAX_N];inv = new ll int[MAX_N];
        fac[0]=fac[1]=1;
        finv[0]=finv[1]=1;
        inv[1]=1;
        for (ll int i = 2; i < MAX_N; i++){
