void combinit(ll n) {
  fac.resize(n);
  ifac.resize(n);

  fac[0] = ifac[0] = 1;
  rep(i, n) {
    fac[i+1] = fac[i]*(i+1) % MOD;
    ifac[i+1] = ifac[i]*modpow(i+1, MOD-2, MOD) % MOD;
  }
}

ll comb(ll n, ll k) {
  if (n == 0 && k == 0) return 1;
  if (n < k || n < 0) return 0;
  return (fac[n]*ifac[k]%MOD)*ifac[n-k]%MOD;
}

