ll powm(ll a, ll n = MOD - 2) {
    ll res = 1;
    for (; n; a = (a * a) % MOD, n >>= 1)
        if (n & 1)
            res = (res * a) % MOD;
    return res;
}

ll C(ll n, ll k) {
    ll res = 1;
    for (ll i = 1; i <= k; i++) {
        (res *= n + 1 - i) %= MOD;
        (res *= powm(i)) %= MOD;
    }
    return res;
}

