	rev[0] = rev[1] = 1;
	for (int i = 2; i < N; i++) rev[i] = (INF - INF / i) * rev[INF % i] % INF;
}
LL C(LL n, int m)
{
	LL ans = 1;
	while (m)
	{
		ans = ans * n % INF * rev[m] % INF;
		n--, m--;
	}
	return ans;
}
LL solve(vector<int>& v)
{
	sort(v.begin(), v.end());
	LL ans = 0;
	LL sum = 0;
	for (int i = 0; i < v.size(); i++)
	{
		ans = (ans + 1LL * v[i] * i - sum) % INF;
		sum += v[i];
		if (sum >= INF)
			sum -= INF;
	}
	return ans;
}
