		for (int j = 1; j <= m; j++)
		{
			v1.push_back(i);
			v2.push_back(j);
		}
	}
	LL ans = (solve(v1) + solve(v2)) * C(1LL * n * m - 2, k - 2) % INF;
	if (ans < 0) ans += INF;
	cout << ans << endl;
	return 0;
}

