const ll mod = static_cast<ll>(1e9 + 7);

ll mpow(ll a, ll n) {
	ll res = 1;
	while (n != 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

ll mfrac(ll a) {
	ll res = 1;
	for (ll i = 2; i <= a; ++i) res = res * i % mod;
	return res;
}

ll mcomb(ll n, ll k) {
	ll res;
	res = mfrac(n) * mpow(mfrac(k), mod - 2) % mod;
	res = res * mpow(mfrac(n - k), mod - 2) % mod;
	return res;
}


int main() {
	ll N, M, K;
