	for (ll i = 0; i < N * M; ++i) {
		cells.emplace_back(i / M, i % M);
	}

	ll ans = 0;
	ll cmb = mcomb(N * M - 2, K - 2);
	for (ll i = 0; i < N * M - 1; ++i) {
		for (ll j = i + 1; j < N * M; ++j) {
			ll dx = abs(cells[i].first - cells[j].first);
			ll dy = abs(cells[i].second - cells[j].second);
			ans += dx * cmb % mod;
			ans += dy * cmb % mod;
			ans %= mod;
		}
	}

	cout << ans << endl;
}

