mint modinv(mint n) {
  int a = n.n;
  int b = MOD;
  int s = 1;
  int t = 0;
  while (b != 0) {
    int q = a / b;
    a -= q * b;
    s -= q * t;
    swap(a, b);
    swap(s, t);
  }
  if (s < 0) s += MOD;
  return s;
}
mint operator/(mint a, mint b) { return a * modinv(b); }

mint f(mint n) {
  return n * (n + 1) / 2;
}

