// mod. m での a の逆元 a^{-1} を計算する
ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m;
    if (u < 0) u += m;
    return u;
}

ll ncm(ll n,ll m){
    ll ans = 1;
    rep(x,m){
        ans *= (n-x);
        ans %= MOD;
        ans *= modinv(m-x,MOD);
        ans %= MOD;
    }
    return  ans;
}

