long long getComb(int x, int y){
    //逆元を求める
    vector<long long> rep(x+1, 0);
    rep[1] = 1;
    for (int i = 2; i < x+1; i++){
        rep[i] = (mod - (mod / i)) * rep[mod % i] % mod;
    }
    //nCr
    vector<long long> c(x+1, 0);
    c[0] = 1;
    for (int i = 1; i < x + 1; i++){
        c[i] = c[i - 1] * ((x - i + 1) * rep[i] % mod) % mod;
        c[i] %= mod;
    }
    return c[y];
}

