		COUNT *= Comb(N * M - 2, K - 2);
		COUNT = COUNT % MOD;
		COUNT *= ((N - i) * Calc(M, 2)) % MOD;
		COUNT = COUNT % MOD;
		ANS += COUNT;
		ANS = ANS % MOD;
	}
	for (int i = 0; i <= M; i++) {
		long long COUNT = i;
		COUNT *= Comb(N * M - 2, K - 2);
		COUNT = COUNT % MOD;
		COUNT *= ((M - i) * Calc(N, 2)) % MOD;
		COUNT = COUNT % MOD;
		ANS += COUNT;
		ANS = ANS % MOD;
	}
	cout << ANS << endl;
}

