int comb(int N, int C) {
	const int NUM = 200009;
	int fact[200010], factr[200010], inv[200010];
	if (fact[0] == 0) {
		inv[1] = fact[0] = factr[0] = 1;
		for (int i = 2; i <= NUM; ++i) inv[i] = inv[mod % i] * (mod - mod / i) % mod;
		for (int i = 1; i <= NUM; ++i) fact[i] = fact[i - 1] * i%mod, factr[i] = factr[i - 1] * inv[i] % mod;
	}
	if (C<0 || C>N) return 0;
	return factr[C] * fact[N] % mod*factr[N - C] % mod;
}

