    long long comb = mComb(N * M - 2, K - 2, MOD);
    long long x = ((mRangeDiffSum(N, MOD) * mPow(M, 2, MOD)) % MOD * comb) % MOD;
    long long y = ((mRangeDiffSum(M, MOD) * mPow(N, 2, MOD)) % MOD * comb) % MOD;
    cout << (x + y) % MOD << endl;

    return 0;
}

