using namespace std;
constexpr int md = 1e9 + 7;
inline void mad (int &a, int b) {
	a += b; if (a >= md) a -= md;
}
inline void msb (int &a, int b) {
	a -= b; if (a < 0) a += md;
}
inline int vad (int a, int b) {
	mad(a, b); return a;
}
inline int vsb (int a, int b) {
	msb(a, b); return a;
}
inline int mul (int a, int b) {
	return (int)((long long)a * b % md);
}
inline int mow (int a, long long b) {
	int res = 1;
	for (; b; b >>= 1) {
		if (b & 1) res = mul(res, a);
		a = mul(a, a);
	}
	return res;
}
inline int inv (int a) {
	a %= md;
	if(a < 0) a += md;
	int b = md, u = 0, v = 1;
	while (a) {
		int t = b / a;
		b -= a * t; swap(a, b);
		u -= v * t; swap(u, v);
	}
	assert(b == 1);
	if(u < 0) u += md;
	return u;
}
struct factorials {
	const int sz;
	vector<int> fct, fnv;
	factorials (int n)
		: sz(n)
		, fct(n, 1)
		, fnv(n, 1)
		{
			for (int i = 1; i < n; i++) fct[i] = mul(fct[i - 1], i);
			fnv[n - 1] = inv(fct[n - 1]);
			for (int i = n - 1; i >= 1; i--) fnv[i - 1] = mul(fnv[i], i);
		}
	inline int binom (int n, int k) const {
		assert(0 <= k && k <= n && n < sz);
		return mul(fct[n], mul(fnv[k], fnv[n - k]));
	}
};
int solve (int h, int w, int k, factorials& fct) {
	int ret = 0, denom = 0;
	for (int i = 1; i < h; i++) {
		mad(ret, mul(i, h - i));
		mad(denom, i);
	}
	ret = mul(ret, mul(w, w));
	denom = mul(denom, mul(w, w));
	mad(denom, mul(h, fct.binom(w, 2)));
	ret = mul(ret, inv(denom));
	return ret;
}
int main() {
	cin.tie(0); cin.sync_with_stdio(false);
	int h, w, k;
	cin >> h >> w >> k;
	factorials fct(h * w + 1);
	int ret = 0;
	mad(ret, solve(h, w, k, fct));
	mad(ret, solve(w, h, k, fct));
	ret = mul(ret, fct.binom(k, 2));
	ret = mul(ret, fct.binom(h * w, k));
	cout << ret << endl;
	return 0;
}

