long long modpow(long long ori, long long po){
	long long res = 1;
	while(po > 0){
		if(po&1){
			res *= ori;
			res %= MOD;
		}
		ori *= ori;
		ori %= MOD;
		po >>= 1;
	}
	return res;
}

