	if(B == 0){
		return 1;
	}
	long long ans = kaidan[A];
	ans *= modpow(kaidan[B], MOD-2);
	ans %= MOD;
	ans *= modpow(kaidan[A-B], MOD-2);
	ans %= MOD;
	return ans;
}

