const int MOD = 1e9+7;

long long modpow(int a, int b){
	if(b == 0){
		return 1;
	}else if(b == 1){
		return a%MOD;
	}else if(b%2 == 0){
		long long x = modpow(a, b>>1);
		return x*x%MOD;
	}else{
		long long x = modpow(a, b>>1);
		return (x*x%MOD)*a%MOD;
	}
}

