        return !((*this)>a);
    }
    constexpr bool operator>=(const mint &a) noexcept{
        return !((*this)<a);
    }

    constexpr mint pow(ll t)const noexcept{
        if(t==0)return (mint)1;
        if(t%2==0){
            mint k=pow(t/2);
            return k*k;
        }else{
            if(t>0)return (*this)*pow(t-1);
