//二分累乗法
ll mult(ll n,ll m){//n^m%modを求める
    if(m==1){
        return n%mod;
    }else if(m%2==0){//オーバーフロー防止のためにn^(m/2)*n^(m/2)を考える
        ll t=mult(n,m/2);
        return (t*t)%mod;
    }else{//奇数の時はn^(m-1)*nを考える
        ll t=mult(n,m-1);
        return (t*n)%mod;
    }
}

//nCkの1e9+7における余り
template <class T>
T comb_mod(T n,T k){
    T ans=1;
    T r=min(k,n-k);
    FOR(i,n-r+1,n+1){
        ans*=(i%mod);
        ans%=mod;
    }
    FOR(i,1,r+1){
        ans*=mult(i,mod-2);
        ans%=mod;
    }
    return ans;
}

