    }
    reps(i, 1, n) {
            mint tmp = (mint)i * (n - i);
            tmp *= m * m;
            ans += tmp;
    }
    ans *= bc.combination(n * m - 2, k - 2);
    cout << ans.x << endl;
    return 0;
}

