		tmp %= mod;
		tmp *= m;
		tmp %= mod;
		tmp *= rui(n * m - 1, mod - 2, mod);
		tmp %= mod;
		res += tmp;
		res %= mod;
	}
	res *= rui(2, mod - 2, mod);
	cout << res%mod;
}

