		result = (result + i * (N - i) * M % MOD * M % MOD) % MOD;
	}
	for (auto i = 1; i < M; ++i)
	{
		result = (result + i * (M - i) * N % MOD * N % MOD) % MOD;
	}

	result = (result * calcCombination(N * M - 2, K - 2)) % MOD;
	cout << result << endl;

	return 0;
}

