long long int multiply(long long int a, long long int b) {
    return (a * b) % DVSR;
}

long long int power(long long int a, long long int b) {
    if (b == 0) return 1;
    if (b == 1) return a % DVSR;
    int s = power(a, b/2);
    int ss = multiply(s, s);
    if (b % 2 == 0) return ss;
    return multiply(ss, a);
}

long long int divide(long long int a, long long int b) {
    return multiply(a, power(b, DVSRA));
}

long long int choose(int n, int k) {
    if (k > n) return 0;
    if (k == 0) return 1;
    if (k > n / 2) return k = n - k;

    long long int x = 1;

    for (int i=1; i<=k; i++)
        x = divide(multiply(x, n-i+1), i);

    return x;
}

long long int f(int N, int M) {
    long long int sum = divide(
        + multiply(power(N, 3), power(M, 2))
        + multiply(power(N, 2), power(M, 3))
        - multiply(power(N, 2), power(M, 1))
        - multiply(power(N, 1), power(M, 2))
        , 6);
    return sum;
}

