ll combinationValue( ll n, ll k, ll mod )
{
	vector<ll> fac( n, 1 ), inv( n, 1 ), facInv( n , 1 );
	for( ll i = 2; i <= n; ++i )
	{
		fac[i] = fac[i - 1] * i % mod;
