// 割り算のための逆元を求める（mod m での a の逆元）
long long modinv(long long a, long long m) {
    long long b = m, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u;
}

/*
    順列と組み合わせ (P, C, H)
*/

class PCH {
    private:
        Factorial fact;

    public:
        PCH(long long n_max);
        long long P(long long n, long long r);
        long long C(long long n, long long r);
        long long H(long long n, long long r);
};
PCH::PCH(long long n_max) {
    fact.initialization(n_max);
}
long long PCH::P(long long n, long long r) {
    return fact.getFactorial(n) % MOD * modinv(fact.getFactorial(r), MOD) % MOD;
}

long long PCH::C(long long n, long long r) {
    return fact.getFactorial(n) % MOD * modinv(fact.getFactorial(r), MOD) % MOD * modinv(fact.getFactorial(n - r), MOD) % MOD;
}

long long PCH::H(long long n, long long r) {
    return C(n - 1 + r, r);
}

int main() {

    int N, M, K;
    cin >> N >> M >> K;

    long long int cost[N][M];

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            cost[i][j] = 0;
        }
    }

    // decide cost[0][0]
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < M; j++) {
            cost[0][0] += i + j;
        }
    }

    long long int totalCost = cost[0][0] % MOD;

    // decide cost[0][j]
    for (int j = 1; j < M; j++) {
        cost[0][j] = cost[0][j - 1] + N * (j - (M - j));
        totalCost = (totalCost + cost[0][j] % MOD) % MOD;
    }
    for (int i = 1; i < N; i++) {
        for (int j = 0; j < M; j++) {
            cost[i][j] = cost[i - 1][j] + M * (i - (N - i));
            totalCost = (totalCost + cost[i][j] % MOD) % MOD;
        }
    }

    totalCost = totalCost / 2;


    PCH pch(N * M);
    totalCost = (totalCost * pch.C(N * M, K)) % MOD;
    totalCost = (totalCost * pch.P(K, 2)) % MOD;
    totalCost = totalCost * modinv(N * M, MOD) % MOD;
    totalCost = totalCost * modinv(N * M - 1, MOD) % MOD;

    cout << totalCost << endl;

    return 0;
}

