ll BIG;

ll binpow(ll a, ll b) {
    ll res = 1;
    while (b > 0) {
        if (b & 1)
            res = res * a;
        res %= MOD;
        a = a * a;
        a %= MOD;
        b >>= 1;
    }
    return res;
}

ll inverse(ll n) {
    return binpow(n, MOD-2);
}


ll fact(ll n) {
    ll ans = 1;
    FOR(i, 1, n+1) {ans *= i; ans %= MOD;}
    return ans;
}

ll choose(ll n, ll k) {
    return fact(n) * inverse(fact(k)) % MOD * inverse(fact(n-k)) % MOD;
}

ll calc(ll N, ll M) {
    ll ans = 0;
    F0R(i, N - 1) {
        ll ED = (N - i);
        ans += ED * BIG % MOD * M % MOD * (N-i-1) % MOD * M % MOD;
    }
    return ans;
}
int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
    ll N, M, K; cin >> N >> M >> K;
    BIG = choose(N * M - 2, K - 2);
    ll ans = 0;
    ans += calc(N, M) / 2; ans %= MOD;
    ans += calc(M, N) / 2; ans %= MOD;
    cout << ans << endl;
}

