struct modCalc{
	static int mod;
	int n;
	bool ok;
	vector<int> fact,invfact;
	modCalc(){};
	modCalc(int _mod,int _n){
		mod=_mod,n=_n;
		ok=false;
	};
	void init(){
		fact.resize(n+1,1);
		for(int i=0;i<n;i++)fact[i+1]=fact[i]*(i+1)%mod;
		invfact.resize(n+1,1);
		invfact[n]=modinv(n);
		for(int i=n;i>1;i--)invfact[i-1]=invfact[i]*i%mod;
		ok=true;
	}

	int modpow(int x,int n,int m=-1){
		if(m==-1)m=mod;
		int ret=1;
		while(n>0){
			if(n&1)(ret*=x)%=m;
			(x*=x)%=m;
			n>>=1;
		}
		return ret;
	}

	int modinv(int x,int m=-1){
		if(m==-1)m=mod;
		return modpow(x,m-2,m);
	}

	int nCm(int x,int y){
		if(!ok)init();
		if(y==0)return 1;
		else return fact[x]*invfact[y]%mod*invfact[x-y]%mod;
	}
	int nPm(int x,int y=-1){
		if(y==-1)y=x;
		if(!ok)init();
		return fact[x]*invfact[x-y]%mod;
	}
};



