// Solve ax+by=gcd(a, b)
lint extgcd(lint a, lint b, lint &x, lint &y)
{
    lint d = a;
    if (b != 0)
        d = extgcd(b, a % b, y, x), y -= (a / b) * x;
    else
        x = 1, y = 0;
    return d;
}
// Calc a^(-1) (MOD m)
lint mod_inverse(lint a, lint m = MOD)
{
    lint x, y;
    extgcd(a, m, x, y);
    return (m + x % m) % m;
}
int main()
