    REP(i, M) ret += N * (M - 1 - i) % MOD * (M - i) % MOD * mod_inverse(2) % MOD * N % MOD;
    ret %= MOD;
    // dbg(ret);
    FOR(i, 1, K - 2 + 1)
    {
        ret = ret * mod_inverse(i) % MOD * ((N * M - 1 - i) % MOD) % MOD;
    }
    cout << ret << endl;
}

