    for(d=1;d<n;d++) x=(x+(((d*(nn-d)%MOD)*mm%MOD)*mm%MOD))%MOD;
    for(d=1;d<m;d++) y=(y+(((d*(mm-d)%MOD)*nn%MOD)*nn%MOD))%MOD;
    cout << ((x+y)%MOD)*z%MOD << endl;
}

