ll arith(int n){
	return (n * (n+1))/2;
}
ll comp(int N, int M){
	ll sum = 0;
	for(int i = 1; i <= N; i++){
		for(int j = 1; j <= M; j++){
			sum += (M * (arith(i-1) + arith(N-i)));
			sum += (N * (arith(j-1) + arith(M-j)));
		}
	}
	return sum/2;
}
long long C(int a, int b) {
  long long top = 1, bot = 1;
  for (int i = 0; i < b; ++i) {
    top = top * (a - i) % mod;
    bot = bot * (b - i) % mod;
  }

  long long binpow = mod - 2, botinv = 1;
  while (binpow) {
    if (binpow & 1)
      botinv = botinv * bot % mod;
    bot = bot * bot % mod;
    binpow >>= 1;
  }
  return (top * botinv) % mod;
}
