const i64 mod = 1e9+7LL;

int main(){
    i64 N, M, K;
    cin >> N >> M >> K;
    i64 ret = 0;
    i64 C = 1;
    if(K != 2){
        auto pow = [&](i64 a, i64 r){
            i64 ret = 1LL;
            while(r){
                if(r&1LL)ret = ret * a % mod;
                a = a * a % mod;
                r >>= 1;
            }
            return ret;    
        };
        for(i64 i=1;i<=K-2;i++){
            C = C * (N * M - 1 - i) % mod;
            C = C * pow(i, mod-2) % mod;
        }
    }
    for(i64 s = 1LL;s <= N + M - 1LL;s++){
        for(i64 i = 0LL;i <= s;i++){
            i64 j = s - i;
            i64 n = max((i64)N - i, (i64)0LL);
            i64 m = max((i64)M - j, (i64)0LL);
            if(!n||!m)continue;
            i64 k = n * m % mod;
            if(i!=0 && i!=s)k = k * 2 % mod;
            ret += k * s % mod * C % mod;
            ret %= mod;
            // cerr << s << " " << i << " " << k << endl;
        }
    }
    // cerr << C << endl;
    cout << ret << endl;
