class Combi {
  private:
    v(ll) fac, inv, finv;

    void init(ll N) {
      fac[0] = fac[1] = 1; inv[1] = 1; finv[0] = finv[1] = 1;

      for (ll i = 2; i < N; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
      }
    }

  public:
    Combi(ll N) : fac(N + 1), inv(N + 1), finv(N + 1) { init(N + 1); }

    int Cmod(ll n, ll k) {
      if (n < k) return 0;
      if (n < 0 || k < 0) return 0;
      return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
    }

    ll Pmod(ll n, ll k) {
      if (n < k) return 0;
      if (n < 0 || k < 0) return 0;
      return fac[n] * finv[n - k] % MOD;
    }
  };

