class Combination {
private:
    const int N;
    const lint MOD;
    std::vector< lint > fact, inv;

    lint powmod(lint x, lint k) {
        lint res = 1;
        while (k) {
            if (k&1) res = (res * x) % MOD;
            x = (x * x) % MOD;
            k >>= 1;
        }
        return res;
    }

    void precomputation() {
        fact[0] = fact[1] = 1;
        for (int i=2; i<=N; ++i) fact[i] = (fact[i-1] * i) % MOD;
        for (int i=0; i<=N; ++i) inv[i] = powmod(fact[i], MOD-2);
    }

public:
    Combination(int N_, lint MOD_) : N(N_), MOD(MOD_), fact(N_), inv(N_) {
        precomputation();
    }

    lint compute(int n, int k, bool duplicate = false) {
        if (duplicate) return compute(n+k-1, k);
        if (k == 0) return 1;
        if (n < k) return 0;
        lint res = fact[n];
        res = (res * inv[n-k]) % MOD;
        res = (res * inv[k]) % MOD;
        return res;
    }
};

int main() {
    int N, M, K;
    cin >> N >> M >> K;

    const lint MOD = lint(1e9) + 7;
    Combination comb(N * M, MOD);

    auto func = [&](int X, int Y) {
        lint ret = 0;
        for_(d,1,X) {
            lint a = ((X - d) * Y * Y) % MOD;
            lint b = comb.compute(N * M - 2, K - 2);
            lint add = (a * b) % MOD;
            add = (d * add) % MOD;
            ret = (ret + add) % MOD;
        }
        return ret;
    };

    lint ans = (func(N, M) + func(M, N)) % MOD;
    cout << ans << endl;
}

