	long long int ans = 0;
	for (int i = 1; i <= N * M; i++) {
		by[i] = by[i - 1] * i;
		by[i] %= MOD;
		rev[i] = power(by[i], MOD - 2, MOD);
	}
	for (int i = 0; i < N; i++) {
		long long int box = 1LL * i * (i + 1) / 2;
		box *= M;
		box %= MOD;
		box *= M;
