long long mod_pow(long long a, long long b)
{
  if (b == 0) return 1;
  long long ret = mod_pow(a, b/2);
  ret = ret * ret % MOD;
  if (b % 2 == 1) ret = a * ret % MOD;
  return ret;
}

long long comb(long long a, long long b)
{
  if (b > a - b) return comb(a, a - b);

  long long num = 1;
  long long denom = 1;

  for (int i = 1; i <= b; i++) {
    num = num * (a - i + 1) % MOD;
    denom = denom * i % MOD;
  }

  return num * mod_pow(denom, MOD-2) % MOD;
}

