    Combination comb(N * M, MOD);

    auto func = [&](int X, int Y) {
        lint ret = 0;
        for_(d,1,X) {
            lint a = ((X - d) * Y * Y) % MOD;
            lint b = comb.compute(N * M - 2, K - 2);
            lint add = (a * b) % MOD;
            add = (d * add) % MOD;
            ret = (ret + add) % MOD;
        }
        return ret;
    };

    lint ans = (func(N, M) + func(M, N)) % MOD;
    cout << ans << endl;
}

