// fact(n)%MOD, invFact(n)%MOD, inv(n)%MOD, nCk
// Constructor O(N)
// other O(1)
template<typename T>
class Choose {
public:
	vector<T> fact, inv, invFact;

	Choose(T N):fact(N), inv(N), invFact(N){
		inv[1] = 1;
		FOR(i, 2, inv.size()) inv[i] = MOD - (MOD / i) * inv[MOD%i] % MOD;
		fact[0] = invFact[0] = 1;
		FOR(i, 1, fact.size()) {
			fact[i] = fact[i - 1] * i % MOD;
			invFact[i] = (invFact[i - 1] * inv[i]) % MOD;
		}
	}

	//Get nCk
	T operator () (T n, T k) const {
		if (not ((T)0 <= k and k <= n)) return 0;
		return (((fact[n] * invFact[k]) % MOD)*invFact[n - k]) % MOD;
	}
};

mint solve(int N, int M){
	mint su = 0;
	mint memo = 0;
	// O(N)
	REP(i, M) {
		memo += i;
		su += memo;
	}
	su *= N*N;
	return su;
}

void solve() {
	int N, M, K; cin >> N >> M >> K;
	Choose<int> choose(N*M+1);
	mint res = 0;
	res += solve(N, M);
	res += solve(M, N);
	res *= choose(N * M-2, K - 2);
	cout << res << endl;
}

