void solve(long long N, long long M, long long K){
  mint ans = 0;
  for(ll d = 1; d <= N+M-2; d++){
    dump(d);
    ll cnt = 0;
    for(ll X=1;X<=N;X++){
      for(ll Y=1;Y<=M;Y++){
        ll mi = max(X+1,X+Y+d-M); 
        ll ma = min(X+d,N);
        dump(X,Y,mi,ma);
        if(mi>ma) continue;
        cnt += ma-mi+1;
      }
    }
    dump(d,cnt);
    ans += mint(cnt)*mint(d);
  }
  swap(N,M);
