    public:
        Factorial();
        Factorial(ll n_max);
        void initialization(ll n_max);
        ll getFactorial(ll n);
};

Factorial::Factorial() {}
Factorial::Factorial(ll n_max) {
    fac.clear();
    fac.push_back(1);
    fac.push_back(1);
    for (ll i = 2; i <= n_max; i++) {
        fac.push_back(fac[i-1] * i % MOD);
    }
}
void Factorial::initialization(ll n_max) {
    fac.clear();
    fac.push_back(1);
    fac.push_back(1);
    for (ll i = 2; i <= n_max; i++) {
