}

/*
  MOD計算
*/
// 割り算のための逆元を求める（mod m での a の逆元）
ll modinv(ll a, ll m) {
    ll b = m, u = 1, v = 0;
    while (b) {
        ll t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= m; 
    if (u < 0) u += m;
    return u % m;
}

/*
    順列と組み合わせ (P, C, H)
*/

class PCH {
    private:
        Factorial fact;

    public:
        PCH(ll n_max);
        ll P(ll n, ll r);
        ll C(ll n, ll r);
        ll H(ll n, ll r);
};
PCH::PCH(ll n_max) {
    fact.initialization(n_max);
}
ll PCH::P(ll n, ll r) {
    return fact.getFactorial(n) % MOD * modinv(fact.getFactorial(n - r), MOD) % MOD;
}

ll PCH::C(ll n, ll r) {
    return fact.getFactorial(n) % MOD * modinv(fact.getFactorial(r), MOD) % MOD * modinv(fact.getFactorial(n - r), MOD) % MOD;
}

ll PCH::H(ll n, ll r) {
    return C(n - 1 + r, r);
}

ll sum(ll i) {
  ll ans = (1 + i) * i / 2;
  ans %= MOD;
  return ans;
}

int main() {

