  PCH pch(N * M);

  ll ans = 0;

  for (int i = 1; i <= N; i++) {
    for (int j = 1; j <= M; j++) {
      ans += M * (sum(i - 1) + sum(N - i)) % MOD;
      ans += N * (sum(j - 1) + sum(M - j)) % MOD;
      ans %= MOD;
    }
  }

  ans *= pch.C(N * M - 2, K - 2);
  ans %= MOD;

  ans *= modinv(2, MOD);
  ans %= MOD;

  cout << ans << endl;

  return 0;
}

