class Solve
{
  ll n, m, k;

public:
  Solve(ll n, ll m, ll k) : n{n}, m{m}, k{k}
  {
  }

  mint answer()
  {
    mint ans{0};
    for (auto j{0LL}; j < m; ++j)
    {
      ans += j * (j + 1) / 2;
    }
    ans *= mint{n} * n * C(n * m - 2, k - 2);
    return ans;
  }

private:
};

