long long int fc(long long int c, long long int k) {
	const int mod = 1000000007;
	long long int res = 1;
	for (int i = 1; i <= k; i++) {
		res = res * (c - i + 1) / i % mod;
	}
	return res;
}

int main(int argc, char *argv[]) {
	long long int n, m, k;
	cin >> n >> m >> k;	
	long long int res = 0;
	const int mod = 1000000007;
	long long int combination = fc(m * n - 2, k - 2);

	for (int i = 0; i < n; i++) {
		for (int j = 0; j < m; j++) {
			long long int t = 0;
			t = (i * i + i - n * i + (n * n - n) / 2);
			t %= mod;
			t *= m;
			t %= mod;
			res += t;
			res %= mod;

			t = (j * j + j - m * j + (m * m - m) / 2) % mod;
			t *= n;
			t %= mod;
			res += t;
			// cout << res << " ";
		}
	}

		res /= 2;
	res *= combination;
	res %= mod;
	cout << res << endl;
}

