    B = (B*M)%MOD;
    B = (B*(N-1))%MOD;
    B = (B*N)%MOD;
    B = (B*(N+1))%MOD;

    // 前処理
    COMinit();

    ll C = COM(N*M-2, K-2) % MOD;

