ll MOD = 1e9+7;
ll powMod(ll a, ll b) { // a^b mod M
    ll ans = 1; ll temp = a;
    while (b > 0) {
        if ( b % 2 == 1 ) ans = (ans * temp) % MOD;
        temp = (temp * temp) % MOD;
        b = b / 2;
    }
    return ans;
}
ll nCkMod(ll n, ll k) { // nCk mod M
    ll ans = 1, temp = 1, mink = min(k, n-k);
    for (ll i = 0; i < mink; i++) {
        ans = (ans * (n - i)) % MOD;
    }
    for (ll i = 0; i < mink; i++) {
        temp = (temp * (i + 1)) % MOD;
    }
    return (ans * powMod(temp, MOD - 2)) % MOD;
}


