// finding the distance between all pair of points in O(nlogn)
ll dist(){
	ll ans = 0;
	vector<int> x,y;
	FOR(i,1,n+1) FOR(j,1,m+1) x.pb(i);
	FOR(i,1,m+1) FOR(j,1,n+1) y.pb(i);

	ll prev_sum = 0;
	FOR(i,1,x.size()){
		ans += (x[i]-x[i-1])*i + prev_sum;
		prev_sum += (x[i]-x[i-1])*i;
	}

	prev_sum = 0;
	FOR(i,1,y.size()){
		ans += (y[i]-y[i-1])*i + prev_sum;
		prev_sum += (y[i]-y[i-1])*i;
	}

	return ans;
}

