ll qexp(ll A, ll B) {
    if (B == 0) return 1;
    ll half = qexp(A, B / 2);
    (half *= half) %= MOD;
    if (B % 2) (half *= A) %= MOD;
    return half;
}

void precompute() {
    fact[0] = invf[0] = 1;
    for (int i = 1; i < MAX_N; i++) {
		fact[i] = fact[i - 1] * i % MOD;
		invf[i] = qexp(fact[i], MOD - 2);
	}
}

ll nCk(int n, int k) {
    if (k < 0 || k > n) return 0;
	return fact[n] * invf[k] % MOD * invf[n - k] % MOD;
}

