    inline mint<MOD> operator + (mint<MOD> other) const { int32_t c = this->value + other.value; return mint<MOD>(c >= MOD ? c - MOD : c); }
    inline mint<MOD> operator - (mint<MOD> other) const { int32_t c = this->value - other.value; return mint<MOD>(c <    0 ? c + MOD : c); }
    inline mint<MOD> operator * (mint<MOD> other) const { int32_t c = (int64_t)this->value * other.value % MOD; return mint<MOD>(c < 0 ? c + MOD : c); }
    inline mint<MOD> & operator += (mint<MOD> other) { this->value += other.value; if (this->value >= MOD) this->value -= MOD; return *this; }
    inline mint<MOD> & operator -= (mint<MOD> other) { this->value -= other.value; if (this->value <    0) this->value += MOD; return *this; }
    inline mint<MOD> & operator *= (mint<MOD> other) { this->value = (int64_t)this->value * other.value % MOD; if (this->value < 0) this->value += MOD; return *this; }
    inline mint<MOD> operator - () const { return mint<MOD>(this->value ? MOD - this->value : 0); }
    mint<MOD> pow(uint64_t k) const {
        mint<MOD> x = *this, y = 1;
        for (; k; k >>= 1) {
            if (k & 1) y *= x;
            x *= x;
        }
        return y;
    }
    mint<MOD> inv() const { return pow(MOD - 2); }  // MOD must be a prime
    inline mint<MOD> operator /  (mint<MOD> other) const { return *this *  other.inv(); }
    inline mint<MOD> operator /= (mint<MOD> other)       { return *this *= other.inv(); }
    inline bool operator == (mint<MOD> other) const { return value == other.value; }
    inline bool operator != (mint<MOD> other) const { return value != other.value; }
};
template <int32_t MOD> mint<MOD> operator * (int64_t value, mint<MOD> n) { return mint<MOD>(value) * n; }
template <int32_t MOD> mint<MOD> operator * (int32_t value, mint<MOD> n) { return mint<MOD>(value % MOD) * n; }
template <int32_t MOD> ostream & operator << (ostream & out, mint<MOD> n) { return out << n.value; }

int fact_unpack(const char *s) {
    int n = 0;
    REP_R (i, 5) {
        n *= 64;
        n +=
            'a' <= s[i] ? s[i] - 'a' + 26 :
            'A' <= s[i] ? s[i] - 'A' :
            '0' <= s[i] ? s[i] - '0' + 52 :
            s[i] == '+' ? 62 : 63;
    }
    return n;
}
/**
 * @return n! mod MOD
 * @note O(w), for the embedding width w = 100000
 */
int fact(int64_t n) {
    constexpr int MOD = 1e9 + 7;
    constexpr int width = 100000;
    static const char *table = // {{{
        ""
    ;  // }}}
    assert (0 <= n);
    if (n >= MOD) return 0;
    int64_t acc = fact_unpack(&table[n / width * 5]);
    int init = n / width * width;
    for (int i = max(1, init); i <= n; ++ i) {
        acc = acc * i % MOD;
    }
    return acc;
}

mint<1000000007> choose(int64_t n, int64_t r) {
    constexpr int MOD = 1e9 + 7;
    assert (0 <= r and r <= n);
    if (n / MOD > (n - r) / MOD + r / MOD) {
        return 0;
    } else {
        return mint<MOD>(fact(n % MOD)) * mint<MOD>(fact((n - r) % MOD)).inv() * mint<MOD>(fact(r % MOD)).inv();
    }
}


constexpr int MOD = 1e9 + 7;

mint<MOD> solve(ll h, ll w, ll k) {
    mint<MOD> acc = 0;
    REP (y, h) {
        acc += mint<MOD>(y) * (y + 1) / 2 * w * w;
    }
    REP (x, w) {
        acc += mint<MOD>(x) * (x + 1) / 2 * h * h;
    }
    return acc * choose(h * w - 2, k - 2);
}

int main() {
    ll n, m, k; cin >> n >> m >> k;
    cout << solve(n, m, k).value << endl;
    return 0;
}

