#define DVSR  1'000'000'007
#define DVSRA 1'000'000'005

long long int multiply(long long int a, long long int b) {
    return (a * b) % DVSR;
}

long long int power(long long int a, long long int b) {
    if (b == 0) return 1;
    if (b == 1) return a % DVSR;
    int s = power(a, b/2);
    int ss = multiply(s, s);
    if (b % 2 == 0) return ss;
    return multiply(ss, a);
}

long long int divide(long long int a, long long int b) {
    return multiply(a, power(b, DVSRA));
}

long long int choose(int n, int k) {
    if (k > n) return 0;
    if (k == 0) return 1;
    if (k > n / 2) return k = n - k;

    long long int x = 1;

    for (int i=1; i<=k; i++) {
        x = multiply(x, n-i+1);
        x = divide(x, i);
    }

    return x;
}

int main() {
    int N; // # of rows
    int M; // # of columns
    int K; // # of pieces
    std::cin >> N >> M >> K;

    // Bounds
    assert(2 <= N * M && N * M <= 200'000); // the grid size
    assert(2 <= K && K <= N * M);           // # of piece

    long long int sum = 0;

    auto abs = [](int x) { return x > 0 ? x : -x; };

    for (int ai=1; ai<=N; ai++)
        for (int aj=1; aj<=M; aj++)
            for (int bi=ai; bi<=N; bi++)
                for (int bj=1; bj<=M; bj++) {
                    if (bi <= ai && bj <= aj) continue;
                    sum = (sum + abs(ai - bi) + abs(aj - bj)) % DVSR;
                }

    long long int d = choose(N * M - 2, K - 2);
    sum = (sum * d) % DVSR;

    std::cout << sum << std::endl;

    return 0;
}

