{
    gt[0] = 1;
    for (int i = 1; i <= maxn; i++)
        gt[i] = (gt[i - 1] % MOD * i % MOD) % MOD;
}

int64_t SumX()
{
    int64_t s = 0;
    for (int i = 1; i <= m; i++)
    {
        int64_t l = i - 1, r = m - i;
        s = (s + l * i - r * i) % MOD;
    }
    s = (s % MOD * Pow(n, 2)) % MOD;
    return s;
}

int64_t SumY()
{
    int64_t s = 0;
    for (int i = 1; i <= n; i++)
    {
        int64_t l = i - 1, r = n - i;
        s = (s + l * i - r * i) % MOD;
    }
    s = (s % MOD * Pow(m, 2)) % MOD;
    return s;
}

void Solve()
{
    cout << ((SumX() + SumY()) % MOD * Comb(m * n - 2, k - 2)) % MOD;
}

