int solve(int n, int m)
{
	int ans = 0;
	int w = 0;
	for(int b = 1; b <= n; b++) w = (w + 1ll * b * (k - b) % mod * C(n * (m - 1), k - b) % mod * C(n, b)) % mod;
	for(int a = 1; a <= m; a++)
	{
		int P = 1ll * Inv[m - 1] * (a - 1 - (m - a) + mod) % mod;
		ans = (ans + 1ll * w * P % mod * a) % mod;
	}
	return ans;
}

