ll pow_mod(ll n, ll p)
{
    ll ret = 1;
    ll wk_n = n;
    ll wk_p = p;
    while (wk_p > 0)
    {
        if (wk_p % 2 == 0)
        {
            wk_n *= wk_n;
            wk_p /= 2;
            wk_n %= mod;
        }
        else
        {
            ret *= wk_n;
            wk_p--;
            ret %= mod;
        }
    }
    return ret;
}

ll cmb_mod(ll n, ll k)
{
    ll ret = 1;
    for (ll i = 1; i <= k; i++)
    {
        ret *= (n - i + 1);
        ret %= mod;
        ret *= pow_mod(i, mod - 2);
        ret %= mod;
        if (ret < 0)
        {
            ret += mod;
        }
    }
    return ret;
}

