array<ll,2> inv(ll a,ll m){
    array<ll,2> val;
    a=a%m;
    if(a==1){
        val[0]=1;
        val[1]=0;
    }else{
        array<ll,2> hoge;
        ll k=m/a,mm=m%a;
        hoge=inv(mm,a);
        val[1]=hoge[0]-k*a;
        val[0]=hoge[1]-k*hoge[0]+k*m;
    }
    if(val[0]>m-1){
        ll n=val[0]/m;
        val[0]=val[0]%m;
        val[1]=val[1]+n*a;
    }
    return val;
}

ll comb(ll a,ll b,ll m){
    if(b==0) return 1;
    if(b==1) return a%m;
    return ((((a%m)*inv(b,m)[0])%m)*comb(a-1,b-1,m))%m;
}


