ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  ll ret = fact[n];
  ret = (ret*rfact[r]) % M;
  ret = (ret*rfact[n - r]) % M;
  return ret;
}

ll solve (ll h, ll w, ll k) {
  ll rn = h * (w - 1);
  ll rs = (h * (w - 1) * w / 2) % MOD;

  ll res = 0;
  rep (j, w) {
    res = (res + rs) % MOD;
    rs -= rn;
    rn -= h;
  }
  res = res * h % MOD;
  (res *= nCr(h*w - 2, k - 2)) %= MOD;
  return res % MOD;
}

