	ans += mint(1) * M * M * (N - 1) * N * (N + 1) / 6;
	ans += mint(1) * N * N * (M - 1) * M * (M + 1) / 6;
	ans *= Factorial()(N*M - 2, K - 2);

	cout << ans << "\n";

	return 0;
}

