ll n, m, k;
ll fact[500000];
ll revfact[500000];

long long cnk(long long n, long long k)
{
    return fact[n] * revfact[k] % MOD * revfact[n - k] % MOD;
}

signed main()
{
    ios_base::sync_with_stdio();
    cin.tie(0);
    cout.tie(0);
    cin >> n >> m >> k;
    fact[0] = 1;
    for (int i = 1; i <= 200000; i++)
    {
        fact[i] = fact[i - 1] * i % MOD;
        revfact[i] = inq(fact[i], MOD - 2, MOD);
    }
    revfact[0] = 1;
    long long ans = 0;
    for (int di = - n + 1; di <= n - 1; di++)
    {
        for (int dj = - m + 1; dj <= m - 1; dj++)
        {
            if (di == 0 && dj == 0) continue;
            int rav = abs(di) + abs(dj);
            int cnt = (n - abs(di)) * (m - abs(dj));
            ans += rav * cnt % MOD * cnk(n * m - 2, k - 2);
            ans %= MOD;
        }
    }
    ans = ans * revfact[2] % MOD;
    cout << ans;
}

