const ll MOD=1000000007;
const ll INF=0x3f3f3f3f;

ll fac[MAXn],inv[MAXn];
ll fpow(ll a,ll b){
    ll ret = 1;
    while (b) {
        if (b&1) ret = (ret * a) % MOD;
        a = (a * a) % MOD;
        b >>= 1;
    }
    return ret;
}
void init(){
    fac[0] = inv[0] = 1;
    REP1 (i,MAXn-1) fac[i] = (fac[i-1] * i) % MOD;
    REP1 (i,MAXn-1) inv[i] = fpow(fac[i],MOD-2);
}
ll C(ll a,ll b){
    if (b == 0) return 1;
    return fac[a] * inv[b] % MOD * inv[a-b] % MOD;
}
int main(){
