    REP1 (i,n-1) ans = (ans + (n-i) * i % MOD * m % MOD * m % MOD) % MOD;
    REP1 (i,m-1) ans = (ans + (m-i) * i % MOD * n % MOD * n % MOD) % MOD;
    ans = (ans * C(n*m-2,k-2)) % MOD;
    assert(ans > 0);
    cout << ans << endl;
}

