const int max_comb=250000;
vector<ll> fac(max_comb+1); //n! (mod M)
vector<ll> ifac(max_comb+1); //k!^(-1) (mod M)

ll mpow(ll x, ll n){ //x^n(mod M)
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll minv(ll x){
    return mpow( x, MOD-2 );
}

ll comb(int a, int b){     // C(a,b) = a! * b!^(-1) * (a-b)^(-1)
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

ll perm(int a, int b){     // P(a,b) = a! * (a-b)!^(-1)
    if(b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b] % MOD;
    return tmp * fac[a] % MOD;
}

void pre_comb()
{
    fac[0] = 1;
    ifac[0] = 1;
    for(int i = 0; i<max_comb; i++){
        fac[i+1] = fac[i]*(i+1) % MOD; // n!(mod M)
        ifac[i+1] = ifac[i]*minv(i+1) % MOD; // k!^(-1) (mod M)
    }
    return;
}


ll func(int n, int m, int K)
{
    ll ans = 0;

    int k;
    for(k=1; k<=n-1; k++) {
        ll ans0 = (ll)k*(n-k)*m %MOD *m %MOD *comb(n*m-2,K-2) %MOD;
        ans = (ans + ans0)%MOD;
    }

    return ans;
}

int main(int argc, char* argv[])
{
    int n,m,K;
    scanf("%d%d%d", &n, &m, &K);

    pre_comb();

    ll ans0 = func(n, m, K);
    ll ans1 = func(m, n, K);

    printf("%lld\n", (ans0+ans1)%MOD);

    return 0;
}

