int nCrModPFermat(int n, int r, int p) 
{ 
   if (r==0) 
      return 1; 
    int fac[n+1]; 
    fac[0] = 1; 
    for (int i=1 ; i<=n; i++) 
        fac[i] = fac[i-1]*i%p; 

    return (fac[n]* modInverse(fac[r], p) % p * 
            modInverse(fac[n-r], p) % p) % p; 
} 
int distancesum(int arr[], int n) 
{ 
    sort(arr, arr + n); 
    int res = 0, sum = 0; 
    for (int i = 0; i < n; i++) 
    { 
        res += ((arr[i] * i - sum)%mod+mod)%mod; 
        sum += arr[i]; 
        sum%=mod;
    } 
    return res; 
} 
