Comb<mod, 200005> com;
long long solve(int rows, int columns) {
	ll ans = 0;

	for (int i = 1; i < columns; ++i) {
		ans = (ans + i * static_cast<ll>(rows) * (static_cast<ll>(columns) - i) % mod * rows % mod) % mod;
	}

	ans = ans * com.C(n * m - 2, k - 2) % mod;

	return ans;
}

