            if (i - j > n || j > m)
                continue;

            (s += max(0ll, n - (i - j)) * max(0ll, m - j) % MOD * 2 % MOD * i % MOD) %= MOD;
        }

        (res += s) %= MOD;
    }

    (res *= t) %= MOD;

    cout << res << endl;

    return 0;
}

