ll choose(int n, int i){
    ll numerator = 1, denominator = 1;
    for (int j = 0; j < i; j++){
        numerator *= (n - j);
        denominator *= (j + 1);
        numerator %= mod;
        denominator %= mod;
    }
    ll nci = numerator * pow(denominator, mod - 2);
    return nci % mod;
}

