// テーブルを作る前処理
void COMinit() {
    fac[0] = fac[1] = 1;
    finv[0] = finv[1] = 1;
    inv[1] = 1;
    for (int i = 2; i < MAX; i++){
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = mod - inv[mod % i] * (mod / i) % mod;
        finv[i] = finv[i - 1] * inv[i] % mod;
    }
}
// 二項係数計算
ll COM(int n, int k) {
    if (n < k) return 0;
    if (n < 0 || k < 0) return 0;
    return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
}

ll k;
mint calc(ll n, ll m) {
  mint tmp = COM(n * m - 1, k - 1);
  tmp *= k - 1;
  tmp *= n;

  rep3(i, 1, k + 1) {
    tmp -= (mint)COM(n, i) * COM(n * m - n, k - i) * 2 * COM(i, 2);
  }

  mint ans = 0;
  rep3(x, 1, m + 1) {
    ans += tmp * (x - 1) * modpow(m - 1, mod - 2, mod) * x;
    ans -= tmp * (m - x) * modpow(m - 1, mod - 2, mod) * x;
  }
  return ans;
}
