    REP1(d, N-1) {
        int add = d*(N-d) % MOD;
        (add *= M*M)%=MOD;
        (ans += add)%=MOD;
    }
    REP1(d, M-1) {
        int add = d*(M-d) % MOD;
        (add *= N*N)%=MOD;
        (ans += add)%=MOD;
    }
    (ans *= COM(N*M-2,K-2))%=MOD;
    cout << ans << endl;
}

