			LL num = n - len;
			ans += co(n * m - 2, k - 2) * m * m * len * num; 
		}
		FOR(len, 1, m) {
			LL num = m - len;
			ans += co(n * m - 2, k - 2) * n * n * len * num; 
		}
		cout << ans << endl;
	}
	return 0;
}

