        // iより上
        a += i * (i + 1) / 2 * (distX - 1);
        a %= MOD;

        // x方向の計算
        a += distX * (distX - 1) / 2 * H;
        a %= MOD;
      }
    }

    ll b = mod_comb(H * W - 2, K - 2, MOD);

    cout << (a * b) % MOD << endl;
  }
