ll  fact[100010];
ll rfact[100010];
void c3_init(ll m) {
    fact[1] = rfact[1] = 1;
    for (ll i = 2; i < 100010; i++) {
        fact[i] = (fact[i-1]*i)%m;
        rfact[i] = minverse(fact[i], m);
    }
}

ll c3(ll n, ll k, ll m) {
    if (n < k || n<0 || k<0)
        return 0;
    else if (n == k || k == 0)
        return 1;
    else
        return (((fact[n] * rfact[k])%m) * rfact[n-k])%m;
}

const ll MOD=1000000009;

// Xについてのみとく。あとで、NとMを入れ替えればYについても計算できる
//
// sigma_全ての組み合わせ sigma_i sigma_j |x_i - x_j| 
// => sigma_i sigma_j sigma_全ての組み合わせ |x_i - x_j| 
ll f(ll n, ll m, ll k){
    ll t = 0;
    for (ll len=1; len<n; len++){ // ある2点を決める。その時の長さをlenとする
        t += (len * (n-len))%MOD;
        t %= MOD;
    } 
    t *= c3(n*m-2, k-2, MOD); // 残りk-2は自由に選ぶ
    t %= MOD;
    t *= (m * m) % MOD; // yについては2点とも自由に選べる
    t %= MOD;
    return t;
}

