template<class T> struct ov : std::vector<optional<T>, std::allocator<optional<T> >> {
    optional<T> emp;
    ov(int i, int v = 0) : std::vector<optional<T>, std::allocator<optional<T> >>(i, v) {}
    ov(const vector<T>& rhs) : std::vector<optional<T>, std::allocator<optional<T> >>(rhs.begin(), rhs.end()) {}
