//        (*this) = ov<T>(rhs);
//    }
    optional<T> &operator()(int i) {        if (i < 0 || (*this).size() <= i) {            emp.reset();            return emp;        } else {            return std::vector<optional<T>, std::allocator<optional<T> >>::operator[](i);        }    }
    optional<T> &operator()(const optional<T>& i){
        if(i.has_value())return operator()(i.value());
        else{
            emp.reset();
            return emp;
        }
    }
