template<class T> struct ovv : std::vector<vector<optional<T>>, std::allocator<vector<optional<T>> >> {
    optional<T> emp = nullopt;
    ovv(int i, int j, int v = 0) : std::vector<vector<optional<T>>, std::allocator<vector<optional<T>> >>(i, vector<optional<T>, allocator<optional<T>>>(j, v)) {}
    optional<T> &operator()(int i, int j) {        if (i < 0 || j < 0 || (*this).size() <= i || ((*this)[i]).size() <= j) {            emp.reset();            return emp;        } else {            return (*this)[i][j];        }    }
