    long long Ans = 0;
    long long Stan = ( ( ( Fact[N * M - 2] * InvFact[k - 2] ) % Mod ) * InvFact[N * M - k] ) % Mod; 
    long long row , col;

    for( i = 1 ; i <= N ; ++i ){
        for( j = 1 ; j <= M ; ++j ){
            row = ( M * ( ( ( ( ( i - 1LL ) * i ) / 2LL ) % Mod + ( ( ( N - i ) * ( N - i + 1LL ) ) / 2LL ) % Mod ) % Mod ) ) % Mod;
            col = ( N * ( ( ( ( ( j - 1LL ) * j ) / 2LL ) % Mod + ( ( ( M - j ) * ( M - j + 1LL ) ) / 2LL ) % Mod ) % Mod ) ) % Mod;
            Ans = ( Ans + row + col ) % Mod;
        }
    }

    Ans = ( Ans * Stan ) % Mod; 
