void gener()
{
    fct[0] = ivf[0] = 1;
    fct[1] = ivf[1] = inv[1] = 1;
    for (int i = 2; i <= m * n; i++)
    {
        fct[i] = fct[i - 1] * i % MOD;
        inv[i] = MOD - MOD / i * inv[MOD % i] % MOD;
        ivf[i] = ivf[i - 1] * inv[i] % MOD;
    }
}

void solve()
{
    for (int i = 1; i <= max(m, n); i++)
    {
        c[i] = (c[i - 1] + (i - 1)) % MOD;
        d[i] = (c[i] + d[i - 1]) % MOD;
    }
    ans += d[m] * n % MOD * n % MOD;
    ans += d[n] * m % MOD * m % MOD;
}

