        acc_x += i * (M - i);
    }
    acc_x *= N;
    acc_x *= N;
    acc_x *= mint(c->com(N * M - 2, K - 2));

    mint acc = acc_x + acc_y;
    cout << acc.x << endl;

    delete(c);
    return 0;
}

