            ll tmpx = (1 + N - i) * (N - i) / 2 % MOD;
            tmpx = (tmpx * M * num) % MOD;
            sum = (sum + tmpx) % MOD;

            ll tmpy = (1 + M - j) * (M - j) / 2 % MOD;
            tmpy = (tmpy * N * num) % MOD;
            sum = (sum + tmpy) % MOD;
        }
    }
    cout << sum << endl;
}

