  }

  long long int ans = 0;
  for(int ii=0; ii<N; ii++){
    for(int jj=0; jj<M; jj++){
      ans += (CS[ii] + CS[N-ii-1]) * M % mod;
      ans %= mod;
      ans += (CS[jj] + CS[M-jj-1]) * N % mod;
      ans %= mod;
    }
  }
  ans /= 2;
  ans *= nCr(N*M-2, K-2, mod);
  ans %= mod;
  cout << ans << endl;
  return 0;
}

