    VVLL ru(n,VLL(m));
    REP(i,0,n) REP(j,0,m) ru[i][j] = i + j;
    REP(i,0,n) REP(j,1,m) ru[i][j] = (ru[i][j] + ru[i][j-1]) % MOD;
    REP(j,0,m) REP(i,1,n) ru[i][j] = (ru[i][j] + ru[i-1][j]) % MOD;

    CNK1 cnk;

    LL ans = 0;
    REP(i,0,n) REP(j,0,m) {
        LL sum = 0;
        sum = (sum + ru[n-1-i][m-1-j]) % MOD;
        sum = (sum + ru[i][m-1-j]) % MOD;
        sum = (sum + ru[n-1-i][j]) % MOD;
        sum = (sum + ru[i][j]) % MOD;
        sum = (sum + MOD - (1LL * i * (i+1)/2)) % MOD;
        sum = (sum + MOD - (1LL * j * (j+1)/2)) % MOD;
        sum = (sum + MOD - (1LL * (n-1-i) * (n-1-i+1)/2)) % MOD;
        sum = (sum + MOD - (1LL * (m-1-j) * (m-1-j+1)/2)) % MOD;
        LL mul = 1;
        mul = (mul * cnk.get(n*m-1,k-1)) % MOD;
        mul = (mul * (k-1)) % MOD;
        mul = (mul * power(n*m-1,MOD-2)) % MOD;
        mul = (mul * power(2,MOD-2)) % MOD;
        sum = (sum * mul) % MOD;
        ans += sum;
