lint comb(lint n, lint r, lint m = mod) {
	if (r == 0 || r == n) return 1;
	lint res = fact[n] * modpow(fact[n - r], m - 2, m) % m * modpow(fact[r], m - 2, m) % m;
	return res < 0 ? res + m : res;
}

map<lint, lint> factring(lint n) {
	map<lint, lint> res;
	for (lint i = 2; i * i <= n; ++i) {
		while (n % i == 0) {
			n /= i;
			++res[i];
		}
	}
	if (n != 1) ++res[n];
	return res;
}

lint n, m, k, ans;
int main() {
	cin >> n >> m >> k;
	fact_init(n * m + 10);
	rep(i, n) {
		rep(j, m) {
			if (i == 0 && j == 0) continue;
			lint cnt1 = 2 * (n - i) * (m - j) * (i + j) % mod;
			if (i == 0 || j == 0) cnt1 >>= 1;
			ans += cnt1;
			ans %= mod;
		}
	}
	cout << ans * comb(n * m - 2, k - 2) % mod << endl;
}

