const int max_comb=250000;
vector<ll> fac(max_comb+1); //n! (mod M)
vector<ll> ifac(max_comb+1); //k!^(-1) (mod M)

ll mpow(ll x, ll n){ //x^n(mod M)
    ll ans = 1;
    while(n != 0){
        if(n&1) ans = ans*x % MOD;
        x = x*x % MOD;
        n = n >> 1;
    }
    return ans;
}

ll minv(ll x){
    return mpow( x, MOD-2 );
}

ll comb(int a, int b){     // C(a,b) = a! * b!^(-1) * (a-b)^(-1)
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b]* ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

ll perm(int a, int b){     // P(a,b) = a! * (a-b)!^(-1)
    if(b == 0)return 1;
    if(a < b || a < 0)return 0;
    ll tmp = ifac[a-b] % MOD;
    return tmp * fac[a] % MOD;
}

void pre_comb()
{
    fac[0] = 1;
    ifac[0] = 1;
    for(int i = 0; i<max_comb; i++){
        fac[i+1] = fac[i]*(i+1) % MOD; // n!(mod M)
        ifac[i+1] = ifac[i]*minv(i+1) % MOD; // k!^(-1) (mod M)
    }
    return;
}


ll func(int n, int m, int K)
{
    ll ans = 0;

    int k;
    for(k=1; k<=n; k++) {
        int b;
        for(b=1; b<=MIN(m,K); b++) {
            ll ans0=0;
            int a;
            for(a=0; a<=MIN(m*(k-1),K-b); a++) {
                int c=K-b-a;
                if(c>m*(n-k)) continue;
                ans0 = (ans0 + (comb(m*(k-1), a) * k)%MOD *a)%MOD;
                ans0 = (ans0 + (comb(m*(n-k), c) * (n-k+1))%MOD *c)%MOD;
            }
            ans = (ans + ans0 * comb(m,b))%MOD;
        }
    }

    return ans;
}

