#include <bits/stdc++.h>
using namespace std;

long long int nCr(long long int n, long long int r, long long int mod) {
  vector<vector<long long int>> v(n+1, vector<long long int>(n+1, 0));
  for(int ii=0; ii<v.size(); ii++){
    v[ii][0] = 1;
    v[ii][ii] = 1;
  }
  for(int ii=1; ii<v.size(); ii++) {
    for (int jj=1; jj<ii; jj++) {
      v[ii][jj] = (v[ii-1][jj-1] + v[ii-1][jj]) % mod;
    }
  }
  return v[n][r] % mod;
}

int main(){
  int mod = 1000000007;
  int N, M, K;
  cin >> N >> M >> K;

  int max_NM = max(N, M);
  vector<long long int> CS(max_NM, 0);
  for(int ii=1; ii<max_NM; ii++){
    CS[ii] = (CS[ii-1] + ii) % mod;
  }

  long long int ans = 0;
  for(int ii=0; ii<N; ii++){
    for(int jj=0; jj<M; jj++){
      ans += (CS[ii] + CS[N-ii-1])*M + (CS[jj] + CS[M-jj-1])*N;
      ans %= mod;
    }
  }
  ans /= 2;
  ans *= nCr(N*M-2, K-2, mod);
  ans %= mod;
  cout << ans << endl;
  return 0;
}

