    for (int d = 1; d <= M - 1; d++) {
        ret += ((((((M - d) * N) % MOD) * N) % MOD) * d) % MOD;
        ret %= MOD;
    }
    for (int d = 1; d <= N - 1; d++) {
        ret += ((((((N - d) * M) % MOD) * M) % MOD) * d) % MOD;
        ret %= MOD;
    }
    ret *= comb.get(N * M - 2, K - 2);
    ret %= MOD;

    cout << ret << endl;
    return 0;
}

