    res = add(res, (N-i+M-j-2)*(N-i)*(M-j) / 2);
    res = add(res, (M-j+i-1)*(i+1)*(M-j) / 2);
    res = add(res, (N-i+j-1)*(j+1)*(N-i) / 2);
    res = add(res, (i+j)*(i+1)*(j+1) / 2);
    res = sub(res, (N-i-1)*(N-i)/2);
    res = sub(res, (M-j-1)*(M-j)/2);
    res = sub(res, (j+1)*j/2);
    res = sub(res, (i+1)*i/2);

    return res;
}


