    long long res = 0;
    long long com = COM(N * M - 2, K - 2);
    for(int d=1; d<N; ++d) {
        res += com * d * (N - d) * M * M % MOD;
        res %= MOD;
    }
    for(int d=1; d<M; ++d) {
        res += com * d * (M - d) * N * N % MOD;
        res %= MOD;
    }
    cout << res << endl;
}

