const ll mod = 1000000007;

ll combin(ll n, ll r) {
  r = min(r, n - r);
  if (r == 0) return 1;
  if (r == 1) return n;
  vl num(r), den(r);
  rep(k, r) {
    num[k] = n - r + k + 1;
    den[k] = k + 1;
  }
  for (ll p = 2; p <= r; ++p) {
    ll pivot = den[p - 1];
    if (pivot > 1) {
      int offset = (n - r) % p;
      for (int k = p - 1; k < r; k += p) {
        num[k - offset] /= pivot;
        den[k] /= pivot;
      }
    }
  }
  ll res = 1;
  rep(k, r) {
    if (num[k] > 1) {
      res *= num[k];
      res %= mod;
    }
  }
  return res;
}

