lint pow(lint num, int e, lint MOD) {
    lint result = 1;
    lint cur_num = num;
    while (e) {
        if (e & 1) {
            result *= cur_num;
            result %= MOD;
        }
        cur_num *= cur_num;
        cur_num %= MOD;
        e >>= 1;
    }
    return result;
}

