	precalc();
	long long n, m, k;
	cin >> n >> m >> k;
	long long ans = 0LL;
	for (long long dx = 0LL; dx < m; ++dx) 
		ans = add_mod(ans, mul_mod(mul_mod(dx, mul_mod((m - dx) * n, n)), ncr_mod(n * m - 2, k - 2)));
	for (long long dy = 0LL; dy < n; ++dy) 
		ans = add_mod(ans, mul_mod(mul_mod(dy, mul_mod((n - dy) * m, m)), ncr_mod(n * m - 2, k - 2)));
	cout << ans << '\n';
}

