ll modex(ll a, ll b)
{
    ll ans = 1;
    while(b)
    {
        if(b & 1)
            ans = (ans * a) % mod;
        b >>= 1;
        a = (a * a) % mod;
    }
    return ans;
}
ll ncr(ll n, ll r)
{
    if(r == 0 || r == n)
        return 1;
    ll ans = f[n];
    ans = (ans * modex(f[n - r], mod - 2)) % mod;
    ans = (ans * modex(f[r], mod - 2)) % mod;
    return ans;
}
