  Combination cm = Combination(200010, MOD);

  ll ans = 0LL;
  for(ll i = 1LL; i < N; i++){
    ll cnt = (N - i) * M * M;
    ans += cnt * i * cm.get(N * M - 2, K - 2);
    ans %= MOD;
  }
  for(ll i = 1LL; i < M; i++){
    ll cnt = (M - i) * N * N;
    ans += cnt * i * cm.get(N * M - 2, K - 2);
    ans %= MOD;
  }

  cout << ans << endl;
  return 0;
}

