	ll res = 1;
	for (int i = 1; i <= n; i++) {
		res *= i;
		res %= MOD;
	}
	for (int i = 1; i <= k; i++) {
		res *= modpow(i, MOD - 2);
		res %= MOD;
	}
	for (int i = 1; i <= n - k; i++) {
		res *= modpow(i, MOD - 2);
		res %= MOD;
	}
	return res;
}

