class Combi {
  private:
    v(ll) fac, inv, finv;

    void init(int N) {
      fac[0] = fac[1] = 1; inv[1] = 1; finv[0] = finv[1] = 1;

      for (int i = 2; i < N; i++) {
        fac[i] = fac[i - 1] * i % MOD;
        inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
        finv[i] = finv[i - 1] * inv[i] % MOD;
      }
    }

  public:
    Combi(int N) : fac(N + 1), inv(N + 1), finv(N + 1) { init(N + 1); }

    int Cmod(int n, int k) {
      if (n < k) return 0;
      if (n < 0 || k < 0) return 0;
      return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
    }

    ll Pmod(int n, int k) {
      if (n < k) return 0;
      if (n < 0 || k < 0) return 0;
      return fac[n] * finv[n - k] % MOD;
    }
  };

int main() {
  int N,M,K;
  cin >> N >> M >> K;
  Combi c(N*M);
  ll x = c.Cmod(N*M-2,K-2);
  ll ans = 0;
  for(int i = 2;i <= M;i++) {
    ans = (ans + N * N * (M-i+1) *(i-1)) % MOD;
  }
  for(int i = 2;i <= N;i++) {
    ans = (ans + M * M * (N-i+1) *(i-1)) % MOD;
  }
  ans = (ans * x) % MOD;
  cout << ans << endl;
  return 0;
}

