#include <iostream>

namespace nt {
    template <int_fast64_t mod>
    class ModInt {
        int_fast64_t val;

      public:
        ModInt(): val(0) {}
        ModInt(int_fast64_t init_val): val(init_val >= 0? init_val % mod: mod - (-init_val % mod)) {}

        friend std::istream& operator >> (std::istream& is, ModInt& n) {
            int_fast64_t init_val;
            is >> init_val;
            n = ModInt(init_val);
            return is;
        }
        friend std::ostream& operator << (std::ostream& os, const ModInt n) {
            os << n.val;
            return os;
        }

        ModInt operator -() const {
            return ModInt(-val);
        }
        bool operator !() const {
            return val == 0;
        }
        ModInt& operator ++() {
            val++;
            if (val >= mod) {
                val -= mod;
            }
            return *this;
        }
        ModInt operator ++(int) {
            ModInt tmp = *this;
            val++;
            if (val >= mod) {
                val -= mod;
            }
            return tmp;
        }
        ModInt& operator --() {
            val--;
            if (val < 0) {
                val += mod;
            }
            return *this;
        }
        ModInt operator --(int) {
            ModInt tmp = *this;
            val--;
            if (val < 0) {
                val += mod;
            }
            return tmp;
        }

        ModInt& operator += (const ModInt that) {
            val += that.val;
            if (val >= mod) {
                val -= mod;
            }
            return *this;
        }
        ModInt& operator -= (const ModInt that) {
            val -= that.val;
            if (val < 0) {
                val += mod;
            }
            return *this;
        }
        ModInt& operator *= (const ModInt that) {
            val = val * that.val % mod;
            return *this;
        }
        ModInt& operator /= (const ModInt that) {
            int_fast64_t res = 1, n = that.val, p = mod - 2;
            while (p > 0) {
                if (p % 2 == 1) {
                    res = res * n % mod;
                }
                n = n * n % mod;
                p /= 2;
            }
            val = val * res % mod;
            return *this;
        }

        ModInt operator + (const ModInt that) const {
            return ModInt(*this) += that;
        }
        ModInt operator - (const ModInt that) const {
            return ModInt(*this) -= that;
        }
        ModInt operator * (const ModInt that) const {
            return ModInt(*this) *= that;
        }
        ModInt operator / (const ModInt that) const {
            return ModInt(*this) /= that;
        }
    };

    using mint = ModInt<1000000007>;
}

int main() {
    int_fast64_t m, n, k;
    std::cin >> m >> n >> k;

    nt::mint comb_x = 0;
    for (int i = 1; i < m; i++) {
        comb_x += nt::mint(i) * (m - i);
    }
    comb_x *= n * n;
    nt::mint comb_y = 0;
    for (int i = 1; i < n; i++) {
        comb_y += nt::mint(i) * (n - i);
    }
    comb_y *= m * m;
    nt::mint rest = nt::mint(m) * n - 2, comb_rest = 1;
    for (int i = 0; i < k - 2; i++) {
        comb_rest = comb_rest * (rest - i) / (i + 1);
    }

    std::cout << (comb_x + comb_y) * comb_rest << std::endl;

    return 0;
}

#include <bits/stdc++.h>

using namespace std;

const int MOD = 1e9 + 7, maxn = 1e5 + 9;
int64_t gt[maxn + 1], n, m, k;

int64_t Pow(int x, int y)
{
    if (y == 0)
        return 1;
    else
    {
        int64_t tmp = Pow(x, y/2);
        int64_t res = (tmp % MOD * tmp % MOD) % MOD;
        if (y % 2 == 0)
            return res;
        else
            return (res * x % MOD) % MOD;
    }
}

int64_t Comb(int n, int k)
{
    int64_t a = gt[n];
    int64_t b = (gt[k] % MOD * gt[n - k] % MOD) % MOD;
    int64_t c = (a * Pow(b, MOD - 2)) % MOD;  /// (a / b) % MOD = a * inverse(b) % MOD
    return c;
}

void Enter()
{
    freopen("E.inp", "r", stdin);
    freopen("E.out", "w", stdout);
    cin >> n >> m >> k;
}

void Init()
{
    gt[0] = 1;
    for (int i = 1; i <= maxn; i++)
        gt[i] = (gt[i - 1] % MOD * i % MOD) % MOD;
}

int64_t SumX()
{
    int64_t s = 0;
    for (int i = 1; i <= m; i++)
    {
        int64_t l = i - 1, r = m - i;
        s = (s + l * i - r * i) % MOD;
    }
    s = (s % MOD * Pow(n, 2)) % MOD;
    return s;
}

int64_t SumY()
{
    int64_t s = 0;
    for (int i = 1; i <= n; i++)
    {
        int64_t l = i - 1, r = n - i;
        s = (s + l * i - r * i) % MOD;
    }
    s = (s % MOD * Pow(m, 2)) % MOD;
    return s;
}

void Solve()
{
    cout << ((SumX() + SumY()) % MOD * Comb(m * n - 2, k - 2)) % MOD;
}

int main()
{
    Enter();
    Init();
    Solve();
    return 0;
}

