int comb_MOD(int n, int r){

  if (r > n/2) return comb_MOD(n, n - r);

  vector<int> c(r + 1, 0);
  c.at(0) = 1;

  for(int i = 0; i < n; i++){
    for(int j = r; j > 0 ; j--){
      c.at(j) = (c.at(j) + c.at(j - 1)) % MOD;
    }
  }

  for(int i = 0; i<= r; i++)
    cout << c.at(i) << ' ';

  return c.at(r);
}

