ll calcSum(ll a, ll b) {
  ll ret = 0;

  if (b > 0) {
    ll tmp = 0;
    tmp += a*(a+1)/2;
    ll e = M-1-a;
    tmp += e*(e+1)/2;

    ret = (ret + tmp*b)%MOD;
  }
  ret = (ret + a*(a+1)/2)%MOD;

//cerr << "a: " << ret << endl;

  ll tmp = b*(b+1)/2;

//cerr << "b: " << tmp*M << endl;

  ret = (ret + tmp*M%MOD)%MOD;

  return ret;
}

