  return pow(a, MOD - 2);
}

long long comb(int n, int k) {
  long long ret = 1;
  for (int i = n; i >= n - k + 1; --i) ret = ret * i % MOD;
  for (int i = 1; i <= k; ++i) ret = ret * inv(i) % MOD;
  return ret;
}

