template <typename number>
pair<number, number> extended_euclid(number a, number b)
{
    number r0, r1, a0, a1, b0, b1;
    r0 = a; r1 = b;
    a0 = 1; a1 = 0;
    b0 = 0; b1 = 1;
    while (r1>0) {
        number q1 = r0 / r1;
        number r2 = r0 % r1;
        number a2 = a0 - q1 * a1;
        number b2 = b0 - q1 * b1;
        r0 = r1 ; r1 = r2;
        a0 = a1 ; a1 = a2;
        b0 = b1 ; b1 = b2;
    }
    number c = r0;
    a = a0; //x
    b = b0; //y
    return  {a, c};
}

//Nを法とした逆元を求める関数
template  <typename number>
number inverse_N(number a, number N)
{
    pair<number, number> result = extended_euclid(a, N);
    if(result.first < 0)
    {
        result.first = result.first + N;
    }
    return result.first;
}

ll calc(ll unit, ll n, ll m)
{
  ll result = 0;
  //m = (m * m) % mod;
  m = (m * m);
  for(ll i = 1; i < n; i++)
  {
    ll temp = (m * (n - i)) % mod;
    ll temp2 = (temp * unit) % mod;
    ll temp3 = (temp2 * i) % mod;
    result = (result + temp3) % mod;
  }
  return result;
}

