        }
        if (a < 0) {
                return a + MOD;
        }
        return a;
}

int mul(int a, int b) {
        return a * (ll) b % MOD;
}

int expow(int a, int b) {
        int r = 1;
        while (b) {
                if (b & 1) {
                        r = mul(r, a);
                }
                a = mul(a, a);
                b >>= 1;
        }
        return r;
}

int get_factorial(int i) {
        if (i == 0) {
                return 1;
        } else {
                return mul(get_factorial(i - 1), i);
        }
}

int inv(int x) {
        return expow(x, MOD - 2);
}

int comb(int n, int k) {
        int x = get_factorial(n), y = inv(mul(get_factorial(k), get_factorial(n - k)));
        return mul(x, y);
}

