ll getK(ll k) {
    return k * (k - 1) / 2 % MODBASE;
}

ll mu(ll a, ll b) {
    if (b == 0) return 1;
    if (b == 1) return a % MODBASE;
    ll g = mu(a, b/2);
    if (b % 2) return g * g % MODBASE * a % MODBASE;
    return g * g % MODBASE;
}

ll C(ll n, ll k) {
    if (k > n) return 0;
    if (n < 0) return 0;
    return gt[n] * rev[n-k] % MODBASE * rev[k] % MODBASE;
}

ll tinh(ll g) {
    return g * (g + 1) / 2 % MODBASE;
}

