MI s1(MI x) { return x * (x + 1) / 2; }
MI s2(MI x) { return x * (x + 1) * (2 * x + 1) / 6; }
MI g(MI i, MI j) { return s2(i + j) - (s2(i) + j * s1(i)) - (s2(j - 1) + (i + 1) * s1(j - 1)); }

MI f(MI i, MI j) {
	MI I = n - 1 - i;
	MI J = m - 1 - j;

	MI s = 0;
	s += g(i, j);
	s += g(J, i);
	s += g(I, J);
	s += g(j, I);
	return s;
}

MI perm(LL x, LL y) {
	MI p = 1;
	inc(i, y) { p *= x - i; }
	return p;
}

