long long choose(long long n,long long r){
    if(n-r<r) r= n-r;
    if(r==0) return 1;
    if(r==1) return n;
    vector<long long> numerator(r);
    vector<long long> denominator(r);
    for(int k=0;k<r;k++){
        numerator[k] = n-r+k+1;
        denominator[k] = k+1;
    }
    for(int p=2;p<=r;p++){
        int pivot=denominator[p-1];
        if(pivot>1){
            int offset = (n-r)%p;
            for(int k=p-1;k<r;k+=p){
                numerator[k-offset] /= pivot;
                denominator[k] /=pivot;
            }
        }
    }
    long long result = 1;
    for(int k=0;k<r;k++){
        if(numerator[k]>1) result *= (int)numerator[k];
    }
    return result;
}

