        chmod(ans);
    }

    for(int d=1; d<m; ++d){
        ans += COM(n*m-2, k-2)*d%mod*(m-d)%mod*n%mod*n;
        chmod(ans);
    }

    cout << ans << endl;

	return 0;
}

