        ans += i * (M - i) * N * N; 
    }

    // y 方向
    for (int i = 0; i <= N - 1; i++) {
        ans += i * (N - i) * M * M;
    }

    // 2点以外の残りを選ぶ
    ans *= comb(N * M - 2, K - 2);
    cout << ans << endl;
}

