void recursive_comb(int *indexes, int s, int rest,
                    std::function<void(int *)> f) {
    if(rest == 0) {
        f(indexes);
    } else {
        if(s < 0)
            return;
        recursive_comb(indexes, s - 1, rest, f);
        indexes[rest - 1] = s;
        recursive_comb(indexes, s - 1, rest - 1, f);
    }
}

