int mod = 1000000007;

int power(int x, int y, int p) 
{ 
    int res = 1;      // Initialize result 

    x = x % p;  // Update x if it is more than or 
                // equal to p 

    while (y > 0) 
    { 
        // If y is odd, multiply x with result 
        if (y & 1) 
            res = (res*x) % p; 

        // y must be even now 
        y = y>>1; // y = y/2 
        x = (x*x) % p; 
    } 
    return res; 
} 

// Returns n^(-1) mod p 
int modInverse(int n, int p) 
{ 
    return power(n, p-2, p); 
} 

// Returns nCr % p using Fermat's little 
// theorem. 
int nCrModPFermat(int n, int r, int p) 
{ 
   // Base case 
   if (r==0) 
      return 1; 

    // Fill factorial array so that we 
    // can find all factorial of r, n 
    // and n-r 
    int prev=1, factn, factr, factn_r;
    for (int i=1 ; i<=n; i++) 
    {
        prev = prev*i%p; 
        if(i==n)
            factn = prev;
        else if(i==r)
            factr = prev;
        else if(i==n-r)
            factn_r=prev;
    }

    return (factn* modInverse(factr, p) % p * 
            modInverse(factn_r, p) % p) % p; 
} 

