    mint add = one * (N - i) * M * M * i;
    ans += add;
  }
  swap(N, M);
  for(ll i = 1; i <= N; i++){
    mint add = one * (N - i) * M * M * i;
    ans += add;
  }
  ans *= one * comb_naive(N*M-2, K-2);
  ans.get();
}

