      ll d1 = d, d2 = d;
      REP(k, i) {
        d1 += M;
        addM(d, d1);
      }
      REP(k, N - i - 1) {
        d2 += M;
        addM(d, d2);
      }
      mulM(d, COM(N * M - 2, K - 2));
      addM(ans, d);
    }
  }
