void gener() {
    for (int i = 1; i <= max(m, n); i++) {
        k[i] = (k[i - 1] + (i - 1)) % MODULO;
        d[i] = (k[i] + d[i - 1]) % MODULO;
        s[i] = (s[i - 1] + k[i] * 2) % MODULO;
    }
}

void Clear() {
    for (int i = 0; i <= n; i++)
        for (int j = 0; j <= m; j++)
            F[i].push_back(0);
