void prepa() {
    gener();
    Clear();
    for (int i = 2; i <= n; i++)
        for (int j = 2; j <= m; j++) {
            lld temp = ((d[i] * j * j) % MODULO + (s[j] * k[i]) % MODULO + (d[j] * i) % MODULO) % MODULO;
            F[i][j] = temp;
        }
}

void extendedEuclid(lld A, lld B)
{
    if (B == 0)
    {
        gcd = A;
        x = 1;
        y = 0;
    }
    else
    {
        extendedEuclid(B, A%B);
        lld temp = x;
        x = y;
        y = temp - (A/B)*y;
    }
}

