long comb(int r,int n){
	n = n + r - 1;
	if(n-r < r){
		r = n-r;
	}
	if(r == 1){
		return n;
	}
	vector <int> a(r);
	vector <int> b(r);

	for(int k = 0;k<r;k++){
		a[k] = n-r+k+1;
		b[k] = k+1;
	}

	for(int k = 2;k<=r;k++){
		int p = b[k-1];
		if(p > 1){
			for(int i = 0;i<r;i++){
				if(a[i] % p == 0){
					a[i] = a[i]/p;
					b[k-1] = 1;
					break;
				}
			}
		}
	}
	long result = 1;
	for(int p = 0;p<r;p++){
		if(a[p] > 1){
			result = result * a[p];
			result = result / b[p];
			if(result > 1000000007){
				result = result%1000000007;
			}
		}
	}
	return result;
}






