void solver::run(){
    if(!input()) return;
    RCR n, m, k;
    n = N; m = M; k = K;

    RCR ans = 0;
    for (int xd = 1; xd < N; ++xd) {
        ans += m*m*(n-xd) * xd;
    } // end xd
    for (int yd = 1; yd < M; ++yd) {
        ans += n * n * (m - yd) * yd;
    } // end xd
    RCR cons = choose(N*M-2, K-2);
    ans *= cons;
    os << ans << endl;
}

