constexpr int INF = (1<<30);
constexpr ll INFLL = 1LL<<62;
constexpr long double EPS = 1e-12;
constexpr ll MOD = (ll)((1E+9)+7);

class MODCOM{
  //nCr
  private:
    const ll MAX = 1000000;
    vll fac, finv, inv;
  public:
    MODCOM(void){
      fac.resize(MAX);
      finv.resize(MAX);
      inv.resize(MAX);

      fac[0] = fac[1] = 1;
      finv[0] = finv[1] = 1;
      inv[1] = 1;
      for(int i=2; i<MAX; ++i){
        fac[i] = fac[i-1]*i%MOD;
        inv[i] = MOD-inv[MOD%i]*(MOD/i)%MOD;
        finv[i] = finv[i-1]*inv[i]%MOD;
      }
    };

    ~MODCOM(void){
      return;
    };

    ll calc(ll n, ll k){
      if(n<k) return 0;
      if(n<0 || k<0) return 0;
      return fac[n]*(finv[k]*finv[n-k]%MOD)%MOD;
    };
};


int main(){
  cin.tie(0); // cut the cin and cout (default, std::flush is performed after std::cin)
  ios::sync_with_stdio(false); // cut the iostream and stdio (DON'T endl; BUT "\n";)

  ll N,M,K;
  IN(N,M,K);

  MODCOM com;

  ll x_cost=0, y_cost=0;

  for(ll d=1; d<N; ++d){
    x_cost += d*(N-d)*M*M;
    x_cost %= MOD;
  }
  ll tmp = com.calc((ll)(N*M-2), (ll)(K-2));
  x_cost *= tmp;
  for(ll d=1; d<M; ++d){
    y_cost += d*(M-d)*N*N;
    y_cost %= MOD;
  }
  y_cost *= tmp;

  OUT((x_cost%MOD + y_cost%MOD)%MOD);

  return 0;
}

