    // }
    // acc_x *= N;
    // acc_x *= N;
    // acc_x *= mint(c->com(N * M - 2, K - 2));
    for (ll i = 1; i < M; i++) {
        acc_x += i * (M - i) * N * N;
    }

    mint acc = acc_x + acc_y;
    acc *= mint(c->com(N * M - 2, K - 2));
    cout << acc.x << endl;

