      ll m = i - n;
      if(0 <= m && m < M){
        if(n == 0 || m == 0){
          cnt += (N - n) * (M - m);
        } else {
          cnt += (N - n) * (M - m) * 2;
        }
      }
    }
    ans += i * cnt * cm.get(N * M - 2, K - 2);
    ans %= MOD;
    //cout << "i = " << i << " cnt = " << cnt << " ans = " << ans << endl;
  }

  cout << ans << endl;
