    modint sum = 0;
    for (int i = 0; i <= N - 1; ++i) {
        for (int j = 0; j <= M - 1; ++j) {
            modint tmp = modint(N - i) * modint(M - j) * modint(i + j);
            if (i != 0 && j != 0) {
                tmp *= 2;
            }
            sum += tmp;
        }
    }
    cout << sum * comb.nCk(N * M - 2, K - 2) << endl;
    return 0;
}

