struct Comb{

  vector<int> fact,infact;
  int mod;

  Comb(int n,int m=1e9+7):
    fact(n+1),
    infact(n+1),
    mod(m)
  {
    n++;
    fact[0] = 1;
    for( int i = 1 ; i < n ; i++ ){
	 fact[i] = fact[i-1] * i;
	 fact[i] %= mod;
    }
    for( int i = 0 ; i < n ; i++ ){
	 infact[i] = mod_pow( fact[i] , mod-2 );
    }
  }

  int mod_pow(int x,int n){
    if(n==0)return 1;
    int res=mod_pow( x*x%mod , n/2 );
    if( n & 1 )res = res*x%mod;
    return res;
  }

  int comb(int a,int b){
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    int tmp = infact[a-b]* infact[b] % mod;
    return tmp * fact[a] % mod; 
  }

  int perm(int a,int b){
    if(a == 0 && b == 0)return 1;
    if(a < b || a < 0)return 0;
    return fact[a] * infact[a-b] % mod;
  }
};


