void gcd_extended(lld a,lld b,lld *x,lld *y)
{
    if(a==0)
    {
        *x=0;
        *y=1;
        return;
    }
    lld x1,y1;
    gcd_extended(b%a,a,&x1,&y1);
    *x=y1-(b/a)*x1;
    *y=x1;
    return;
}
lld ncr(lld n,lld k)
{
    if (k > n) return 0LL;
    if (k * 2 > n) k = n-k;
    if (k == 0) return 1;

    int result = n;
    for( int i = 2; i <= k; ++i ) {
        result = (result*(n-i+1))%mod;
    }
    for(int i=2;i<=k;i++)
    {
        lld x,y;
        gcd_extended(mod,i,&x,&y);
        y=(y%mod+mod)%mod;
        result=(result*y)%mod;
    }
    return result;
}
