  modint res = 0;
  binomial binom(n*m);
  modint c = binom(n*m-2,k-2);
  rep(d, 1, n) {
    res += modint(m) * modint(m) * modint(n-d) * c * modint(d);
  }
  rep(d, 1, m) {
    res += modint(n) * modint(n) * modint(m-d) * c * modint(d);
  }
  OUT(res);
}

