        fact[i] = fact[i - 1] * i % mod;
    }
    return fact;
}

long long nCk(long long n, long long k) {
    if (n - k < k) k = n - k;
    return fact[n] * (inverse(fact[n - k]) * inverse(fact[k]) % mod) % mod;
}

