};

Mod operator+=(Mod &a, Mod b) { a.n += b.n; if(a.n>=mod) a.n-=mod; return a; }
Mod operator-=(Mod &a, Mod b) { a.n -= b.n; if(a.n<0) a.n += mod; return a; }
