      mem %= mod;
    }
  }

  ans = mem * k;
  ans %= mod;
  ans *= inverse(2);
  ans %= mod;
  ans *= inverse(n*m);
  ans %= mod;
  ans *= k-1;
  ans %= mod;
  ans *= inverse(n*m-1);
  ans %= mod;
  ans *= combination(n*m,k);
  ans %= mod;
