  mint x(0);
  for (ll d = 1; d < N; ++d) { // d: |xi-xj|
    x += mint(d) * mint(N-d) * mint(M) * mint(M);
  }
  mint y(0);
  for (ll d = 1; d < M; ++d) { // d: |yi-yj|
    y += mint(d) * mint(M-d) * mint(N) * mint(N);
  }

  Combination c(N * M);
  mint ans = (x + y) * c(N * M-2, K-2);

  cout << ans.x << endl;
}

