    scanf("%d%d%d", &n, &m, &k);

    LL total = 0;
    for (LL i = 0; i < n; i++) {
        for (LL j = 0; j < m; j++) {
            total += sum(n - 1 - i) * m % M;
            total += sum(i) * m % M;
            total += sum(m - 1 - j) * n % M;
            total += sum(j) * n % M;
        }
    }
    // printf("total = %lld\n", total);

    LL l = n * m;

    LL ans = Number::mod_comb(l - 2, k - 2, M) * total;
    ans %= M;
    ans *= Number::mod_inv(2, M);
    ans %= M;

    printf("%lld\n", ans);

}

