    for (int i = MAXN - 2; i >= 0; --i) {
        tcaf[i] = prod(tcaf[i + 1], i + 1);
    }
}

int choose(int n, int k) {
    return prod(fact[n], prod(tcaf[k], tcaf[n - k]));
