    long d=1;
    for (int i=1;i<=k-2;i++)
    {
        d=(d*i)%mod;
    }
    d=power(d,mod-2);
    d=(d*s)%mod;
    return d;
}

long second()
{
    long s=0;
    for (int i=1;i<=n;i++)
    {
        for (int j=1;j<=m;j++)
        {
            long k1=(i-1)*i;
            k1=(k1%mod*m)%mod;
            long l1=(n-i)*(n-i+1);
            l1=(l1%mod*m)%mod;
            long k2=(j-1)*(j);
            k2=(k2%mod*n)%mod;
            long l2=(m-j)*(m-j+1);
            l2=(l2%mod*n)%mod;
            s=(s+k1+l1+k2+l2)%mod;
        }
    }
    s=(s*power(4,mod-2))%mod;
    return s;
}

