    for(ll i=1;i<M;i++){
        res_M = mod.add(res_M, mod.multi(i, M-i));
    }
    res_M = mod.multi(res_M, mod.power(N,2));

    auto res = mod.add(res_N, res_M);
    res = mod.multi(res, mod.comb(N*M-2, K-2));
    cout<<res<<endl;
