        ll tmp = y * (N - y) % MOD;
        tmp = tmp * M % MOD;
        tmp = tmp * M % MOD;
        tmp = tmp * cmb.nCk(N * M - 2, K - 2) % MOD;
        ans = (ans + tmp) % MOD;
    }
    cout << ans << endl;
    return 0;
}

