            s2[i][j] += (c2[i - 1][j] + s2[i - 1][j] + cr(j)) % M;
            c2[i][j] = (c2[i - 1][j] + j + m - j) % M;    
            sum2 += s2[i][j];
            cc2 += c2[i][j];
            sum2 %= M;
            cc2 %= M;
