    ll denomenator = 1;

    rep(i, r){
        numerator *= ll(n - i);
        numerator %= mod;
        denomenator *= power_mod(ll(i + 1), mod - 2);
        denomenator %= mod;
    }

    return (numerator * denomenator) % mod;
}

