ll distancesum(int arr[], int n) 
{ 
    // sorting the array. 
    sort(arr, arr + n); 

    // for each point, finding the distance. 
    ll res = 0, sum = 0; 
    for (int i = 0; i < n; i++) { 
        res = (res + ((arr[i] * i)% mod - sum + mod) % mod) % mod; 
        sum = (sum + arr[i]) % mod; 
    } 
    return res; 
} 

ll totaldistancesum(int x[], int y[], int n) 
{ 
    return distancesum(x, n) % mod + distancesum(y, n) % mod; 
} 


