ll calc(bool ud,ll pa_xy,ll xy,ll nm,ll k,ll kk,ll num){
  if(abs(pa_xy-xy)*nm>k-kk)return 0;//
  ll sum=0;
  if(ud){
    for(ll i=pa_xy+1;i<xy;++i){
      for(int j=0;j<k-kk+1;++j){
        sum+=calc(!ud,xy,i,nm,k,kk+j,j);
      }
    }
  }else{
    for(ll i=xy+1;i<pa_xy;++i){
      for(int j=0;j<k-kk+1;++j){
        sum+=calc(!ud,xy,i,nm,k,kk+j,j);
      }
    }
  }
  if(pa_xy==-1)return sum;
  return sum+=(abs(pa_xy-xy)*num);
}
