let threshold = 1000000007
var fac: [Int] = [1]
var ifac: [Int] = [1]

func comb(_ n: Int, _ k: Int) -> Int {
  return ((fac[n] * ifac[k]) % threshold) * ifac[n-k] % threshold
}

func powd(_ x: Int, _ n: Int) -> Int {
  var result = 1
  var n = n
  var x = x
  while n != 0 {
    if n & 1 == 1 {
      result = result * x % threshold
    }
    x = x * x % threshold
    n >>= 1
  }
  return result
}

