            // last + drow == n
            int last = n - drow;
            answ += Int(last) * drow * m * m * C(n*m-2,k-2);
        }
        for (int dcol = 0; dcol <= n; dcol++) {
            // last + dcol == m
            int last = m - dcol;
            answ += Int(last) * dcol * n * n * C(n*m-2,k-2);
        }
        std::cout << answ << std::endl;
    }
    return 0;
}

