// mod. m での a の逆元 a^{-1} を計算する
// 逆元をかければ割ったことになる
ll modinv(ll a) {
    ll b = MOD, u = 1, v = 0;
    while (b) {
        long long t = a / b;
        a -= t * b; swap(a, b);
        u -= t * v; swap(u, v);
    }
    u %= MOD;
    if (u < 0) u += MOD;
    return u;
}



