ll my_pow(ll a, ll n)
{
	if (n == 1) return a;
	if (n % 2)
	{
		ll res = my_pow(a, n - 1);
		res *= a;
		return res % MOD;
	}

	ll res = my_pow(a, n / 2);
	return res * res % MOD;
}

ll gb(ll a, ll b)
{
	ll ans = 1;
	for (int i = 1; i <= a; i++)
	{
		ans *= i;
		ans %= MOD;
	}

	for (int i = 1; i <= b; i++)
	{
		ans *= my_pow(i, MOD - 2);
		ans %= MOD;
	}

	for (int i = 1; i <= a - b; i++)
	{
		ans *= my_pow(i, MOD - 2);
		ans %= MOD;
	}
	return ans;
}

