LL modcom(const LL n, const LL k, LL mod) {
  LL nfact = 1;
  for(LL i=1; i<=n; i++) {
    nfact = (nfact * i) % mod;
  }

  LL s = max(k,n-k);
  std::vector<LL> inv(s+1);
  inv[1] = 1;
  for(LL i=2; i<= s; i++) {
    inv[i] = mod - inv[mod%i] * (mod / i) % mod;
  }
  LL kinv_fact = 1;
  for(LL i=2; i<=k; i++) {
    kinv_fact = (kinv_fact * inv[i]) % mod;
  }
  LL nkinv_fact = 1;
  for(LL i=2; i<=(n-k); i++) {
    nkinv_fact = (nkinv_fact * inv[i]) % mod;
  }

  if(n<k) { return 0; }
  if(n<0 || k<0) { return 0; }
  return nfact * (kinv_fact * nkinv_fact % mod) % mod;
}

