  // consider x-diff
  LL score = 0;
  for(int dx=1; dx<M; dx++) {
    score += dx * (M-dx) * N * N;
    score %= mod;
  }

  for(int dy=1; dy<N; dy++) {
    score += dy * (N-dy) * M * M;
    score %= mod;
  }

  LL c = modcom(N*M-2, K-2, mod);
  score = score * c % mod;

  cout << score << endl;

  return 0;
}

