const int MOD = 1e9+7;
const int MAX = 2e5;

vector<long long> fac(MAX), finv(MAX), inv(MAX);

int power_MOD(int a, int b){
  int ans = 1;
  while(b > 0){
    if(b&1) ans = (ans * a) % MOD;
    a = (a * a) % MOD;
    b>>=1;
  }
  return ans;
}

void comb_ini(){
  fac.at(0) = 1; fac.at(1) = 1;
  finv.at(0) = 1; finv.at(1) = 1;
  inv.at(1) = 1;
  for(int i = 2; i < MAX; i++){
    fac.at(i) = fac.at(i - 1) * i % MOD;
    inv.at(i) = MOD - inv.at(MOD % i) * (MOD / i) % MOD;
    finv.at(i) = finv.at(i - 1) * inv.at(i) % MOD;
  }
}

int comb_MOD(int n, int r){
  if(n < r) return 0;
  if(n < 0 || r < 0) return 0;
  return fac.at(n) * (finv.at(r) * finv.at(n - r) % MOD) % MOD;
}

