constexpr int fpm(int base, int index) {
    int power = 1;
    while (index) {
        if (index & 1) {
            power = 1LL * base * power % MOD;
        }
        base = 1LL * base * base % MOD;
        index >>= 1;
    }
    return power;
}
constexpr int inv2 = fpm(2, MOD-2);

int ncr(int r) {
    // (N x M - 2) choose (K - 2)
    int n = (1LL * N * M % MOD + MOD - 2) % MOD;
    int c = 1;
    for (int i = 1; i <= r; ++i) {
        c = 1LL * c * (n - (i - 1)) % MOD * fpm(i, MOD-2) % MOD;
    }
    return c;
}

