ll ncr(ll n, ll r, ll mod = MOD) {
	if (n < r || n < 0 || r < 0) return 0;
	if (r > n - r) r = n - r;
	ll res = 1;
	for (ll i = n; i >= n - r + 1; i--) res = res * i % mod;
	res = res * inv[r] % mod;
	return res;
}

ll solve(ll H, ll W, ll K) {
	ll res = 0;

	ll allp = ncr(H * W - 2, K - 2);

	FOR(w, 1, W + 1) {
		ll pat = W - w;
		pat = pat * H % MOD * H % MOD * allp % MOD;
		res = (res + pat * w % MOD) % MOD;
	}

	return res;
}

