LL powMod(LL num, LL n, LL mod = (LL)MOD) {//(num**n)%mod
	num %= mod;//
	if (n == 0) {
		return (LL)1;
	}
	LL mul = num;
	LL ans = (LL)1;
	while (n) {
		if (n & 1) {
			ans = (ans * mul) % mod;
		}
		mul = (mul * mul) % mod;
		n >>= 1;
	}
	return ans;
}
LL mod_inverse(LL num, LL mod = MOD) {
	return powMod(num, MOD - 2, MOD);
}

LL nCk(LL N, LL k, LL mod = MOD) {
	LL ans = 1;
	if (k == 0 || k == N) {
		return 1;
	}
	ans = (kai[N] * kai_inv[N - k]) % mod;
	ans = (ans * kai_inv[k]) % mod;
	return ans;
}

LL cal(LL H, LL W,LL K) {
	LL ans = 0;
	LL base = nCk(H * W - 2, K - 2);
	base = (base * H) % MOD;
	base = (base * H) % MOD;
	for (LL i = 0; i < W; ++i) {
		ans += i * (W - i);
		ans %= MOD;
	}
	/*
	for (int w1 = 0; w1 < W; ++w1) {
		for (int w2 = w1; w2 < W; ++w2) {
			ans += abs(w1 - w2);
			ans %= MOD;
		}
	}
	*/
	ans = (ans * base) % MOD;
	return ans;
}
