ll modpow(ll a, ll n, ll m) {
	ll res = 1;
	while (n) {
		if (n & 1)res = res * a % m;
		a = a * a%m; n >>= 1;
	}
	return res;
}

struct MODF_{
  int n;
  V<ll> f, invf;
  void init(int num){
    n = num;
    f = V<ll>(n+5), invf = V<ll>(n+5); 
    //f.resize(n+5); invf.resize(n+5);
    f[0] = 1;
    FOR(i,0,n){
      f[i+1] = (i+1)*f[i]%mod;
    }
    invf[0] = 1;
    invf[1] = 1;
    IFOR(i,2,n){
      invf[i] = modpow( f[i], mod-2, mod);
    }
  }
  ll comb(ll a,ll b){
    if(a<0 || b<0 || a-b<0) return 0;
    return ( ((f[a] * invf[b])%mod ) *invf[a-b] )%mod;
  }
};



void solve(){
