    (tmp *= ((((m*m)%mod)*m)%mod + mod - m) %mod ) %=mod;
    (tmp *= modpow(3,mod-2,mod)) %= mod;
    (ans += tmp) %= mod;
    swap(n,m);
  }

  (ans *= mf.comb(n*m-2,k-2) ) %= mod;
  (ans *= modpow(2,mod-2,mod) ) %= mod;
  coutn(ans);
}


