ModularInt solve(int n, int m, int k) {
    ModularInt bc = binomialCoefficient.choose(n * m - 2, k - 2);
    ModularInt ans = 0;
    for(int d = 1; d < m; d++) {
        ans += (ModularInt)d * n * n * (m - d) * bc;
    }
    return ans;
}

