// x^n ( mod M ) を求める
//  例えば n = 10 だとすると
//  x^10 = x^(2+8) = x^2 * x^8 = x^2 * ((x^2)^2)^2
//  10 = 'b1010
ll powmod( ll x, ll n) {
  ll ans = 1;
  while ( n > 0 ) {
    if (n & 1) ans = (ans * x) % MOD;
    x = (x * x) % MOD;
    n >>= 1;
  }
  return ans;
}

// MODの逆元
//  a^(p-1) mod p = 1
//  a * a^(p-2) mod p = 1
//  a^(p-2) mod p = 1 / a mod p
ll inv( ll a ) {
  ll x = 1;
  for ( ll i=1; i<a+1; ++i ) {
    x = (i * x) % MOD;
  }
  return powmod( x, MOD-2 ) % MOD;
}

// n C r mod M
//  = n! / ( r! * (n-r)! )
//  = n * (n-1) * (n-2) * ... * (n-r+1) + (r!)^-1 
ll comb( ll n, ll r ) {
  ll ans = 1;
  for ( ll i=n; i>(n-r); --i ) {
    ans = (ans * i) % MOD;
  }
  return (ans * inv(r)) % MOD;
}

