    for (int i = 1; i <= nn - kk; ++i) mau = (mau*i) % MOD;
    mau = power(mau, MOD - 2);

    res = (res * tu) % MOD;
    res = (res * mau) % MOD;
    cout << res;

    return 0;
}

#include <bits/stdc++.h>
