        ll A = N*N*(M-dx) % mod;
        sumdx += dx * A %mod;
        sumdx = sumdx % mod;
    }

    ll sumdy = 0;
    for(ll dy=1; dy < N; dy++){
        ll B = M*M*(N-dy) % mod;
        sumdy += dy * B % mod;
        sumdy = sumdy % mod;
    }

    cout << (sumdx+sumdy) * W % mod << endl; 
}

