const int N = 2e5 + 10;
int t1[N], t2[N];

int fpow(int a, int b) {
  int ans = 1;
  for(; b > 0; b >>= 1, a = 1ll * a * a % MOD) {
    if(b & 1) {
      ans = 1ll * ans * a % MOD;
    }
  }
  return ans;
}

int fac(int n) {
  if(n <= 1) return 1;
  const int C = sqrt(n);
  vector<int> v(C);
  for(int i = 0; i < C; i++) {
    v[i] = MOD - (i + 1);
  }
  v = poly::buildPoly(v, 0, C - 1);
  vector<int> p(C);
  for(int i = 0; i < C; i++) {
    p[i] = C * i;
  }
  int ans = 1;
  p = poly::multipointCalc(v, p);
  for(int i = 0; i < C; i++) {
    ans = 1ll * ans * p[i] % MOD;
  }
  for(int i = C * C + 1; i <= n; i++) {
    ans = 1ll * ans * i % MOD;
  }
  return ans;
}

int C(int n, int m) {
  return 1ll * fac(n) * fpow(fac(n - m), MOD - 2) % MOD * fpow(fac(m), MOD - 2) % MOD;
}

int lucas(ll n, ll m) {
  if(n < MOD && m < MOD) {
    return C(n, m);
  }
  return C(n % MOD, m % MOD) * lucas(n / MOD, m / MOD) % MOD;
}

void Main() {
