    }
    for(int j = 5; j <= n; j++) {
      t1[j] = (((4ll * t1[j - 1] - 6ll * t1[j - 2] + 4ll * t1[j - 3] - 1ll * t1[j - 4]) % MOD) + MOD) % MOD;
    }
    t2[i] = t1[n];
  }
  for(int i = 5; i <= m; i++) {
    t2[i] = (((4ll * t2[i - 1] - 6ll * t2[i - 2] + 4ll * t2[i - 3] - 1ll * t2[i - 4]) % MOD) + MOD) % MOD;
  }
  int res = 1ll * t2[m] * lucas(1ll * n * m - 2, k - 2) % MOD;
  cout << res << "\n";
}

