	Modll operator + (Modll &b) { return val + b.val; }
	Modll operator - (Modll &b) {return val - b.val;}
	Modll<mod> operator * (Modll<mod> &b) {return val * b.val;}
	Modll operator + (ll b) { return *this + Modll(b); }
	Modll operator - (ll b) { return *this - Modll(b); }
	Modll<mod> operator * (ll b) { return *this * Modll<mod>(b); }
	friend Modll<mod> operator + (ll a, Modll<mod> &b) { return b + a; }
	friend Modll<mod> operator - (ll a, Modll<mod> &b) { return -b + a; }
	friend Modll<mod> operator * (ll a, Modll<mod> &b) { return b * a; }
	Modll &operator += (Modll &b) { val=(val+b.val)%mod; return *this; }
	Modll &operator -= (Modll &b) { val=(val+mod-b.val)%mod; return *this; }
	Modll &operator *= (Modll &b) { val=(val*b.val)%mod; return *this; }
	Modll &operator += (ll b) { return *this += Modll(b); }
	Modll &operator -= (ll b) { return *this -= Modll(b); }
	Modll &operator *= (ll b) { return *this *= Modll(b); }
	Modll &operator /= (ll b) { return *this /= Modll(b); }

	Modll &operator /= (Modll &r) {
		ll a=r.val, b=mod, u=1, v=0;
		while (b){
			ll t = a / b;
			a -= t * b; swap(a, b);
			u -= t * v; swap(u, v);
		}
		val = val * u % mod;
		if (val < 0) val += mod;
		return *this;
	}

	Modll operator / (Modll &r) {
		return Modll(*this) /= r;
	}

	bool operator == (Modll &b) { return val == b.val; }
	bool operator != (Modll &b) { return val != b.val; }
	bool operator == (ll b) { return *this == Modll(b); }
	bool operator != (ll b) { return *this != Modll(b); }
	friend bool operator == (ll a, Modll<mod> &b) { return Modll<mod>(a) == b.val; }
