vector<modll> P;

int main()
{
	cin >> N >> M >> K;
	NM = N * M;
	C.resize(K  +1);
	P.resize(K-2+1);

	P[0] = 1;
	REPS(i, 1, K-2){
		P[i] = P[i-1] * (NM - 2 - (i-1));
	}

	modll III = N*N*(M-1)*M*(M+1)/3 + M*M*(N-1)*N*(N+1)/3;
	C[1] = 0;
	REPS(k, 2, K){
		modll I = C[k-1] * (NM - k + 1);
		modll II = (k-1)*P[k-2]*III;
		C[k] = I + II;
	}

	//K!で割る
	modll ans = C[K];
	REPS(k, 2, K){
		ans /= k;
	}

	cout << ans << '\n';
	return 0;
}

