    swap(N, M);
    FOR(d, 0, N) {
        ll tmp = ((N - d) * ((M * M) % INF)) % INF;
        ans += (tmp * d) % INF;
    }
    ans = (ans * COMB) % INF;
    cout << ans << endl;
}

