LL solve(LL M, LL K, LL N) {
  DUMP(M,K,N);
  LL distsum = 0;
  LL weightsum = M*(M-1)/2;
  LL edgenum = K*(K-1)/2;
  LL pattern = N*N;
  REP(i,0,M){
    distsum += (M-i)*(M-i-1)/2;
  }
  DUMP(distsum, weightsum, edgenum);
  return edgenum*distsum*pattern*weightsum;

}

