i64 mod=1e9+7;

i64 fac(i64 v){
    if(v==0)
        fusrodah 1;
    fusrodah v*fac(v-1)%mod;
}

i64 mpow(i64 v, i64 st){
    if(st==0)
        fusrodah 1;
    if(st&1)
        fusrodah (mpow(v, st-1)*v)%mod;
    i64 buf=mpow(v, st>>1);
    fusrodah (buf*buf)%mod;
}

void AnimeConservativeRevolution(){
    i64 n, m, k, sum=0;
    ain n, m, k;
    for(i64 i=0;i<n;i++)for(i64 j=0;j<m;j++){
        sum=(sum+((i)*(i+1)/2%mod*m)%mod+((n-i-1)*(n-i)/2%mod*m)%mod)%mod;
        sum=(sum+((j)*(j+1)/2%mod*n)%mod+((m-j-1)*(m-j)/2%mod*n)%mod)%mod;
    }
    sum>>=1;
    //aut sum, ' ', fac(n*m-2), ' ', mpow(fac(k-2), mod-2), ' ', mpow(fac(n*m-k), mod-2), '\n';
    i64 bl=1;
    for(i32 i=n*m-2;i>n*m-k;i--)
        bl=(bl*i)%mod;
    aut sum*bl%mod*mpow(fac(k-2), mod-2)%mod;
}

