    fact[1] = invfac[1] = 1;
    for(int i = 2; i < MAXM; ++i) fact[i] = 1ll * i * fact[i - 1] % mo, invfac[i] = fpm(fact[i]);
}
inline ll C(ll n, ll r)
{
    if(n < r || r < 0 || n < 0) return 0;
