class mint {
public:
    long long x;
    mint(long long x=0) : x((x%MOD+MOD)%MOD) {}
    //mint operator-() const{ return mint(-x);}
    mint operator-() const {
      return mint(-x);
    }
    mint& operator+=(const mint& a) {
        if ((x += a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator-=(const mint& a) {
        if ((x += MOD-a.x) >= MOD) x -= MOD;
        return *this;
    }
    mint& operator*=(const  mint& a) {
        (x *= a.x) %= MOD;
        return *this;
    }
    mint operator+(const mint& a) const {
        mint res(*this);
        return res+=a;
    }
    mint operator-(const mint& a) const {
        mint res(*this);
        return res-=a;
    }
    mint operator*(const mint& a) const {
        mint res(*this);
        return res*=a;
    }
    mint pow(ll t) const {
        if (!t) return 1;
        mint a = pow(t>>1);
        a *= a;
        if (t&1) a *= *this;
        return a;
    }
    // for prime mod
    mint inv() const {
        return pow(MOD-2);
    }
    mint& operator/=(const mint& a) {
        return (*this) *= a.inv();
    }
    mint operator/(const mint& a) const {
        mint res(*this);
        return res/=a;
    }

};

template<class T>
struct combination {
    vector<T> fact_, ifact_;
    combination(long long n):fact_(n+1),ifact_(n+1) {
      assert(n < MOD);
      fact_[0] = 1;
      for (int i = 1; i <= n; ++i) fact_[i] = fact_[i-1]*i;
      ifact_[n] = fact_[n].inv();
      for (int i = n; i >= 1; --i) ifact_[i-1] = ifact_[i]*i;
    }
    T com(long long n, long long k) {
      if (k < 0 || k > n) return 0;
      return fact_[n]*ifact_[k]*ifact_[n-k];
    }
    T fact(ll n){
      if (n < 0) return 0;
      return fact_[n];
    }
};

