	Combination c(n*m-2,k-2);
	for(int i=0; i<n; i++){
		for(int j=0; j<m; j++){
			sum += (i*(i+1)/2+(n-i)*(n-i-1)/2)*m;
			sum %= MOD;
			sum += (j*(j+1)/2+(m-j)*(m-j-1)/2)*n;
			sum %= MOD;
		}
	}
	sum *= c.comb(k-2);
	sum %= MOD; 
	sum *= inverse(2,MOD);
	sum %= MOD;
	cout << sum << endl;

}

