    modlong sum = 0, comb = modComb(n*m-2, k-2);
    for (long d=1; d<n; d++) sum += comb * d * (n-d) * m * m;
    for (long d=1; d<m; d++) sum += comb * d * (m-d) * n * n;
    cout << sum << '\n';
    return 0;
}

