ll nCr(ll n, ll r, ll M = MOD) {
  if (r > n) return 0;
  ll ret = fact[n];
  ret = (ret*rfact[r]) % M;
  ret = (ret*rfact[n - r]) % M;
  return ret;
}

ll solve (ll h, ll w, ll k) {
  ll rn = h * (w - 1);
  ll ln = h;
  ll rs = (h * (w - 1) * w / 2) % MOD;
  ll ls = 0;

  ll res = 0;
  rep (j, w) {
    res = (res + rs + ls) % MOD;
    rs -= rn;
    ls += ln;
    rn -= h;
    ln += h;
  }
  res *= h;
  (res *= nCr(h*w - 2, k - 2)) %= MOD;
  return res;
}

