    rep(d, N) sum += mint(d) * mint(N - d) * mint(M) * mint(M); // |xi - xj| = d となる２駒の距離の合計 横方向にN-d個,縦方向にM*2パターンの置き方がある
    rep(d, M) sum += mint(d) * mint(M - d) * mint(N) * mint(N); // |yi - yj| = d となる２駒の距離の合計 縦方向にM-d個,横方向にN*2パターンの置き方がある
    cout << sum * bc.com(N * M - 2, K - 2) << endl; // ある2マスを固定したときの残りのN*M-2マスにK-2個の駒を置く通り数を掛ける
}

