/**
 *  mod による操作ライブラリ
 */

#define ANS_MOD (1000000007LL)

static SQWORD addMod(SQWORD x, SQWORD y)
{ 
    return (x + y) % ANS_MOD;
}

static SQWORD subMod(SQWORD x, SQWORD y)
{
    return (x - y + ANS_MOD) % ANS_MOD;
}

static SQWORD mulMod(SQWORD x, SQWORD y) 
{
    return (x * y) % ANS_MOD;
}

static SQWORD powMod(SQWORD x, SQWORD e) {
    SQWORD v = 1;
    for (; e; x = mulMod(x, x), e >>= 1) {
        if (e & 1) {
            v = mulMod(v, x);
        }
    }
    return v;
}

static SQWORD divMod(SQWORD x, SQWORD y)
{
    return mulMod(x, powMod(y, ANS_MOD - 2));
}


static SQWORD combMod(SQWORD n, SQWORD k)
{
    SQWORD v=1;
    for(SQWORD i=1; i<=k; i++) {
        v = divMod(mulMod(v, n-i+1),i);
    } 
    return v;
}

static SQWORD calcSingleAxis(SQWORD sqVal_N, SQWORD sqVal_M, SQWORD sqVal_K)
{
    SQWORD sqComb_a = subMod(mulMod(sqVal_N, sqVal_M), 2LL);
    SQWORD sqComb_b = subMod(sqVal_K, 2LL);
    SQWORD sqComb = combMod(sqComb_a, sqComb_b);
    SQWORD sqM_sqared = mulMod(sqVal_M, sqVal_M);

    SQWORD sqDistSum = 0;
    for (SDWORD lIdx = 1; lIdx < sqVal_N; lIdx++) {
        sqDistSum = addMod(sqDistSum, mulMod((SQWORD)lIdx, sqVal_N - (SQWORD)lIdx));
    }
//    printf("%lld %lld %lld\n", sqComb, sqM_sqared, sqDistSum);

    SQWORD sqRet = mulMod(sqComb, sqM_sqared);
    sqRet = mulMod(sqRet, sqDistSum);

    return sqRet;
}



int main(void)
{
    SQWORD sqInput_N = inputSQWORD();
    SQWORD sqInput_M = inputSQWORD();
    SQWORD sqInput_K = inputSQWORD();

