    r1 = r1 * M % MOD * M % MOD * comb.nCk(N * M - 2, K - 2) % MOD;

    for(int d=1;d<M;++d){
        r2 = (r2 + 1ll * d * (M - d)) % MOD;
    }

    r2 = r2 * N % MOD * N % MOD * comb.nCk(N * M - 2, K - 2) % MOD;

    ll res = (r1 + r2) % MOD;

    std::cout << res << std::endl;
}

