		v_inv[i]=pmod(v[i],mod-2);
	}
}

ll binom(ll n, ll k){
	if(n<k) return 0;
	ll tmp=v_inv[k]*v_inv[n-k]%mod;
	return v[n]*tmp%mod;
}

ll fcn(int n, int m){
	ll t=n*n%mod;
	return t*binom(m+1,3)%mod;
}

