int main() {

    ll n, m, k; cin >> n >> m >> k;

    vector<vector<ll>> dist(n, vector<ll>(m));
    vector<vector<ll>> imos(n+1, vector<ll>(m+1, 0));
    REP(i, n) REP(j, m) dist[i][j] = i + j;
    REP(i, n) REP(j, m) {
        imos[i+1][j+1] += imos[i][j+1] + imos[i+1][j] - imos[i][j] + dist[i][j];
    }

    make_fac_cache(200010);

    ll ans = 0;
    REP(i, n) REP(j, m) {

        ll term = 0;
        ll w1 = m-j, w2 = j+1;
        ll h1 = n-i, h2 = i+1;

        term += imos[h1][w1] % p;
        term += imos[h1][w2] % p;
        term += imos[h2][w1] % p;
        term += imos[h2][w2] % p;
        term += p - imos[1][w1];
        term += p - imos[1][w2];
        term += p - imos[h1][1];
        term += p - imos[h2][1];
        term %= p;

        ans += term;
        ans %= p;

    }

    ans *= nCr(n*m-2,k-2);
    ans %= p;
    ans *= facll(k-2);
    ans %= p;
    ans *= nCr(k, 2);
    ans %= p;
    ans *= invfacll(k);
    ans %= p;

    cout << ans << endl;

}

