    for (int i = 0; i < 2; i++) {
        for (int d = 1; d < n; d++) {
            mint res = (n - d) * m * m;
            res *= com(n * m - 2, k - 2);
            res *= d;
            ans += res;
        }
        swap(n, m);
    }

    cout << ans << '\n';
    return 0;
}

