template <long long mod>
struct mint {
    long long v;
    mint(long long x = 0) : v(x >= 0 ? x % mod : mod >= -x ? mod + x : -(-x % mod) + mod) {}
    mint &operator+=(const mint &r)
    {
        if ((v += r.v) >= mod)
        {
            v -= mod;
        }
        return *this;
    }
    mint &operator-=(const mint &r)
    {
        if ((v -= r.v) < 0)
        {
            v += mod;
        }
        return *this;
    }
    mint &operator*=(const mint &r)
    {
        if ((v *= r.v) >= mod)
        {
            v %= mod;
        }
        return *this;
    }
    mint &operator/=(const mint &r)
    {
        *this *= r.inverse();
        return *this;
    }
    mint &operator+(const mint &r)
    {
        return mint(*this) += r;
    }
    mint &operator-(const mint &r)
    {
        return mint(*this) -= r;
    }
    mint &operator*(const mint &r)
    {
        return mint(*this) *= r;
    }
    mint &operator/(const mint &r)
    {
        return mint(*this) /= r;
    }
    mint &operator-()
    {
        return mint(-v);
    }
    mint pow(long long n) const
    {
        mint constant = mint(v);
        mint tmp = mint(1);

        while (n > 0)
        {
            if (n & 1)
            {
                tmp *= constant;
            }

            constant *= constant;
            n >>= 1;
        }
        return tmp;
    }
    mint inverse() const
    {
        long long mi = mod - 2ll;
        return pow(mi);
    }

};

long long pow(const long long &v, const long long &n, const long long &mod)
{
    long long ret = 1;
    long long num = n;
    long long now = v;

    while (num > 0)
    {
        if (num & 1)
        {
            ret = ret * now % mod;
        }
        now = now * now % mod;
        num = num >> 1;
    }

    return ret;
}

long long calc(const long long &n, const long long &k, const long long &mod)
{
    long long ret;
    vector<ll> fac = vector<long long>(n + 1, 1);
    vector<ll> inv = vector<long long>(n + 1, 1);

    for (int i = 1; i <= n; ++i)
    {
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = pow(fac[i], mod - 2, mod);
    }

    ret = fac[n] * inv[k] % mod * inv[n - k] % mod;

    return ret;
}



