  for(int d = 1; d < N; d++)
    res = ((d * ((((N-d) * M * M) * ModComb(N * M - 2, K - 2, MOD)) % MOD)) % MOD + res) % MOD;

  for(int d = 1; d < M; d++)
    res = ((d * ((((M-d) * N * N) * ModComb(N * M - 2, K - 2, MOD)) % MOD)) % MOD + res) % MOD;

  cout << res << endl;
  return 0;

}

