  {
    ll t = (M - i) * (M - 1 - i) / 2;
    t %= MOD;
    t *= N;
    t %= MOD;
    t *= N;
    t %= MOD;
    t *= C(N * M - 2, K - 2);
    t %= MOD;
#if DEBUG == 1
    cerr << "i = " << i << ", t = " << t << endl;
#endif
    ans += t;
    ans %= MOD;
  }
}

