ll AN(ll A, ll N){
  if (N == 0){
    return 1;
  }else{
    if (N % 2 == 0){
      return AN(A * A % nmax, N / 2) % nmax;
    }else{
      return A * AN(A * A % nmax, N / 2) % nmax;
    }
  }
}

ll nCk(ll N, ll K){
  ll ans = 1;
  for (ll i = 0; i < K; i++){
    ans *= N - i; ans %= nmax;
    ans *= AN(i + 1, nmax - 2); ans %= nmax;
  }
  return ans;
}

