	while(b>0){
		if(b&1) result = (result*a)%mod;
		(a*=a)%=mod;
		b/=2;
	}
	return result;
}

int inv(ll x){
	ll e= mod-2, r= 1;
	while(e){
		if(e&1) r = r*x%mod;
		x = x*x % mod;
		e >>= 1;
	}
	return r;
}

int ncr(ll a, ll b){
	if(b<0 || b>a) return 0;
	return fac[a]*fin[b] %mod * fin[a-b]%mod;
}


