// a^b % MOD を計算して返す
ll power(ll a, ll b) {
  if (b == 0) {
    return 1;
  } else {
    ll ans = power(a, b / 2); ans = ans * ans; ans = ans % MOD;
    if (b % 2 == 1) ans = ans * a;
    ans = ans % MOD;
    return ans;
  }
}

 // nCr % MOD を計算して返す
ll choose(ll n, ll r) {
  ll ans = fact[n];
  ans = fact[n] * power(fact[r], MOD-2); ans = ans % MOD;
  ans = ans * power((fact[n-r] + MOD) % MOD, MOD-2); ans = ans % MOD;
  return ans;
}

