  }
  for (int64_t i = 1; i < m; i++) {
    cost += (m - i) * i * n * n;
    cost %= mod;
  }

  std::cout << (cost * combination(n * m - 2, k - 2, mod)) % mod << std::endl;
  return 0;
}

