#define MAX 1000000007

int calc_cost(long long int n, long long int m, long long int k) {
    long long int combi = 1;
    for (long long int i = 1, j = n * m - 2; i <= k - 2; i++, j--) {
        combi *= j;
        combi /= i;
    }
    combi %= MAX;
    long long int sum = 0;
    for (long long int i = 1; i < n; i++) {
        sum += i * (n - i) * m * m * combi;
        sum %= MAX;
    }
    return sum;
}


