    int i = 1, j = 0;
    while(i < s.size()) {
        while((i+j < s.size()) && (s.at(j) == s.at(i+j))) j++;
        a.at(i) = j;
        if(j == 0) {
            i++;
            continue;
        }
        int k = 1;
        while ((i+k < s.size()) && (k+a.at(k) < j)) {
            a.at(i+k) = a.at(k);
            k++;
        }
        i += k;
        j -= k;
    }
}

