					uh.emplace(a);
					uh_sum += a;

					int tmp = uh.top();
					uh.pop();
					lh.emplace(tmp);
					uh_sum -= tmp;
					lh_sum += tmp;

					lh_cnt++;

				}
				else {

					assert(lh_cnt > uh_cnt);

					uh.emplace(a);
					uh_sum += a;

					uh_cnt++;

				}

			}


		}
		else {
			cout << lh.top() << " " << uh_sum - lh_sum + B + (lh_cnt != uh_cnt) * lh.top() << "\n";
		}

	}

	return 0;
}

