/* 二項係数 C(n,k) mod p を計算 */
const int MAX = 2*1e5;
long long fac[MAX], finv[MAX], inv[MAX];

void COMinit() {
  fac[0] = fac[1] = 1;
  finv[0] = finv[1] = 1;
  inv[1] = 1;
  for (int i = 2; i < MAX; i++){
    fac[i] = fac[i - 1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i - 1] * inv[i] % MOD;
  }
}

long long COM(int n, int k){
  if (n < k) return 0;
  if (n < 0 || k < 0) return 0;
  return fac[n] * (finv[k] * finv[n - k] % MOD) % MOD;
}

int main() {
  int N, M, K;
  cin >> N >> M >> K;

  COMinit();
  ll ans = 0;

  FOR(d,1,N){
    ans += d * (N-d) % MOD * M % MOD * M % MOD;
  }

  FOR(d,1,M){
    ans += d * (M-d) % MOD * N % MOD * N % MOD;
  }

  ans = ans * COM(M*N-2, K-2) % MOD;

  cout << ans % MOD << endl;
}

