// あまり大きな数字を入れると桁溢れする
template <typename T>
T comb(T n, T r) {
  // 組み合わせ計算時のかぶっている部分を取り除く
  r = std::min(n - r, r);
  T result = 1;
  T div = 1;
  for (T i = 1; i <= r; ++i) {
    result = (result * (n - i + 1));
    // result = result / i;
    div = div * i;
  }
  return result / div;
}

// 値が大きくなる時の対処用のクラス
template <typename T, T MOD>
class mod_int {
 private:
  typedef mod_int<T, MOD> mint;
  T inverse(T x) {
    T pow = MOD - 2;
    T result = 1;
    for (; pow; pow >>= 1, x = x * x % MOD) {
      if (pow & 1) result = result * x % MOD;
    }
    return result;
  }

 public:
  T val;
  // コンストラクタ
  mod_int() : val(0) {}
  mod_int(const mint &o) : val(o.val % MOD) {}
  mod_int(const T &o) : val(o % MOD) {}

  mint &operator+=(const mint &o) {
    val = (val + o.val) % MOD;
    return *this;
  }
  mint &operator-=(const mint &o) {
    val = (val + MOD - o.val) % MOD;
    return *this;
  }
  mint &operator*=(const mint &o) {
    val = (val * o.val) % MOD;
    return *this;
  }
  mint &operator/=(const mint &o) {
    val = (val * inverse(o.val)) % MOD;
    return *this;
  }

  mint &operator++() {
    val = (++val) % MOD;
    return *this;
  }

  mint &operator--() {
    val = (--val) % MOD;
    return *this;
  }

  mint operator+(const mint &o) const { return mint(*this) += o; }
  mint operator-(const mint &o) const { return mint(*this) -= o; }
  mint operator*(const mint &o) const { return mint(*this) *= o; }
  mint operator/(const mint &o) const { return mint(*this) /= o; }

  void operator=(const mint &o) { this->val = o.val; }
  void operator=(const int i) { this->val = i; }
  void operator=(const T i) { this->val = i; }

  bool operator<(const mint &o) const { return val < o.val; }
  bool operator<=(const mint &o) const { return val <= o.val; }
  bool operator==(const mint &o) const { return val == o.val; }
};

