const LL MAX = 440000;
const LL mod = 1e9 + 7;
LL fac[MAX];
LL inv[MAX];

LL pow_mod(LL n, LL p) {
    LL ret = 1;
    while (p > 0) {
        if (p & 1) ret = (ret * n) % mod;
        n = (n * n) % mod;
        p >>= 1;
    }
    return ret;
}

void setup() {
    fac[0] = fac[1] = 1;
    inv[0] = inv[1] = 1;
    for (LL i = 2; i < MAX - 1; i++) {
        fac[i] = fac[i - 1] * i;
        fac[i] %= mod;
        inv[i] = pow_mod(fac[i], mod - 2);
    }
}

LL ncr(LL n, LL r) {
    return fac[n] * inv[r] % mod * inv[n - r] % mod;
}

int main() {

    setup();

    LL N, M, K;
    cin >> N >> M >> K;
    LL ans = 0;

    // calc X
    LL X = 0;
    for (LL i = 0; i < M; i++) {
        LL d = i * (M - i);
        d %= mod;
        d *= N;
        d %= mod;
        d *= N;
        d %= mod;
        X += d;
        X %= mod;
    }

    LL Y = 0;
    for (LL i = 0; i < N; i++) {
        LL d = i * (N - i);
        d %= mod;
        d *= M;
        d %= mod;
        d *= M;
        d %= mod;
        Y += d;
        Y %= mod;
    }

    ans += X;
    ans += Y;
    ans %= mod;

    LL dd = ncr(N * M - 2, K - 2);
    ans *= dd;
    ans %= mod;
    cout << ans << endl;

    return 0;
}

