    repe(i, 1, 1e6 + 1) finv[i] = finv[i - 1] * (ll)(1e6 - i + 1) % mod;
    reverse(all(finv));

    //inv init
    repe(i, 1, 1e6 + 1) inv[i] = modpow(i, mod - 2, mod);
}

ll perm(ll a, ll b) { return fac[a] * finv[a - b] % mod; }

ll comb(ll a, ll b) { return fac[a] * finv[b] % mod * finv[a - b] % mod; }

int main() {
    init();
