    fac_init();
    ll ans = 0;
    vl sum(S + 1, 0);
    rep(i,S)
        sum[i + 1] = sum[i] + i + 1;

    ll C = comb(S - 2, K - 2);
    rep(i,N)rep(j,M){
        ll tmp = 0;
        ll l, r;
        // 探索点の右で縦にわって２つの四角形の累積和を考える, l=探索点を含む列のマンハッタン距離, r=探索点の右隣
        l = sum[i] + sum[N - i - 1];
        r = l + N;
        l = (j + 1) * l % mod + N * (j + 1) * j % mod * inv[2] % mod;
        r = (M - j - 1) * r % mod + N * (M - j - 1) * (M - j - 2) % mod * inv[2] % mod;
        ans = (ans + l * C % mod + r * C % mod) % mod;
    }
    ans = ans * inv[2] % mod;
    cout << ans << endl;
    return 0;
}

