int mpow(int x, int n)
{  //x^n(mod M) ←普通にpow(x,n)では溢れてしまうため，随時mod計算
    int ans = 1;
    while (n != 0) {
        if (n & 1)
            ans = (ans * x) % MOD;
        x = (x * x) % MOD;
        n = n >> 1;
    }
    return ans;
}

int comb(int a, int b)
{  //aCbをmod計算
    if (a == 0 && b == 0)
        return 1;
    if (a < b || a <= 0)
        return 0;
    int tmp = ifac[a - b] * ifac[b] % MOD;
    return tmp * fac[a] % MOD;
}

