long int extGCD(long int a, long int b, long int *x, long int *y) {
    if (b == 0) {
        *x = 1;
        *y = 0;
        return a;
    }
    long int d = extGCD(b, a%b, y, x);
    *y -= a / b * (*x);
    return d;
}

long int comb_mod(long int n, long int r) {
    long int deno = 1;
    long int mole = 1;
    long int r_change = (r <= n / 2) ? r : n - r;
    for (int i=1; i<=r_change; i++) {
        mole = mole * i % mod;
    }
    for (int i=n-r_change+1; i<=n; i++) {
        deno = deno * i % mod;
    }
    long int x = 0, mole_inv = 0;
    extGCD(mod, mole%mod, &x, &mole_inv);
    mole_inv = mole_inv % mod;
    return (deno * mole_inv) % mod;
}

