        com += mod;
    }
    for (int i=1; i<w; i++) {
        long int num = (h * h) % mod;
        long int hoge = (w - i) % mod;
        sum_x += (((((com * num) % mod) * hoge) % mod) * i) % mod;
        sum_x = sum_x % mod;
    }
    long int sum_y = 0;
    for (int i=1; i<h; i++) {
        long int num = (w * w) % mod;
        long int hoge = (h - i) % mod;
        sum_y += (((((com * num) % mod) * hoge) % mod) * i) % mod;
        sum_y = sum_y % mod;
    }
