void swap(long long* a, long long* b){
  *a ^= *b;
  *b ^= *a;
  *a ^= *b;
}

long long inv(long long x){
  long long m = mod, u = 1, v = 0;
  while(m){
    long long t = x / m;
    x -= t * m; swap(&x, &m);
    u -= t * v; swap(&u, &v);
  }
  u %= mod;
  if(u < 0) u += mod;
  return u;
}

