fun powMod(n: Long, l: Long): Long {
    var k = l
    var a = 1L;
    var m = n
    while (k > 0) {
        if (k % 2 == 1L) {
            a = (a * m) % MOD;
        }
        m = (m * m) % MOD;
        k /= 2L
    }

    return a
}

