fun pow(base: Long, exp: Long): Long{
    var base = base
    var exp = exp
    var ret = 1L
    while (exp>0) {
        if(exp%2==1L) ret = ret x base
        base = base x base
        exp /= 2
    }
    return ret
}

fun inv(n: Long) = pow(n, MOD-2)

fun combination(n: Long, k: Long) : Long{
    val n = n.toInt()
    val k = k.toInt()
    val denominator = (fact[k]*fact[n-k]) % MOD
    return (fact[n]*pow(denominator, MOD-2)) % MOD
}

import java.util.Scanner;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n=sc.nextInt();
		int m=sc.nextInt();
		int k=sc.nextInt();
		long mod=1000000007;
		long ans=0;
		for(int i=1; i<=m; i++){
			ans+=((((m-i+1)*(m-i)/2)*((n*n)%mod))%mod)*Combination(n*m-2,k-2,mod);
			ans%=mod;
		}
		for(int i=1; i<=n; i++){
			ans+=((((n-i+1)*(n-i)/2)*((m*m)%mod))%mod)*Combination(n*m-2,k-2,mod);
			ans%=mod;
		}
		System.out.println(ans);
	}
	static long Combination(int left,int right,long mod){
		long ans=1;
		right=Math.min(right,left-right);
		for(int i=0; i<right; i++){
			ans*=(left-i);
			ans%=mod;
		}
		for(int i=2; i<=right; i++){
			long tmp=mod-2;
			long mul=i;
			while(tmp>0){
				if((tmp&1)==1){
					ans*=mul;
				}
				tmp>>=1;
				mul*=mul;
				ans%=mod;
				mul%=mod;
			}
		}
		return ans;
	}
}

