        long[][] sum = new long[n][m];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                sum[i][j] += i + j;
                if(0 < i) sum[i][j] = (sum[i][j] + sum[i-1][j]) %mod;
                if(0 < j) sum[i][j] = (sum[i][j] + sum[i][j-1]) %mod;
                if(0 < i && 0 < j) sum[i][j] = (sum[i][j] - sum[i-1][j-1] + mod) %mod;
            }
        }
        long ans = 0;
        for (int i = 0; i < n; i++) {
