    static class ECellDistance {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long n = in.nextInt();
            long m = in.nextInt();
            long k = in.nextInt();
            long mod = 10000_0000_7;
            long dist = 0;
            long temp = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = i + 1; j <= n; j++) {
                    temp += Math.abs(j - i);
                    temp %= mod;
                }
            }
            dist += (temp * ((m * m) % mod)) % mod;
            temp = 0;
            for (int i = 1; i <= m; i++) {
                for (int j = i + 1; j <= m; j++) {
                    temp += Math.abs(j - i);
                    temp %= mod;
                }
            }
            dist += (temp * ((n * n) % mod)) % mod;
//        dist = (dist * Maths.power(2,mod-2,mod))%mod;
            long up = 1;
            long down = 1;
            for (int i = 1; i <= n * m - 2; i++) {
                up *= i;
                up %= mod;
            }
            for (int i = 1; i <= k - 2; i++) {
                down *= i;
                down %= mod;
            }
            for (int i = 1; i <= n * m - k; i++) {
                down *= i;
                down %= mod;
            }
            long downinv = Maths.power(down, mod - 2, mod);
            out.println((dist * ((up * downinv) % mod)) % mod);
        }

    }

