    }

    for(long i = 1; i < n; i++) {
      long kosuu = ((n - i) * m) % MOD;
      kosuu = (kosuu * m) % MOD;
      kosuu = (kosuu * i) % MOD;
      kosuu = (kosuu * com((n * m - 2), k - 2)) % MOD;
      ans = (ans + kosuu) % MOD;
    }

    for(long i = 1; i < m; i++) {
      long kosuu = ((m - i) * n) % MOD;
      kosuu = (kosuu * n) % MOD;
      kosuu = (kosuu * i) % MOD;
      kosuu = (kosuu * com((n * m - 2), k - 2)) % MOD;
      ans = (ans + kosuu) % MOD;
    }

    System.out.println(ans);
  }

  public static long func(long a, long x) {
    if(x == 0) {
      return 1;
    } else if(x == 1) {
      return a % MOD;
    } else {
      if(x % 2 == 0) {
        return (func(a, x / 2) * func(a, x / 2)) % MOD;
      } else {
        return (a * func(a, x - 1)) % MOD;
      }
    }
  }

  public static long com(long s, long t) {
    if(s >= t) {
      long t1 = func(kai[(int)t], MOD - 2);
      long t2 = func(kai[(int)(s - t)], MOD - 2);
      long t3 = (kai[(int)s] * t1) % MOD;
      return (t3 * t2) % MOD;
    } else {
      return 0;
    }
  }
}

