    	long res=1;
    	while (n>0) {
    		if ((n-n/2*2)==1) {
    			res=res*a%mod;
    		}
    		a=a*a%mod;
    		n>>=1;
    	}
    	return res%mod;
    }

    static long modinv(long a,long mod) {
        return pow(a,mod-2);
    }
