		for(int i=n-1;i>=1;i--) count = (count + (i*(i+1)/2)*m*m) % mod;
		for(int i=m-1;i>=1;i--) count = (count + (i*(i+1)/2)*n*n) % mod;
		System.out.println((count*nCk(n*m-2,k-2,mod))%mod);
