public class Main {
	static final long MOD = 1000000007l;

	private static void solve() {
		long n = nei();
		long m = nei();
		long k = nei();

		long sumC = 0;
		for (int x = 1; x <= n; x++) {
			for (int y = 1; y <= m; y++) {
				long yoko = mmul(m, mdiv(madd(mmul(x - 1, x), mmul(n - x, n - x + 1)), 2));
				long tate = mmul(n, mdiv(madd(mmul(y - 1, y), mmul(m - y, m - y + 1)), 2));
				long heikin = mdiv(madd(yoko, tate), n * m - 1);
				sumC = madd(sumC, heikin);
			}
		}
		long c = mdiv(sumC, n * m);
		long avg = mmul(c, mmul(k, (k - 1)) / 2);
		long res = mmul(avg, modcomb(m * n, k, MOD));

		out(res);
	}

	static long mmul(long a, long b) {
		return a * b % MOD;
	}

	static long madd(long a, long b) {
		return (a + b) % MOD;
	}

	static long mdiv(long a, long b) {
		return mmul(a, modinv(b, MOD));
	}

	// returns (x, y, d) s.t. ax + by = d
	static long[] exgcd(long a, long b) {
		int sa = a < 0 ? -1 : 1;
		int sb = b < 0 ? -1 : 1;
		a *= sa;
		b *= sb;
		long x = 1;
		long y = 0;
		long z = 0;
		long w = 1;
		while (b > 0) {
			long q = a / b;
			long t = z;
			z = x - q * z;
			x = t;
			t = w;
			w = y - q * w;
			y = t;
			t = b;
			b = a - q * b;
			a = t;
		}
		return new long[] { x * sa, y * sb, a };
	}

	static int[] lis(int[] s) {
		int n = s.length;
		int[] dp = new int[n];
		int[] ids = new int[n];
		int[] pids = new int[n];
		dp[0] = s[0];
		int len = 1;
		int lidx = 0;
		for (int i = 1; i < n; i++) {
			int idx = bs(s[i], dp, 0, len);
			dp[idx] = s[i];
			ids[idx] = i;
			if (idx == len) {
				lidx = i;
				len++;
			}
			if (idx > 0)
				pids[i] = ids[idx - 1];
		}
		int[] lis = new int[len];
		lis[len - 1] = s[lidx];
		for (int i = len - 1; i >= 0; i--) {
			lis[i] = s[lidx];
			lidx = pids[lidx];
		}
		return lis;
	}

	static int bs(int a, int[] as, int from, int num) {
		int min = from;
		int max = from + num - 1;
		while (min < max) {
			int mid = min + max >> 1;
			if (as[mid] < a)
				min = mid + 1;
			else if (as[mid] > a)
				max = mid;
			else
				return mid;
		}
		return as[min] < a ? min + 1 : min;
	}

	static int gcd(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		int z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static long gcd(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		long z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static long modinv(long a, long mod) {
