class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		int K = sc.nextInt();
		long mod=1_000_000_007L;
		long ans=0L;
		for (int i=0;i<M;i++) {
			ans+=(i*(M-i)*(N*N))%mod;
			ans=ans%mod;
		}
		for (int i=0;i<N;i++) {
			ans+=(i*(N-i)*(M*M))%mod;
			ans=ans%mod;
		}
		long cnt=calcNumOfCombination(N*M-2,K-2)%mod;
		System.out.println((ans*cnt)%mod);
	}

    static long calcNumOfCombination(int n, int r){
    	long mod=1_000_000_007L;
    	return ((factorial(n)%mod*modinv(factorial(n-r),mod))%mod*modinv(factorial(r),mod))%mod;
    }

    static long factorial(int n) {
    	long num=1L;
    	long mod=1_000_000_007L;
    	for (int i=n;i>0;i--) {
    		num=num*i;
    		num%=mod;
    	}
    	return num;
    }

    static long pow(long a,long n) {
    	long mod=1_000_000_007L;
    	long res=1;
    	while (n>0) {
    		if ((n-n/2*2)==1) {
    			res=res*a%mod;
    		}
    		a=a*a%mod;
    		n>>=1;
    	}
    	return res;
    }

    static long modinv(long a,long mod) {
        return pow(a,mod-2);
    }
}

import java.util.Scanner;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n=sc.nextInt();
		int m=sc.nextInt();
		int k=sc.nextInt();
		long mod=1000000007;
		long count=0;
		for(int i=1; i<=m; i++){
			count+=((n*n)%mod)*((m-i+1)*(m-i)/2)%mod;
			count%=mod;
		}
		for(int i=1; i<=n; i++){
			count+=((m*m)%mod)*((n-i+1)*(n-i)/2)%mod;
			count%=mod;
		}
		System.out.println((count*Combination(n*m-2,k-2,mod))%mod);
	}
	static long Combination(int left,int right,long mod){
		long ans=1;
		right=Math.min(right,left-right);
		for(int i=0; i<right; i++){
			ans*=(left-i);
			ans%=mod;
		}
		for(int i=2; i<=right; i++){
			long tmp=mod-2;
			long mul=i;
			while(tmp>0){
				if((tmp&1)==1){
					ans*=mul;
				}
				tmp>>=1;
				mul*=mul;
				ans%=mod;
				mul%=mod;
			}
		}
		return ans;
	}
}

