      long N2 = N * N;

      long ans = 0;
      for (long i=0; i<N; i++) {
        ans += ((((N-i-1)*(N-i)/2) % MOD) * ((C * M2)%MOD)) % MOD;
      }
      for (long i=0; i<M; i++) {
        ans += ((((M-i-1)*(M-i)/2) % MOD) * ((C * N2)%MOD)) % MOD;
      }

      ans %= MOD;

      out.println(ans);

    }
