		int m = sc.nextInt();
		int k = sc.nextInt();

		PC pc = new PC(n * m, MOD);

		long ans = 0;
		for (int i = 0; i < n; i++) {
			long tmp = f(n - 1 - i) * m % MOD * m % MOD;
			ans += tmp;
			ans %= MOD;
		}
		for (int j = 0; j < m; j++) {
			long tmp = f(m - 1 - j) * n % MOD * n % MOD;
			ans += tmp;
			ans %= MOD;
		}

		ans *= pc.C(n * m - 2, k - 2);
		ans %= MOD;

		pr.println(ans);
	}

	private static long f(int x) {
		if (x <= 0) {
			return 0L;
		}

		return (long)x * (x + 1) / 2 % MOD;
	}

	static final int MOD = 1_000_000_007;

	/**
	 * 組合せの数、順列、重複組み合わせなどを求める
	 * MOD による剰余を返す
