  static final int[] dx = {0, 1, 0, -1};
  static final int[] dy = {-1, 0, 1, 0};

  static final long MOD = (long) (1e9 + 7);
  static final long INF = Long.MAX_VALUE / 2;

  static long[] fact;

  public static class Solver implements Runnable {
    public void run() {

      long N = sc.nextLong();
      long M = sc.nextLong();

      fact = new long[(int)(N*M)+1];

      long K = sc.nextLong();

      long C = comb(M*N-2, K-2);
      long M2 = M * M;
      long N2 = N * N;

      long ans = 0;
      for (long i=0; i<N; i++) {
        ans += ((((N-i-1)*(N-i)/2) % MOD) * C * M2) % MOD;
      }
      for (long i=0; i<M; i++) {
        ans += ((((M-i-1)*(M-i)/2) % MOD) * C * N2) % MOD;
      }

      ans %= MOD;

      out.println(ans);

    }
  }

  public static long power(long a, long b) {
    if (b == 0) return 1;

    if (b % 2 == 0) {
      long p = power(a, b/2);
      return (p * p) % MOD;
    } else {
      return (a * power(a, b - 1)) % MOD;
    }
  }

  public static long factorial(long n) {
    if (n == 0) return 1;
    if (fact[(int)n] == 0) {
      return fact[(int)n] = (n * factorial(n - 1)) % MOD;
    } else {
      return fact[(int)n];
    }
  }

  public static long factorialInverse(long n) {
    return power(factorial(n), MOD-2);
  }

  public static long comb(long n, long r) {
    if (r < 0 || r > n) return 0;
    return (((factorial(n) * factorialInverse(r)) % MOD) * factorialInverse(n-r)) % MOD;
  }


