import java.util.Scanner;

public class Main {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int n = in.nextInt();
		int m = in.nextInt();
		int k = in.nextInt();
		int mod = 1000000007;
		long count = 0;
		for(long i=n-1;i>=1;i--) count = (count + (i*(i+1)*m*m)/2) % mod;
		for(long i=m-1;i>=1;i--) count = (count + (i*(i+1)*n*n)/2) % mod;
		System.out.println((count*nCk(n*m-2,k-2,mod))%mod);
		in.close();
	}

	//return a^b mod M O(logB)
		public static long pow(long a,long b,int M) {
			long ret = 1;
			long tmp = a;
			while(b>0) {
				if((b&1)==1) ret = (ret * tmp) % M;
				tmp = (tmp * tmp) % M;
				b = b>>1;
			}
			return ret;
		}

		//return nCk mod M (M must be prime number) O(min(k,n-k)*logM)
		public static int nCk(int n,int k,int M) {
			long ret = 1;
			int min = Math.min(k, n-k);
			for(int i=1;i<=min;i++) {
				ret = (ret * pow(i,M-2,M)) % M;
			}
			for(int i=n-min+1;i<=n;i++) {
				ret = (ret * i) % M;
			}
			return (int)ret;
		}

}

import java.util.Scanner;
public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int n=sc.nextInt();
		int m=sc.nextInt();
		int k=sc.nextInt();
		long mod=1000000007;
		long count=0;
		for(int i=1; i<=m; i++){
			count+=((n*n)%mod)*(((m-i+1)*(m-i))/2)%mod;
			count%=mod;
		}
		for(int i=1; i<=n; i++){
			count+=((m*m)%mod)*(((n-i+1)*(n-i))/2)%mod;
			count%=mod;
		}
		System.out.println((count*Combination(n*m-2,k-2,mod))%mod);
	}
	static long Combination(int left,int right,long mod){
		long ans=1;
		right=Math.min(right,left-right);
		for(int i=0; i<right; i++){
			ans*=(left-i);
			ans%=mod;
		}
		for(int i=2; i<=right; i++){
			long tmp=mod-2;
			long mul=i;
			while(tmp>0){
				if((tmp&1)==1){
					ans*=mul;
				}
				tmp>>=1;
				mul*=mul;
				ans%=mod;
				mul%=mod;
			}
		}
		return ans;
	}
}

import java.io.*;
import java.util.*;

class Main {
	static final int MOD = 1000000007;

	public static void main(String[] args) throws Exception {
		final Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();

		int M = sc.nextInt();
		int K = sc.nextInt();

		long x = 0;
		Combination c = new Combination(N * M, MOD);

		for (int dx = 0; dx < M; dx++) {
			x += dx * N * N * (M - dx);
			x %= MOD;
		}

		long y = 0;
		for (int dy = 0; dy < N; dy++) {
			y += dy * M * M * (N - dy);
			y %= MOD;
		}

		System.out.println((((x + y) % MOD) * c.choose(N * M - 2, K - 2)) % MOD);
	}

	private static class Combination {
		private final int M;
		private long[] fact;
		private long[] ifact;
		private long[] inv;

		public Combination(int n, int M) {
			this.M = M;
			fact = new long[n + 1];
			ifact = new long[n + 1];
			inv = new long[n + 1];

			fact[0] = fact[1] = 1;
			ifact[0] = ifact[1] = 1;
			inv[1] = 1;

			for (int i = 2; i <= n; i++) {
				fact[i] = fact[i - 1] * i % M;
				// p = (p / a * a) + (p % a)
				// 0 ≡ (p / a * a) + (p % a)          (mod p)
				// a^(-1) ≡ - (p % a)^(-1) * (p / a)  (mod p)
				inv[i] = M - inv[M % i] * (M / i) % M;
				ifact[i] = ifact[i - 1] * inv[i] % M;
			}
		}

		public long choose(int n, int k) {
			if (n < k) return 0;
			if (n < 0 || k < 0) return 0;
			return fact[n] * (ifact[k] * ifact[n - k] % M) % M;
		}
	}
}

public class Main {


  private static void solve() {
    long n = ni();
    long m = ni();
    long k = ni();

    int mod = (int)1e9 + 7;
    int[][] fif = enumFIF(300000, mod);

    long ret = 0;
    for (int d = 1; d < n; d ++) {
      ret += m * m * (n - d) * d;
      ret %= mod;
     }
    for (int d = 1; d < m; d ++) {
      ret += n * n * (m - d) * d;
      ret %= mod;
     }

    System.out.println(ret * CX(n * m - 2, k - 2, mod, fif) % mod);
  }


  public static long CX(long n, long r, int p, int[][] fif)
  {
      if(n < 0 || r < 0 || r > n)return 0;
      int np = (int)(n%p), rp = (int)(r%p);
      if(np < rp)return 0;
      if(n == 0 && r == 0)return 1;
      int nrp = np-rp;
      if(nrp < 0)nrp += p;
      return (long)fif[0][np]*fif[1][rp]%p*fif[1][nrp]%p*CX(n/p, r/p, p, fif)%p;
  }

  public static int[][] enumFIF(int n, int mod)
  {
      int[] f = new int[n+1];
      int[] invf = new int[n+1];
      f[0] = 1;
      for(int i = 1;i <= n;i++){
          f[i] = (int)((long)f[i-1] * i % mod);
      }
      long a = f[n];
      long b = mod;
      long p = 1, q = 0;
      while(b > 0){
          long c = a / b;
          long d;
          d = a; a = b; b = d % b;
          d = p; p = q; q = d - c * q;
      }
      invf[n] = (int)(p < 0 ? p + mod : p);
      for(int i = n-1;i >= 0;i--){
          invf[i] = (int)((long)invf[i+1] * (i+1) % mod);
      }
      return new int[][]{f, invf};
  }


