    /**
     * 距離 |a - b| はM個のマスから a, b を除いた M-2個に残りの K-2個のコマを置く場合の数だけ重複する。
     * 重複度は C(M-2, K-2) となる。
     */
    private void solveE() {
        int n = nextInt();
        int m = nextInt();
        int k = nextInt();

        final long CONST_MOD = (long) (Math.pow(10, 9) + 7);
		/*
		まず、1次元で考える。
		1次元では距離dの駒のペアはM-d個
		上記ペアの距離の総和はd(M-d)と表せる。
		距離dを1からM-1まで動かして総和を計算する。
		 */
        long dx = 0;
        for (int i = 1; i < m; i++) {
            dx += n % CONST_MOD * n % CONST_MOD * i % CONST_MOD * (m - i) % CONST_MOD;
        }
        long dy = 0;
        for (int i = 1; i < n; i++) {
            dy += m % CONST_MOD * m % CONST_MOD * i % CONST_MOD * (n - i) % CONST_MOD;
        }
        Combination combination = new Combination(n * m);
        long res = combination.combination(n * m - 2, k - 2);
        res *= dx % CONST_MOD + dy % CONST_MOD;
        res %= CONST_MOD;

        out.println(res);
    }

