import java.util.*;

public class Main {
  public static long MOD = (long)Math.pow(10, 9) + 7;
  public static long[] kai;
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    long n = sc.nextLong();
    long m = sc.nextLong();
    long k = sc.nextLong();
    long ans = 0;

    kai = new long[200001];
    kai[0] = 1;
    for(long i = 1; i < 200001; i++) {
      kai[(int)i] = (kai[(int)i - 1] * i) % MOD;
    }

    for(long i = 1; i < n; i++) {
      long kosuu = ((n - i) * m) % MOD;
      kosuu = (kosuu * m) % MOD;
      kosuu = (kosuu * i) % MOD;
      kosuu = (kosuu * com((n * m - 2), k - 2)) % MOD;
      ans = (ans + kosuu) % MOD;
    }

    for(long i = 1; i < m; i++) {
      long kosuu = ((m - i) * n) % MOD;
      kosuu = (kosuu * n) % MOD;
      kosuu = (kosuu * i) % MOD;
      kosuu = (kosuu * com((n * m - 2), k - 2)) % MOD;
      ans = (ans + kosuu) % MOD;
    }

    System.out.println(ans);
  }

  public static long func(long a, long x) {
    if(x == 0) {
      return 1;
    } else if(x == 1) {
      return a % MOD;
    } else {
      if(x % 2 == 0) {
        long q = func(a, x / 2);
        return (q * q) % MOD;
      } else {
        return (a * func(a, x - 1)) % MOD;
      }
    }
  }

  public static long com(long s, long t) {
    if(s >= t) {
      long t1 = func(kai[(int)t], MOD - 2);
      long t2 = func(kai[(int)(s - t)], MOD - 2);
      long t3 = (kai[(int)s] * t1) % MOD;
      return (t3 * t2) % MOD;
    } else {
      return 0;
    }
  }
}

import java.util.Scanner;
import java.util.stream.LongStream;

/**
 * 解説に書かれた合計式を展開した計算方法
 */
public class Main {

	private static final long MOD = 1_000_000_007;

	public static void main(String[] args) {
		try (Scanner scanner = new Scanner(System.in)) {
			int n = scanner.nextInt(), m = scanner.nextInt(), k = scanner.nextInt();
			// 1からnまでのi*(n-i)は (n-1)n(n+1)/6
			long xSum = n * (n - 1) % MOD * (n + 1) % MOD * powMod(6, MOD - 2) % MOD * m % MOD * m % MOD;
			long ySum = m * (m - 1) % MOD * (m + 1) % MOD * powMod(6, MOD - 2) % MOD * n % MOD * n % MOD;
			System.out.println((xSum + ySum + MOD) % MOD * combinationMod(n * m - 2, k - 2) % MOD);
		}
	}

	/**
	 * n_C_m mod MOD を計算する
	 * 
	 * @param n
	 * @param m
	 * @return n_C_m mod MOD
	 */
	private static long combinationMod(long n, int m) {
		long min = Math.min(m, n - m), max = Math.max(m, n - m);
		long factorialMin = LongStream.rangeClosed(1, min).reduce(1L, (result, next) -> result = result * next % MOD);
		long factorialMax = LongStream.rangeClosed(1, max).reduce(1L, (result, next) -> result = result * next % MOD);
		long factorialN = LongStream.rangeClosed(1, n).reduce(1L, (result, next) -> result = result * next % MOD);
		return factorialN * powMod(factorialMin, MOD - 2) % MOD * powMod(factorialMax, MOD - 2) % MOD;
	}

	/**
	 * n^m mod MOD を計算する
	 * 
	 * @param n
	 * @param m
	 * @return n^m mod MOD
	 */
	private static long powMod(long n, long m) {
		long result = 1L;
		while (m > 0) {
			if (1 == (1 & m)) {
				result = result * n % MOD;
			}
			n = n * n % MOD;
			m >>= 1;
		}
		return result;
	}
}

import java.util.*;

class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		int K = sc.nextInt();
		long mod=1_000_000_007L;
		long ans=0L;
		for (int i=0;i<M;i++) {
			ans+=(N*i%mod*(M-i)%mod*N%mod)%mod;
			ans=ans%mod;
		}
		for (int i=0;i<N;i++) {
			ans+=(M*i%mod*(N-i)%mod*M%mod)%mod;
			ans=ans%mod;
		}
		long cnt=calcNumOfCombination(N*M-2,K-2);
		System.out.println((ans*cnt)%mod);
	}

    static long calcNumOfCombination(int n, int r){
    	long mod=1_000_000_007L;
    	return ((factorial(n)*modinv(factorial(n-r),mod))%mod*modinv(factorial(r),mod))%mod;
    }

    static long factorial(int n) {
    	long num=1L;
    	long mod=1_000_000_007L;
    	for (int i=n;i>0;i--) {
    		num=num*i;
    		num%=mod;
    	}
    	return num;
    }

    static long pow(long a,long n) {
    	long mod=1_000_000_007L;
    	long res=1;
    	while (n>0) {
    		if ((n-n/2*2)==1) {
    			res=res*a%mod;
    		}
    		a=a*a%mod;
    		n>>=1;
    	}
    	return res;
    }

    static long modinv(long a,long mod) {
        return pow(a,mod-2);
    }
}

