	class ModLong {
		long MOD;
		long value;
		public ModLong(long value, long MOD) {
			this.value = value;
			this.MOD = MOD;
		}
		public ModLong add(long value) {
			this.value = (this.value + value) % MOD;
			return this;
		}
		public ModLong mul(long value) {
			this.value = (this.value * value) % MOD;
			return this;
		}
