public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    // static int mod = 1_000_000_007;
    int mod = 998244353;
    // long inf = Long.MAX_VALUE/2;
    int inf = Integer.MAX_VALUE/2;


    void solve(){
        int n = ni();
        int m = ni();
        int k = ni();
        int mod = 1000000007;
        int[][] fif = enumFIF(1000000, mod);

        long xsum = 0;
        long ysum = 0;

        long xa = C(n*m-2,k-2,mod,fif) * fif[0][k-2] % mod;
        long xb = 0;
        for(int i = 0; i <= m-1; i++){
            long tmp = (long)i * (m-i) % mod * n % mod * n % mod * 2 % mod;
            xb += tmp;
            xb %= mod;
        }
        long xc = xa * xb % mod * C(k,2,mod,fif) % mod;
        xsum = xc * fif[1][k] % mod;
        // out.println(xa+" "+xb+" "+xc);
        // out.println(xsum);

        long ya = C(n*m-2,k-2,mod,fif) * fif[0][k-2] % mod;
        long yb = 0;
        for(int i = 0; i <= n-1; i++){
            long tmp = (long)i * (n-i) % mod * m % mod * m % mod * 2 % mod;
            yb += tmp;
            yb %= mod;
        }
        long yc = ya * yb % mod * C(k,2,mod,fif) % mod;
        ysum = yc * fif[1][k] % mod;

        // out.println(ysum);

        out.println((xsum+ysum)%mod);

    }

    public static long C(int n, int r, int mod, int[][] fif) {
        if (n < 0 || r < 0 || r > n)
            return 0;
        return (long) fif[0][n] * fif[1][r] % mod * fif[1][n - r] % mod;
    }


    public static int[][] enumFIF(int n, int mod) {
        int[] f = new int[n + 1];
        int[] invf = new int[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) {
            f[i] = (int) ((long) f[i - 1] * i % mod);
        }
        long a = f[n];
        long b = mod;
        long p = 1, q = 0;
        while (b > 0) {
            long c = a / b;
            long d;
            d = a;
            a = b;
            b = d % b;
            d = p;
            p = q;
            q = d - c * q;
        }
        invf[n] = (int) (p < 0 ? p + mod : p);
        for (int i = n - 1; i >= 0; i--) {
            invf[i] = (int) ((long) invf[i + 1] * (i + 1) % mod);
        }
        return new int[][] { f, invf };
    }


    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

