class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int M = sc.nextInt();
		int K = sc.nextInt();
		long mod=1_000_000_007L;
		long ans=0L;
		for (int i=0;i<M;i++) {
			ans+=(i*(M-i)*(N*N))%mod;
			ans=ans%mod;
		}
		for (int i=0;i<N;i++) {
			ans+=(i*(N-i)*(M*M))%mod;
			ans=ans%mod;
		}
		long cnt=calcNumOfCombination(N*M-2,K-2)%mod;
		System.out.println((ans*cnt)%mod);
	}

    static long calcNumOfCombination(int n, int r){
    	long mod=1_000_000_007L;
    	return ((factorial(n)%mod*modinv(factorial(n-r),mod))%mod*modinv(factorial(r),mod))%mod;
    }

    static long factorial(int n) {
    	long num=1L;
    	long mod=1_000_000_007L;
    	for (int i=n;i>0;i--) {
    		num=num*i;
    		num%=mod;
    	}
    	return num;
    }

    static long pow(long a,long n) {
    	long mod=1_000_000_007L;
    	long res=1;
    	while (n>0) {
    		if ((n-n/2*2)==1) {
    			res=res*a%mod;
    		}
    		a=a*a%mod;
    		n>>=1;
    	}
    	return res%mod;
    }

    static long modinv(long a,long mod) {
        return pow(a,mod-2);
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		long n = Integer.parseInt(sa[0]);
		long m = Integer.parseInt(sa[1]);
		long k = Integer.parseInt(sa[2]);
		br.close();

		int mod = 1000000007;
		long x = 0;
		for (long i = 1; i < n; i++) {
			x += i * (n - i);
		}
		x %= mod;
		x *= m;
		x %= mod;
		x *= m;
		x %= mod;

		long y = 0;
		for (long i = 1; i < m; i++) {
			y += i * (m - i);
		}
		y %= mod;
		y *= n;
		y %= mod;
		y *= n;
		y %= mod;

		long ans = x + y;
		ans *= nCr(n * m - 2, k - 2, mod);
		ans %= mod;
		System.out.println(ans);
	}

	static long nCr(long n, long r, int m) {
		long val = 1;
		for (int i = 1; i <= r; i++) {
			val = val * (n - i + 1) % m;
			val = val * modinv(i, m) % m;
		}
		return val;
	}

	static long modinv(long a, int m) {
		long b = m;
		long u = 1;
		long v = 0;
		long tmp = 0;

		while (b > 0) {
			long t = a / b;
			a -= t * b;
			tmp = a;
			a = b;
			b = tmp;

			u -= t * v;
			tmp = u;
			u = v;
			v = tmp;
		}

		u %= m;
		if (u < 0) u += m;
		return u;
	}
}

