namespace AtCoder
{
    class Modular
    {
        private const int M = 1000000007;
        private static readonly List<int> facs = new List<int> { 1 };
        private long value;

        public Modular(long value)
        {
            this.value = value;
        }
        public static implicit operator Modular(long a)
        {
            return new Modular(a % M);
        }
        public static Modular operator +(Modular a, Modular b)
        {
            return (a.value + b.value) % M;
        }
        public static Modular operator -(Modular a, Modular b)
        {
            return ((a.value - b.value) % M + M) % M;
        }
        public static Modular operator *(Modular a, Modular b)
        {
            return a.value * b.value % M;
        }
        private static Modular Pow(Modular a, int n)
        {
            switch (n)
            {
            case 0:
                return new Modular(1);
            case 1:
                return a;
            default:
                var p1 = Pow(a, n / 2);
                var p2 = p1 * p1;
                return ((n % 2) == 0) ? p2 : p2 * a;
            }
        }
        public static Modular operator /(Modular a, Modular b)
        {
            return a * Pow(b, M - 2);
        }
        private static Modular Fac(int n)
        {
            for (int i = facs.Count; i <= n; ++i)
            {
                facs.Add((int)(Math.BigMul(facs.Last(), i) % M));
            }
            return new Modular(facs[n]);
        }
        public static Modular Ncr(int n, int r)
        {
            return (n < r)  ? new Modular(0)
                 : (n == r) ? new Modular(1)
                            : Fac(n) / Fac(r) / Fac(n - r);
        }
        public static explicit operator int(Modular a)
        {
            return (int)a.value;
        }
    }

    class Program
    {
        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static int Solve(int N, int M, int K)
        {
            Modular a = 0, b = 0;
            for (int i = 0; i < N; ++i) { a += Math.BigMul(N - i, i); }
            for (int i = 0; i < M; ++i) { b += Math.BigMul(M - i, i); }
            return (int)((a * M * M + b * N * N) * Modular.Ncr(N * M - 2, K - 2));
        }

        static void Main(string[] args)
        {
            var V = ReadInts();
            Console.WriteLine(Solve(V[0], V[1], V[2]));
        }
    }
}

