            long sum = 0;

            for (int i = 1; i < N; i++)
            {
                sum = (sum + i * (N - i) * M * M) % mod;
            }
            for (int i = 1; i < M; i++)
            {
                sum = (sum + i * (M - i) * N * N) % mod;
            }

            var combination = Combination(N * M - 2, K - 2);

            return sum * combination % mod;
        }
        BigInteger Combination(long n, long k)
        {
            if (n / 2 < k) return Combination(n, n - k);

            BigInteger ret = 1;
            for (var i = 0; i < k; i++)
                ret *= n - i;
            for (var i = k; i > 1; i--)
                ret /= i;
            return ret;
        }

