class Program
{
    static void Main(string[] args)
    {
        var sw = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = false };
        Console.SetOut(sw);
        Solve();
        Console.Out.Flush();
    }
    static void Solve()
    {
        var N = sc.ReadInt();
        var M = sc.ReadInt();
        var K = sc.ReadInt();
        ModInt ans = 0;
        for (int i = 1; i < N; i++)
        {
            ModInt dn = N - i;
            var res = dn * M * M * i;
            ans += res;
        }
        for (int i = 1; i < M; i++)
        {
            ModInt dm = M - i;
            var res = dm * N * N * i;
            ans += res;
        }
        ans *= ModInt.nCr(N * M - 2, K - 2);
        Console.WriteLine(ans);
    }

    public struct ModInt
    {
        public const long Mod = (int)1e9 + 7;
        public long num;
        public ModInt(long n) { num = n; }
        public override string ToString() { return num.ToString(); }
        public static ModInt operator +(ModInt l, ModInt r) { l.num += r.num; if (l.num >= Mod) l.num -= Mod; return l; }
        public static ModInt operator -(ModInt l, ModInt r) { l.num -= r.num; if (l.num < 0) l.num += Mod; return l; }
        public static ModInt operator *(ModInt l, ModInt r) { return new ModInt(l.num * r.num % Mod); }
        public static ModInt operator /(ModInt l, ModInt r) { return l * Inverse(r); }
        public static implicit operator ModInt(long n) { n %= Mod; if (n < 0) n += Mod; return new ModInt(n); }
        public static ModInt Pow(ModInt v, long k) { return Pow(v.num, k); }
        public static ModInt Pow(long v, long k)
        {
            long res = 1;
            while (k > 0)
            {
                if ((k & 1) == 1) res = res * v % Mod;
                v = v * v % Mod;
                k >>= 1;
            }
            return new ModInt(res);
        }
        public static ModInt Inverse(ModInt v) { return Pow(v, Mod - 2); }
        private static List<ModInt> Facs = new List<ModInt> { 1 };
        private static List<ModInt> iFacs = new List<ModInt> { 1 };
        public static ModInt Fac(int n)
        {
            for (int i = Facs.Count; i <= n; i++)
            {
                Facs.Add(i * Facs[i - 1]);
                iFacs.Add(Inverse(Facs[i]));
            }
            return Facs[n];
        }
        public static ModInt iFac(int n)
        {
            Fac(n);
            return iFacs[n];
        }
        public static ModInt nCr(int n, int r, bool loop = false)
        {
            if (n < r) return 0;
            if (n == r) return 1;
            if (loop && n > (int)1e6) return nCrLoop(n, r);
            return Fac(n) * iFac(r) * iFac(n - r);
        }
        public static ModInt nCrLoop(long n, long r)
        {
            ModInt num = 1;
            for (long i = 1; i <= r; i++)
            {
                num = num * (n - i + 1) / i;
            }
            return num;
        }
        public static ModInt nHr(int n, int r)
        {
