    static long mod = (long)1e9 + 7;

    static void Main()
    {
        /* 入力の受け取り */
        string[] input = Console.ReadLine().Split();
        n = int.Parse(input[0]);
        m = int.Parse(input[1]);
        k = int.Parse(input[2]);

        /* Combinationの前計算 */
        Comb c = new Comb(n * m, mod);

        /* 答えの計算 */
        long ans = m * (m - 1) % mod * (m + 1) % mod * n % mod * n % mod * Inv(6);
        ans += n * (n - 1) % mod * (n + 1) % mod * m % mod * m % mod * Inv(6);
        ans %= mod;
        ans *= c.Com(n * m - 2, k - 2);
        ans %= mod;

        /* 答えの出力 */
        Console.WriteLine(ans);
    }

    static long Pow(long a, long k)
    {
        if (k == 0) return 1;
        a %= mod;
        long t = Pow(a, k / 2);
        if (k % 2 == 0)
            return t * t % mod;
        return t * t % mod * a % mod;
    }

    static long Inv(long a)
    {
        return Pow(a, mod - 2);
    }
}

//整数がらみの処理
static class Calc
{
    public static int GCD(int a, int b) //最大公約数の計算
    {
        return a > b ? GcdRecursive(a, b) : GcdRecursive(b, a);
    }

    private static int GcdRecursive(int a, int b)
    {
        return b == 0 ? a : GcdRecursive(b, a % b);
    }

    public static int GCD(params int[] nums) //最大公約数の計算
    {
        int n = nums.Length;
        int ans = GCD(nums[0], nums[1]);
        for (int i = 2; i < n; i++)
            ans = GCD(ans, nums[i]);
        return ans;
    }

    public static int LCM(int n, int m) //最小公倍数の計算
    {
        int gcd = GCD(n, m);
        int a, b;
        a = n / gcd;
        b = m / gcd;
        return gcd * a * b;
    }
}

class Comb
{
    private long size;
    private long[] inv;
    private long[] kai;
    private long[] invkai;
    private long mod;
    public Comb(long size, long mod)
    {
        this.size = size;
        this.mod = mod;
        inv = new long[size + 1];
        kai = new long[size + 1];
        invkai = new long[size + 1];
        inv[1] = 1;
        for (int i = 2; i <= size; i++)
            inv[i] = mod - (mod / i) * inv[mod % i] % mod;
        kai[0] = 1;
        invkai[0] = 1;
        for (int i = 1; i <= size; i++)
        {
            kai[i] = kai[i - 1] * i % mod;
            invkai[i] = invkai[i - 1] * inv[i] % mod;
        }
    }
    public long Com(long a, long b)
    {
        if (a < b || b < 0)
            return 0;
        return (invkai[b] * invkai[a - b]) % mod * kai[a] % mod;
    }
}

