    class Program
    {
        public class Combination
        {
            readonly long mod;
            readonly long[] fac, finv, inv;
            public Combination(long n, long mod = 1000000007)
            {
                long max = n + 1;
                this.mod = mod;
                fac = new long[max];
                finv = new long[max];
                inv = new long[max];
                fac[0] = fac[1] = 1;
                finv[0] = finv[1] = 1;
                inv[1] = 1;
                for (int i = 2; i < max; ++i)
                {
                    fac[i] = fac[i - 1] * i % mod;
                    inv[i] = mod - inv[mod % i] * (mod / i) % mod;
                    finv[i] = finv[i - 1] * inv[i] % mod;
                }
            }
            public long com(int n, int k)
            {
                if (n < k) return 0;
                if (n < 0 | k < 0) return 0;
                return fac[n] * (finv[k] * finv[n - k] % mod) % mod;
            }
        }
        static public List<int> SIn() { return ReadLine().Split().Select(int.Parse).ToList(); }
        static void Main(string[] args)
        {
            var NMK = SIn();
            var N = NMK[0];//N行
            var M = NMK[1];//M列
            var K = NMK[2];//K個

            long mod = 1000000000 + 7;
            long nsum = 0;
            for (int i = 1; i <= N - 1; ++i)
            {
                nsum = nsum + i * (N - i) % mod;
                nsum %= mod;
            }
            long msum = 0;
            for (int i = 1; i <= M - 1; ++i)
            {
                msum = msum + i * (M - i) % mod;
                msum %= mod;
            }
            long sum = (nsum * (M * M) % mod) % mod + (msum * (N * N) % mod) % mod;
            sum %= mod;
            var cmb = new Combination(N * M - 2, mod);
            sum = sum * cmb.com(N * M - 2, K - 2) % mod;
            WriteLine(sum);
        }
    }
}

