namespace Competitive
{
    internal class Solution
    {
        public int N, M, K;
        public long MOD = 1000000007;
        public FermatCombination com;
        public void Run()
        {
            com = new FermatCombination(210000);
            {
                var line = Input.ReadIntArray();
                N = line[0];
                M = line[1];
                K = line[2];
            }

            long num = com.Combination(N * M, K);
            num %= MOD;
            long combpiece = com.Combination(K, 2);

            long x = avgsum(N) * M * M + avgsum(M) * N * N;
            x %= MOD;

            long divisor1 = (N * M) - 1;
            long divisor2 = (N * M);

            // 解答の計算
            long ret = 1;
            ret *= num;
            ret %= MOD;
            ret *= combpiece;
            ret %= MOD;

            ret *= x;
            ret %= MOD;
            ret *= div(divisor1);
            ret %= MOD;
            ret *= div(divisor2);
            ret %= MOD;
            Console.WriteLine(ret);
        }

        long avgsum(int length)
        {
            long ret = 0;
            for (int i = 0; i < length; i++)
            {
                long left = i;
                long right = length - 1 - i;
                ret += left * (left + 1) / 2L;
                ret += right * (right + 1) / 2L;
            }
            return ret;
        }

        long div(long divisor)
        {
            long ret = 1;
            ret *= com.Inverse[divisor];
            ret %= MOD;
            ret *= com.Factrial[divisor - 1];
            ret %= MOD;
            return ret;
        }
    }

    // libs ----------
    // フェルマーの定理、逆元を使う場合
    class FermatCombination
    {
        public long[] Factrial; // 階乗
        public long[] Inverse; // 逆元
        public long MOD = 1000000007;

        public FermatCombination(int n)
        {

            Factrial = new long[n + 1];
            Inverse = new long[n + 1];
            Factrial[0] = 1;
            Inverse[0] = 1;

            for (int i = 1; i <= n; i++)
            {
                Factrial[i] = (Factrial[i - 1] * i) % MOD;
            }

            for (int i = 1; i <= n; i++)
            {
                // フェルマーの小定理で逆元を求める
                Inverse[i] = Power(Factrial[i], (int)MOD - 2, MOD) % MOD;
            }
        }

        public long Permutation(int n, int k)
        {
            return Factrial[n] * Inverse[n - k] % MOD;
        }

        public long Combination(int n, int k)
        {
            return Factrial[n] * Inverse[k] % MOD * Inverse[n - k] % MOD;
        }

        public static long Power(long x, long n, long M)
        {
            long tmp = 1;

            if (n > 0)
            {
                tmp = Power(x, n / 2, M);
                if (n % 2 == 0) tmp = (tmp * tmp) % M;
                else tmp = (((tmp * tmp) % M) * x) % M;
            }

            return tmp;
        }
    }

