class Comb
{
    private long size;
    private long[] inv;
    private long[] kai;
    private long[] invkai;
    private long mod;
    public Comb(long size, long mod)
    {
        this.size = size;
        this.mod = mod;
        inv = new long[size + 1];
        kai = new long[size + 1];
        invkai = new long[size + 1];
        inv[1] = 1;
        for (int i = 2; i <= size; i++)
            inv[i] = mod - (mod / i) * inv[mod % i] % mod;
        kai[0] = 1;
        invkai[0] = 1;
        for (int i = 1; i <= size; i++)
        {
            kai[i] = kai[i - 1] * i % mod;
            invkai[i] = invkai[i - 1] * inv[i] % mod;
        }
    }
    public long Com(long a, long b)
    {
        if (a < b || b < 0)
            return 0;
        return (invkai[b] * invkai[a - b]) % mod * kai[a] % mod;
    }
}

