public class Hello
{
    private const int MOD_N = 1000000000 + 7;

    public static void Main()
    {
        var list = Console.ReadLine().Split(' ');
        var n = int.Parse(list[0]);
        var m = int.Parse(list[1]);
        var k = int.Parse(list[2]);

        long total = 0;
        for (int i = 1; i < n; ++i)
        {
            for (int j = 1; j < m; ++j)
            {
                for (int a = i + 1; a <= n; ++a)
                {
                    for (int b = j + 1; b <= m; ++b)
                    {
                        total += a + b - i - j;
                        total %= MOD_N;
                    }
                }
            }
        }

        Console.WriteLine((total * Comb(n * m, k) % MOD_N));
    }

    private static int Comb(int m, int n)
    {
        var t = new int[m + 1];
        t[0] = t[1] = 1;

        for (int i = 1; i < m; ++i)
        {
            for (int j = i + 1; j != 0; --j)
                t[j] += t[j - 1];
        }

        return t[n];
    }
}

