public class Hello
{
    private const int MOD_N = 1000000000 + 7;

    public static void Main()
    {
        var list = Console.ReadLine().Split(' ');
        var n = int.Parse(list[0]);
        var m = int.Parse(list[1]);
        var k = int.Parse(list[2]);

        long total = 0;
        for (int i = 1; i <= n; ++i)
        {
            for (int j = 1; j <= m; ++j)
            {
                for (int b = j + 1; b <= m; ++b)
                {
                    total += b - j;
                    total %= MOD_N;
                }
                for (int a = i + 1; a <= n; ++a)
                {
                    for (int b = 1; b <= m; ++b)
                    {
                        total += a - i + Math.Abs(b - j);
                        total %= MOD_N;
                    }
                }
            }
        }

        var ans = total * Comb(n * m - 2, k - 2);
        ans %= MOD_N;
        if (ans < 0)
            ans += MOD_N;
        Console.WriteLine(ans);
    }

    private static int Comb(int m, int n)
    {
        var t = m - n;
        if (n > t)
            n = t;

        long numerator = 1;
        for (int i = 0; i < n; ++i)
        {
            numerator *= m - i;
            numerator %= MOD_N;
        }
        long denominator = 1;
        for (; n != 0; --n)
        {
            denominator *= n;
            denominator %= MOD_N;
        }

        var ret = (int)(numerator * ModInv((int)denominator, MOD_N) % MOD_N);

        return ret >= 0 ? ret : ret + MOD_N;
    }

    private static int ModInv(int a, int m)
    {
        int b = m, x = 1, y = 0;
        while (b != 0)
        {
            var t = a / b;
            a -= t * b;
            Swap(ref a, ref b);
            x -= t * y;
            Swap(ref x, ref y);
        }
        x %= m;
        return x >= 0 ? x : x + m;
    }

    private static void Swap<T>(ref T a, ref T b)
    {
        var t = a;
        a = b;
        b = t;
    }
}

