	static BigInteger Npr(BigInteger n, BigInteger r)
	{
		if (n < r) return 0;
		for (BigInteger x = 1, i = n - r; ; x *= ++i) if (i >= n) return x;
	}
	static BigInteger Ncr(BigInteger n, BigInteger r) => n < r ? 0 : n - r < r ? Ncr(n, n - r) : Npr(n, r) / Factorial(r);
}

