        var m = nmk[1];
        var k = nmk[2];

        var xy = 0L;

        for (var d = 1; d < n; d++)
        {
            xy += (n - d) * m % MOD * m % MOD * d % MOD;
            xy %= MOD;
        }

        for (var d = 1; d < m; d++)
        {
            xy += (m - d) * n % MOD * n % MOD * d % MOD;
            xy %= MOD;
        }

        Console.WriteLine(xy * Combination(n * m - 2, k - 2) % MOD);
    }

    /// <summary>
    /// 組合せ nCr = n! / r! / (n-r)!
    /// [フェルマーの小定理を使用] n! * r!^(m-2) * (n-r)!^(m-2)
    /// </summary>
    long Combination(long n, long r)
    {
        var p = new long[n + 1];
        p[0] = 1;
        p[1] = 1;
        for (var i = 2; i <= n; i++)
        {
            p[i] = i * p[i - 1] % MOD;
        }
        return p[n] * Power(p[r], MOD - 2) % MOD * Power(p[n - r], MOD - 2) % MOD;
    }

    /// <summary>
    /// べき乗 [バイナリ法/繰返し二乗法を使用]
    /// </summary>
    long Power(long a, long n)
    {
        var x = 1L;
        while (n > 0)
        {
            if ((n & 1) != 0) x = x * a % MOD;
            n >>= 1;
            a = a * a % MOD;
        }
        return x;
    }

