        {
            if( a < b) { return 0; }
            if( a < 0 || b < 0) { return 0; }
            long ans = 1;
            for(int i=0;i<b;++i)
            {
                ans *= a - i;
                ans %= MOD;
            }
            for(long i=b;i>=2;--i)
            {
