public class Hello
{
    private const long INF = 1000000007;
    private struct Pair { public long x, y; public Pair(long xx, long yy) { x = xx; y = yy; } }
    public static void Main()
    {
        int N = NextInt();
        int M = NextInt();
        int K = NextInt();
        //2点間さえわかればおｋ
        long ans = 0;
        long C = PCH.nCr(N * M - 2, K - 2);
        long[] X = new long[M + 1];
        for (int i = 0; i <= M; i++) { X[i] = i; X[i] %= INF; }
        for (int i = 1; i <= M; i++) { X[i] += X[i - 1]; X[i] %= INF; }

        long[] Y = new long[N + 1];
        for (int i = 0; i <= N; i++) { Y[i] = i * M; Y[i] %= INF; }
        for (int i = 1; i <= N; i++) { Y[i] += Y[i - 1]; Y[i] %= INF; }

        for (int x = 1; x <= M; x++)
        {
            for (int y = 1; y <= N; y++)
            {
                //Y座標は上にしか存在しない(同じ列のY座標はなので)
                ans += (((Y[N - y] + INF) % INF) * C) % INF;

                //X座標は絶えず変動するので自身より右、左側(領域高さ-1)を足す
                ans += (((X[M - x] + INF) % INF) * (N - y + 1) + ((X[x - 1] + INF) % INF) * (N - y)) * C % INF;
            }
        }
        Console.WriteLine(ans % INF);
    }
}
public static class PCH
{
    public static long nPr(long n, long r, long m = 1000000007)
    {
        for (long i = 0; i < r; r++) { n *= (n - i); n %= m; }
        return n;
    }
    public static long nCr(long n, long r, long m = 1000000007)
    {
        long a = 1;
        for (long i = 0; i < r; i++) { a *= (n - i); a %= m; }
        long b = 1;
        for (long x = 2; x <= r; x++) { b *= x; b %= m; }
        b = RepPow(b, m - 2) % m;
        return (a * b) % m;
    }
    public static long nHr(long n, long r, long m = 1000000007)
    {
        return nCr(n + r - 1, r, m);
    }
    public static long RepPow(long x, long p, long m = 1000000007)
    {
        if (p == 1) return x % m;
        long b = RepPow(x, p / 2, m) % m;
        if (p % 2 == 0) { return (b * b) % m; }
        else { return (x * ((b * b) % m)) % m; }
    }
}
