MOD=10**9+7

def modpow(a,b,m)
  return b==0 ? 1 : b%2==1 ? (modpow(a,b-1,m)*a)%m : modpow(a**2%m,b/2,m) 
end
def fact(n,m)
  return (1..n).inject(1){|a,b| a*b%m}
end
def inv(n,m)
  return modpow(n,m-2,m)
end
def comb(n,r,m)
  return fact(n,m)*inv(fact(r,m),m)*inv(fact(n-r,m),m)%m
end

