const MOD = 1000000007

// CombinationInit returns a function that calculates a combinatorial in O(1). O(n)
func CombinationInit(n, p int) func(a, b int) int {
	fac := make([]int, n+1)
	ifac := make([]int, n+1)
	inv := make([]int, n+1)

	fac[0], fac[1] = 1, 1
	ifac[0], ifac[1] = 1, 1
	inv[1] = 1

	for i := 1; i < n; i++ {
		fac[i+1] = fac[i] * (i + 1) % p
		inv[i+1] = p - inv[p%(i+1)]*(p/(i+1))%p
		ifac[i+1] = ifac[i] * inv[i+1] % p
	}

	return func(a, b int) int { return (fac[a] * ifac[b] % p) * ifac[a-b] % p }
}

