func prepareCombination() {
	fact = make([]int, max)
	finv = make([]int, max)
	inv = make([]int, max)

	fact[0] = 1
	fact[1] = 1
	finv[0] = 1
	finv[1] = 1
	inv[1] = 1

	for i := 2; i < max; i++ {
		fact[i] = fact[i-1] * i % mod
		inv[i] = mod - inv[mod%i]*(mod/i)%mod
		finv[i] = finv[i-1] * inv[i] % mod
	}
}

func combinationM(n, k int) int {
	if n < k {
		return 0
	}
	if n < 0 || k < 0 {
		return 0
	}

	return fact[n] * (finv[k] * finv[n-k] % mod) % mod
}

