// Max of the ints
func Max(numbers ...int) int {
	max := numbers[0]
	for i, number := range numbers {
		if i == 0 {
			continue
		}
		if number > max {
			max = number
		}
	}
	return max
}

// Min of the ints
func Min(numbers ...int) int {
	max := numbers[0]
	for i, number := range numbers {
		if i == 0 {
			continue
		}
		if max > number {
			max = number
		}
	}
	return max
}

// DigitSum returns sum of the int's digits
func DigitSum(n int) int {
	if n < 0 {
		return -1
	}

	res := 0

	for n > 0 {
		res += n % 10
		n /= 10
	}

	return res
}

// Sum of the ints
func Sum(numbers ...int) int {
	sum := 0

	for _, number := range numbers {
		sum += number
	}

	return sum
}

// Pow calculates the pow for int with O(log e)
func Pow(a, e int) int {
	res := 1

	for e != 0 {
		if e&1 == 1 {
			res = res * a
		}
		a = a * a
		e = e >> 1
	}

	return res
}

// PowM gets the Pow value mod M
func PowM(a, e, mod int) int {
	res := 1

	for e != 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e = e >> 1
	}

	return res
}

