// nの階乗(mod M)
// return: nまでの階乗を示す全値(e.g., fact[5] = 5!を示す値)
func mfactorial(n int, M int) []int {
	fact := make([]int, n+1)
	fact[0] = 1
	for i := 1; i <= n; i++ {
		fact[i] = (fact[i-1] * i) % M
	}
	return fact
}

// x^n (mod M)
// See https://qiita.com/ofutonfuton/items/92b1a6f4a7775f00b6ae
func mpow(x, n, M int) int {
	ans := 1
	for n != 0 {
		if n&1 == 1 {
			ans = ans * x % M
		}
		x = x * x % M
		n = n >> 1
	}
	return ans
}

// nCk (mod M)
// @see https://qiita.com/ofutonfuton/items/92b1a6f4a7775f00b6ae
func combi(n int, k int, M int) int {
	if n == 0 && k == 0 {
		return 1
	} else if n < k || n < 0 {
		return 0
	}
	fact := mfactorial(n, M)

	ans := fact[n] * mpow(fact[k], M-2, M) % M
	ans *= mpow(fact[n-k], M-2, M) % M

	return ans % M
}

func mod(a, b int) int {
	for {
		if a < b {
			return a
		}
		a -= b
	}
}

func main() {
	var n, m, k int
	fmt.Scan(&n, &m, &k)
	modRoot := 1000000007

	sumX := 0
	sumY := 0
	for i := 1; i < m; i++ {
		sumX += i * (m - i)
		sumX = mod(sumX, modRoot)
	}
	sumX *= mod(n*n, modRoot)
	sumX = mod(sumX, modRoot)
	for i := 1; i < n; i++ {
		sumY += i * (n - i)
		sumY = mod(sumY, modRoot)
	}
	sumY *= mod(m*m, modRoot)
	sumY = mod(sumY, modRoot)

	sum := combi(m*n-2, k-2, modRoot) * (sumX + sumY)

	fmt.Println(mod(sum, modRoot))
}

