func Factorial(N int) (F, Finv []int) {
  F = make([]int, N + 1)
  Finv = make([]int, N + 1)
  inv := make([]int, N + 1)
  F[0] = 1
  F[1] = 1
  Finv[0] = 1
  Finv[1] = 1
  inv[0] = 1
  inv[1] = 1
  for i := 2; i < N + 1; i++ {
    F[i] = F[i - 1] * i % p
    inv[i] = p - inv[p % i] * (p / i) % p
    Finv[i] = Finv[i - 1] * inv[i] % p
  }
  return
}

func Comb(F, Finv *[]int, N, a int) (ret int) {
  ret = (*F)[N] * ((*Finv)[a] * (*Finv)[N - a] % p) % p
  return
}

