      m := M - j
      n := N - i
      S += m * (m - 1) / 2 % p
      S += M * n * (n - 1) / 2 % p
      S += (n - 1) * (j * (j + 1) / 2 + m * (m - 1) / 2) % p
      S %= p
    }
  }
  F, Finv := Factorial(N * M)
  S *= Comb(&F, &Finv, N * M - 2, K - 2)
  S %= p
  Write(S)
