	if y == 0 {
		return 1
	}
	var i int
	for i =1;i<y;i++ {
		z = z * x
	}
	return z
}

func permutation(n int, k int) int {
	v := 1
	if 0 < k && k <= n {
		for i := 0; i < k; i++ {
			v *= (n - i)
		}
	} else if k > n {
		v = 0
	}
	return v
}

func factorial(n int) int {
	return permutation(n, n - 1)
}

func combination(n int, k int) int {
	return permutation(n, k) / factorial(k)
}

func answer(reader io.Reader, writer io.Writer) {
	var n,m,k int
	_, _ = fmt.Fscan(reader, &n, &m, &k)

	mod := 1000000007
	var sumX, sumY int
	c := 1
	if k > 2 {
		c = combination(n*m-2, k-2)
		c %= mod
	}
	for i := 1; i < n; i++ {
		sumX += i * (n - i)
		sumX %= mod
	}
	sumX = sumX * m * m
	sumX %= mod
	for i := 1; i < m; i++ {
		sumY += i * (m - i)
		sumY %= mod
	}
	sumY = sumY * n * n
	sumY %= mod
	sum := (sumX + sumY) * c
	sum %= mod
