    foreach (i; 0..N) {
        long right = N - i - 1;
        long left = i;
        tmp = (tmp + right * (right + 1) / 2 * M) % MOD;
        tmp = (tmp + left * (left + 1) / 2 * M) % MOD;
    }

    ans += tmp * C % MOD * M % MOD;
    ans %= MOD;

    tmp = 0;
    foreach (i; 0..M) {
        long right = M - i - 1;
        long left = i;
        tmp = (tmp + right * (right + 1) / 2 * N) % MOD;
        tmp = (tmp + left * (left + 1) / 2 * N) % MOD;
    }

    ans += tmp * C % MOD * N % MOD;
    ans %= MOD;
    ans =  ans * powmod(2, MOD-2, MOD) % MOD;
    ans.writeln;
}

long powmod(long a, long x, long m) {
    long ret = 1;
    while (x) {
        if (x % 2) ret = ret * a % m;
        a = a * a % m;
        x /= 2;
    }
    return ret;
}

