immutable long MOD = 1000000007;


auto solve(long N, long M, long K) {
    const a =
        (
            iota(M)
                .map!(d => (M - d) * d % MOD)
                .reduce!((a, b) => (a + b) % MOD) * N % MOD * N % MOD
            +
            iota(N)
                .map!(d => (N - d) * d % MOD)
                .reduce!((a, b) => (a + b) % MOD) * M % MOD * M % MOD
        ) % MOD;
    const b =
        ModCalc(MOD).C(N * M - 2, K - 2);

    return a * b % MOD;
}


struct ModCalc {
private:
    long mod;
    long[] fac;
    long[] inv;
    long[] finv;

public:
    this(long mod) {
        this.mod = mod;
        fac = [1, 1];
        inv = [0, 1];
        finv = [1, 1];
    }

    long factorial(long n) {
        assert(n >= 0);

        auto n_ = n.to!size_t;
        extendTable(n_ + 1);
        return fac[n_];
    }

    long P(long n, long k) {
        assert(0 <= k && k <= n);

        auto n_ = n.to!size_t;
        auto k_ = k.to!size_t;
        extendTable(n_ + 1);
        return fac[n_] * finv[n_ - k_] % mod;
    }

    long C(long n, long k) {
        assert(0 <= k && k <= n);

        auto n_ = n.to!size_t;
        auto k_ = k.to!size_t;
        extendTable(n_ + 1);
        return fac[n_] * finv[k_] % mod * finv[n_ - k_] % mod;
    }

    long H(long n, long k) {
        return C(n + k - 1, k);
    }

private:
    void extendTable(size_t size) {
        auto oldsize = fac.length;
        if (size <= oldsize)
            return;

        fac.length = size;
        inv.length = size;
        finv.length = size;

        foreach (i; oldsize .. size) {
            fac[i] = fac[i - 1] * i % mod;
            inv[i] = mod - inv[(mod % i).to!size_t] * (mod / i) % mod;
            finv[i] = finv[i - 1] * inv[i] % mod;
        }
    }
}


void main() {
    auto input = stdin.byLine.map!split.joiner;

    long N;
    N = input.front.to!long;
    input.popFront;

    long M;
    M = input.front.to!long;
    input.popFront;

    long K;
    K = input.front.to!long;
    input.popFront;

    static if (is(ReturnType!solve == void))
        solve(N, M, K);
    else
        solve(N, M, K).writeln;
}

