Mint nCr(int n, int r) {
  Mint[] fact = new Mint[2 * 10 ^^ 5 + 1];
  Mint[] invFact = new Mint[2 * 10 ^^ 5 + 1];
  fact[0] = fact[1] = 1;
  invFact[0] = invFact[1] = 1;
  foreach (i; 2 .. 2 * 10 ^^ 5 + 1) {
    fact[i] = fact[i - 1] * i;
    invFact[i] = fact[i].inv;
  }

  return fact[n] * invFact[r] * invFact[n - r];
}

