		d = pre_r // cur_r
		r = pre_r % cur_r

		nxt_r = r
		nxt_x = pre_x - d * cur_x
		nxt_y = pre_y - d * cur_y

		if nxt_r == 1:
			ret = nxt_x
			while ret < 0:
