struct Binomial<T> {
    mod_n: T,
    fact: Vec<T>,
    fact_inv: Vec<T>,
    inv: Vec<T>,
}

impl<T> Binomial<T>
where
    T: num::PrimInt,
{
    pub fn new(size: usize, mod_n: T) -> Binomial<T> {
        let mut init = Binomial {
            mod_n,
            fact: Vec::with_capacity(size + 5),
            fact_inv: Vec::with_capacity(size + 5),
            inv: Vec::with_capacity(size + 5),
        };
        init.fact.push(T::from(1).unwrap());
        init.fact.push(T::from(1).unwrap());
        init.fact_inv.push(T::from(1).unwrap());
        init.fact_inv.push(T::from(1).unwrap());
        init.inv.push(T::from(1).unwrap());
        init.inv.push(T::from(1).unwrap());
        for i in 2..size + 5 {
            init.fact
                .push(init.fact[i - 1] * T::from(i).unwrap() % mod_n);
            init.inv.push(
                mod_n
                    - init.inv[mod_n.to_usize().unwrap() % i] * (mod_n / T::from(i).unwrap())
                        % mod_n,
            );
            init.fact_inv
                .push(init.fact_inv[i - 1] * init.inv[i] % mod_n);
        }
        init
    }

    pub fn calc(&self, n: usize, k: usize) -> T {
        self.fact[n] * (self.fact_inv[k] * self.fact_inv[n - k] % self.mod_n) % self.mod_n
    }
}

