fn main() {
    input! {
        n: usize,
        m: usize,
        k: usize
    }

    let mod_num: i64 = 1000_000_007;
    let binomial = Binomial::new(n * m, mod_num);

    let mut ans = 0;
    for d in 1..n {
        ans += d * (n - d) * m * m % mod_num as usize;
    }
    for d in 1..m {
        ans += d * (m - d) * n * n % mod_num as usize;
    }

    println!(
        "{}",
        (ans as i64 * binomial.calc(n * m - 2, k - 2)) % mod_num
    );
}

