fn main() {
    let mut scanner = Scanner::new(stdin());
    let param = scanner.read_vector::<u64>().unwrap();
    let (n, m, k) = (param[0], param[1], param[2]);
    let modulo = 1_000_000_000 + 7;
    let mut ans = 0;
    for i in 1..n {
        ans = (ans + (((((n - i) * m) % modulo) * m * i) % modulo)) % modulo;
    }
    for i in 1..m {
        ans = (ans + (((((m - i) * n) % modulo) * n * i) % modulo)) % modulo;
    }
