fn combination(n: u64, k: u64, modulo: u64) -> u64 {
    if k == 0 {
        return 1;
    }
    let n_fact = factorial(n, modulo);
    let k_fact = factorial(k, modulo);
    let nk_fact = factorial(n - k, modulo);
    let k_pow_inv = pow(k_fact, modulo - 2, modulo);
    let nk_pow_inv = pow(nk_fact, modulo - 2, modulo);
    let mut ans = n_fact;
    ans = (ans * k_pow_inv) % modulo;
    ans = (ans * nk_pow_inv) % modulo;
    ans
}

fn factorial(n: u64, modulo: u64) -> u64 {
    let mut n_fact = 1;
    for i in 2..(n + 1) {
        n_fact = (n_fact * i) % modulo;
    }
    n_fact
}

fn pow(x: u64, mut n: u64, modulo: u64) -> u64 {
    let mut pows = vec![x];
    for i in 0..63 {
        let square = (pows[i] * pows[i]) % modulo;
        pows.push(square);
    }
    let mut ans = 1;
    for i in 0..64 {
        let flag = n & 1;
        n >>= 1;
        if flag == 1 {
            ans = (ans * pows[i]) % modulo;
        }
    }
    ans
}

