const DIV: usize = 1000000000 + 7;

fn main() {
    input!{
        n: usize,
        m: usize,
        k: usize,
    }
    let mut set: BTreeSet<usize> = BTreeSet::new();
    let result = solve(&mut set, n, m, 0, k, 0);
    println!("{}", result);
}

fn solve(set: &mut BTreeSet<usize>, n: usize, m: usize, nmi: usize, k: usize, ki: usize) -> usize {
    if ki >= k {
        return {
            let v = set.iter().map(|&v| v).collect::<Vec<usize>>();
            // println!("{:?}", v);
            let mut sum = 0;
            for i in 0..v.len() {
                for j in i + 1 .. v.len() {
                    let left = v[i];
                    let right = v[j];
                    let lx = left / n;
                    let ly = left % n;
                    let rx = right / n;
                    let ry = right % n;
                    sum += max(lx, rx) - min(lx, rx) + max(ly, ry) - min(ly, ry);
                    sum %= DIV;
                }
            }
            sum
        };
    }
    let mut sum = 0;
    for row in nmi..n * m {
        set.insert(row);
        sum += solve(set, n, m, row + 1, k, ki + 1);
        set.remove(&row);
        sum %= DIV;
    }
    sum
}

