#[doc = " a / b modulo m == a * modinv(b, m) % m"]
#[allow(dead_code)]
fn modinv(a_: u64, m_: u64) -> u64 {
    let m = m_ as i64;
    let mut a = a_ as i64;
    let mut b = m as i64;
    let mut u = 1;
    let mut v = 0;
    while b != 0 {
        let t = a / b;
        a -= t * b;
        std::mem::swap(&mut a, &mut b);
        u -= t * v;
        std::mem::swap(&mut u, &mut v);
    }
    u %= m;
    if u < 0 {
        u += m
    };
    u as u64
}
#[allow(dead_code)]
fn comb(n: u64, r: u64, m: u64) -> u64 {
    let mut ret = 1u64;
    for i in 0..r {
        ret *= n - i;
        ret %= m;
    }
    for i in 1..r + 1 {
        ret *= modinv(i, m);
        ret %= m;
    }
    ret
}
#[doc = " combination with repetition"]
#[allow(dead_code)]
fn comb_rep(n: u64, r: u64, m: u64) -> u64 {
