struct UnionFind {
    parent: Vec<usize>,
    rank: Vec<usize>,
    size: Vec<usize>,
}

impl UnionFind {
    fn new(n: usize) -> UnionFind {
        let mut parent = vec![0; n];
        for i in 0..n {
            parent[i] = i;
        }
        return UnionFind {
            parent: parent,
            rank: vec![0; n],
            size: vec![1; n],
        };
    }

    fn find(&mut self, x: usize) -> usize {
        if x == self.parent[x] {
            x
        } else {
            let parent = self.parent[x];
            let pr = self.find(parent);
            self.parent[x] = pr;
            pr
        }
    }

    fn same(&mut self, a: usize, b: usize) -> bool {
        self.find(a) == self.find(b)
    }

    fn unite(&mut self, a: usize, b: usize) {
        let a_root = self.find(a);
        let b_root = self.find(b);
        if self.rank[a_root] > self.rank[b_root] {
            self.parent[b_root] = a_root;
            self.size[a_root] += self.size[b_root];
        } else {
            self.parent[a_root] = b_root;
            self.size[b_root] += self.size[a_root];
            if self.rank[a_root] == self.rank[b_root] {
                self.rank[b_root] += 1;
            }
        }
    }

    fn get_size(&mut self, x: usize) -> usize {
        let root = self.find(x);
        self.size[root]
    }
}

const p: usize = 1000000007;

// fact(n) = n! mod p
fn fact(n: usize) -> usize {
    let mut acc = 1;
    for i in 1..n + 1 {
        acc = acc * i % p;
    }
    acc
}

fn mod_pow(b: usize, mut e: usize) -> usize {
    let mut base = b;
    let mut acc = 1;

    while e > 1 {
        if e % 2 == 1 {
            acc = acc * base % p;
        }
        e /= 2;
        base = base * base % p;
    }

    if e == 1 {
        acc = acc * base % p;
    }

    acc
}

fn comb(n: usize, r: usize) -> usize {
    // nCr = n! / (r! (n-r)!) = n! (r!)^(p-2) ((n-r)!)^(p-2)
    fact(n) * mod_pow(fact(r), p - 2) % p * mod_pow(fact(n - r), p - 2) % p
}

fn main() {
    input! {
        n: usize,
        m: usize,
        k: usize,
    }

    let mut ans = 0;

    for i in 1..n {
        ans += i * (n - i) * m * m;
        ans %= p;
    }
    for i in 1..m {
        ans += i * (m - i) * n * n;
        ans %= p;
    }

    ans = ans * comb(n * m - 2, k - 2) % p;

    println!("{}", ans);
}

