const P: i64 = 1_000_000_007;

fn main() {
    let (N, M, K) = read!(usize, usize, usize);
    let NM = N * M;

    // fact[n] = n! (mod P)
    let mut fact = vec![0; NM + 1];
    fact[0] = 1;
    fact[1] = 1;
    for n in 2..NM + 1 {
        // n! = (n - 1!) * n
        fact[n] = fact[n - 1] * n as i64 % P;
    }

    // inv[n] = 1/n (mod P)
    let mut inv = vec![0; NM + 1];
    inv[1] = 1;
    for n in 2..NM + 1 {
        // 1/n = -(P / n) / (P % n)
        // (P = floor(P / n) n + P % n から導出)
        let mut z = P - inv[(P % n as i64) as usize];
        z %= P;
        z *= P / n as i64;
        z %= P;
        inv[n] = z;
    }

    // fact_inv[n] = 1/(n!) (mod P)
    let mut fact_inv = vec![0; NM + 1];
    fact_inv[0] = 1;
    fact_inv[1] = 1;
    for n in 2..NM + 1 {
        // 1/(n!) = (1 / (n - 1)!) * 1/n
        fact_inv[n] = fact_inv[n - 1] * inv[n] % P;
    }

    // C(n, r) = n! / ((n - r)! r!)
    let combo = |n, r| {
        let mut z = fact_inv[n - r];
        z *= fact_inv[r];
        z %= P;
        z *= fact[n];
        z %= P;
        z
    };

    // M^2 * Σd. d (N - d)
    let mut y = 0;
    for d in 1..N {
        y += (d * (N - d)) as i64 % P;
        y %= P;
    }
    y *= (M * M) as i64;
    y %= P;

    // N^2 * Σd. d (M - d)
    let mut x = 0;
    for d in 1..M {
        x += (d * (M - d)) as i64 % P;
        x %= P;
    }
    x *= (N * N) as i64 % P;
    x %= P;

    let mut z = (y + x) % P;
    z *= combo(NM - 2, K - 2);
    z %= P;

    println!("{}", z)
}

