pub fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m, k) = i.read::<(usize, usize, usize)>();
    writeln!(o, "{}", solve(n, m, k)).unwrap();
}
fn solve(n: usize, m: usize, k: usize) -> usize {
    fn get(n: usize, m: usize, comb: Mod) -> Mod {
        let mut c = 0;
        for i in 1..m {
            c += (m - i) * i;
        }
        comb * n * n * c
    }
    let comb = comb(n * m - 2, k - 2);
    (get(n, m, comb) + get(m, n, comb)).0
}
fn comb(n: usize, m: usize) -> Mod {
    let mut v0 = Mod::new(1);
    let mut v1 = Mod::new(1);
    for i in 0..m {
        v0 *= i + 1;
        v1 *= n - i;
    }
    v1 / v0
}

pub mod utils {
