    let (n, m, k): (usize, usize, usize);
    input!(n, m, k);
    let mut sum = Modint::new(0);
    for d in 1..m {
        let mut buf = Modint::new(m - d);
        buf.mul_uint(n);
        buf.mul_uint(n);
        buf.mul_uint(d);
        sum = &sum + &buf;
    }
    for d in 1..n {
        let mut buf = Modint::new(n - d);
        buf.mul_uint(m);
        buf.mul_uint(m);
        buf.mul_uint(d);
        sum = &sum + &buf;
    }
    let mut dpf = DPFactorial::new();
    sum = &sum * &dpf.get_combination(m * n - 2, k - 2);
    println!("{}", sum);
}

