use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        m: usize,
        k: usize,
    }
    let mut facts = gen_fact_table::<Mod_1_000_000_007>(500000);
    let mut div2 = Mod::new(1) / Mod::new(2);
    let mut res = Mod::new(0);
    let nCr = |n: usize, r: usize| facts[n] / (facts[n - r] * facts[r]);
    // x
    for d in 0..n {
        let l = Mod::new(d as u32);
        let r = Mod::new((n - d - 1) as u32);
        let l2 = l * (l + Mod::new(1)) * div2;
        let r2 = r * (r + Mod::new(1)) * div2;
        let mm = Mod::new(m as u32);
        res += (l2 + r2) * mm * mm * nCr(n * m - 2, k - 2);
    }
    // eprintln!("{}", res.as_u32());
    // y
    for d in 0..m {
        let l = Mod::new(d as u32);
        let r = Mod::new((m - d - 1) as u32);
        let l2 = l * (l + Mod::new(1)) * div2;
        let r2 = r * (r + Mod::new(1)) * div2;
        let nn = Mod::new(n as u32);
        res += (l2 + r2) * nn * nn * nCr(n * m - 2, k - 2);
    }
    res *= div2;
    writeln!(buf, "{}", res.as_u32());
    buf
}

