pub type ModPBase = u64;
pub const MODULUS: ModPBase = 1_000_000_007;
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct ModP {
    base: ModPBase,
}
impl ModP {
    pub fn new(n: ModPBase) -> ModP {
        if !cfg!(test) {
            assert!(
                MODULUS != 7,
                "Set const MODULUS to the value provided by the problem."
            );
        }
        ModP { base: n % MODULUS }
    }
    pub unsafe fn new_unchecked(n: ModPBase) -> ModP {
        ModP { base: n }
    }
    pub fn base(&self) -> ModPBase {
        self.base
    }
    pub fn pow(self, exp: ModPBase) -> ModP {
        if exp == 0 {
            ModP::new(1)
        } else {
            let sub = self.pow(exp / 2);
            if exp % 2 == 0 {
                sub * sub
            } else {
                self * sub * sub
            }
        }
    }
    pub fn inv(self) -> ModP {
        assert!(self.base() != 0);
        self.pow(MODULUS - 2)
    }
}
