#[derive(Copy, Clone)]
struct F(u64);
const MOD:u64 = 1000000007;

impl F {
    pub fn new(n: i32) -> Self { F((MOD as i32 + n)as u64%MOD) }
    pub fn pow(self, mut exp: u32) -> Self {
        let mut base = self.0;
        let mut acc = 1;
        while exp > 1 {
            if (exp & 1) == 1 { acc *= base; acc %= MOD; }
            exp /= 2; base *= base; base %= MOD;
        }
        if exp == 1 { acc *= base; acc %= MOD; }
        F(acc)
    }
}
impl std::ops::Mul for F {
    type Output = Self;
    fn mul(self, rhs: Self) -> Self {F((self.0 * rhs.0)%MOD)}
}
impl std::ops::MulAssign for F {
    fn mul_assign(&mut self, rhs: Self) {*self = F((self.0 * rhs.0)%MOD)}
}
impl std::ops::Add for F {
    type Output = Self;
    fn add(self, rhs: Self) -> Self {F((self.0 + rhs.0)%MOD)}
}
impl std::ops::AddAssign for F {
    fn add_assign(&mut self, rhs: Self) {*self = F((self.0 + rhs.0)%MOD)}
}
impl std::ops::Neg for F {
    type Output = Self;
    fn neg(self) -> Self {if self.0==0 {F(0)} else {F(MOD-self.0)}}
}
impl std::ops::Sub for F {
    type Output = Self;
    fn sub(self, rhs: Self) -> Self {F((self.0 - rhs.0 + MOD)%MOD)}
}
impl std::ops::SubAssign for F {
    fn sub_assign(&mut self, rhs: Self) {*self = F((self.0 - rhs.0 + MOD)%MOD)}
}
impl std::ops::Div for F {
    type Output = Self;
    fn div(self, rhs: Self) -> Self {F(self.0 * rhs.pow(MOD as u32-2).0 %MOD)}
}
impl std::ops::DivAssign for F {
    fn div_assign(&mut self, rhs: Self) {*self = F(self.0 * rhs.pow(MOD as u32-2).0 %MOD)}
}
impl std::cmp::PartialEq for F {
    fn eq(&self, rhs: &Self) -> bool {self.0 == rhs.0}
}
impl std::fmt::Display for F {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "{}", self.0)
    }
}

