    let m: u64 = itr.next().unwrap().parse().unwrap();
    let k: usize = itr.next().unwrap().parse().unwrap();

    const MOD: u64 = 1_000_000_007;
    let e = enumeration::Enumeration::new((n * m) as usize, MOD);

    // x
    // 2点を固定する。
    // それ以外の選び方はn*m - 2 C k - 2
    // 大きさがxとなる　-> n - x通り * m * m

    let mut ans = 0;
    for x in 1..n {
        ans += x * (n - x) % MOD * m % MOD * m % MOD;
    }
    for x in 1..m {
        ans += x * (m - x) % MOD * n % MOD * n % MOD;
    }
    ans = ans * e.c((n * m) as usize - 2, k - 2) % MOD;
    println!("{}", ans);
}

