fn main() {
    let (n,m,k) = {
        let v: Vec<usize> = read_vec();
        (v[0], v[1], v[2])
    };
    let fact = |n| (2..n+1).fold(F(1), |f, a| f * F(a as u64));
    let comb = fact(n*m-2) / fact(n*m-k) / fact(k-2);
    let solve = |n, m| {
        let mut res = F(0);
        let (h, w) = (F(n as u64), F(m as u64));
        for d in 1..n {
            let d = F(d as u64);
            res += d*(h-d);
        }
        res * comb * w * w
    };
    println!("{}", solve(n,m)+solve(m,n));
}
