fn comb(n: i64, k: i64) -> Mod {
    fact(n) / fact(k) / fact(n - k)
}

fn fact(n: i64) -> Mod {
    if n == 0 {
        1.into()
    } else {
        fact(n - 1) * Mod::new(n)
    }
}

