const MOD: usize = 1e9 as usize + 7;
const MAX: usize = 1e5 as usize * 2 + 1;

fn init_fact() -> (Vec<usize>, Vec<usize>, Vec<usize>) {
  let mut fac = vec![0; MAX]; // 階乗
  let mut inv = vec![0; MAX]; // 逆元
  let mut finv = vec![0; MAX]; // 階乗の逆元
  fac[0] = 1;
  fac[1] = 1;
  finv[0] = 1;
  finv[1] = 1;
  inv[1] = 1;
  for i in 2..MAX {
    fac[i] = fac[i-1] * i % MOD;
    inv[i] = MOD - inv[MOD%i] * (MOD / i) % MOD;
    finv[i] = finv[i-1] * inv[i] % MOD;
  }
  return (fac, inv, finv)
}

fn mod_combination(n: usize, k: usize) -> usize {
    let (fac, _, finv) = init_fact();
    let mut ret = fac[n];
    ret *= finv[n-k];
    ret %= MOD;
    ret *= finv[k];
    ret %= MOD;
    ret
}

fn main() {
    input!{
      n: usize,
      m: usize,
      k: usize,
    }
    let mut ans = 0;
    let pair = mod_combination(n*m-2, k-2);
    for d in 1..m {
        ans += n*n*(m-d)*d%MOD *pair%MOD;
        ans %= MOD;
    }
    for d in 1..n {
        ans += m*m*(n-d)*d%MOD *pair%MOD;
        ans %= MOD;
    }
    println!("{}", ans);
}

