const MOD: u64 = 1000000007;

fn gcd(a: u64, b: u64) -> u64 {
    match b {
        0 => a,
        _ => gcd(b, a % b),
    }
}

fn powmod(base: u64, exp: u64, m: u64) -> u64 {
    let b: Vec<bool> = format!("{:b}", exp)
        .chars()
        .map(|x| x.to_digit(10).unwrap() != 0)
        .collect();
    let mut v = 1;
    for bi in b {
        v *= v;
        v %= m;
        if bi {
            v *= base;
            v %= m
        }
    }
    return v % m;
}

fn invmod(x: u64, m: u64) -> u64 {
    powmod(x, m - 2, m)
}

fn prime_factors(x: u64) -> Vec<u64> {
    let mut res = vec![];
    let mut y = x;
    let mut p = 2;
    let upper = (y as f64).sqrt() as u64;
    while y > 1 && p <= upper {
        match y % p {
            0 => {
                res.push(p);
                y /= p;
            }
            _ => {
                p += 1;
            }
        }
    }
    if y > 1 {
        res.push(y)
    }
    return res;
}

fn get_factorials(n: u64, m: u64) -> Vec<u64> {
    let mut res = vec![1];
    let mut cur = 1;
    for i in 1..(n + 1) {
        cur *= i;
        cur %= m;
        res.push(cur);
    }
    res
}

fn get_facinvs(n: u64, m: u64) -> Vec<u64> {
    let mut res = vec![1];
    let mut cur = 1;
    for i in 1..(n + 1) {
        cur *= invmod(i, m);
        cur %= m;
        res.push(cur);
    }
    res
}

fn combmod(a: u64, b: u64, m: u64, facts: &Vec<u64>, invs: &Vec<u64>) -> u64 {
    if a < b {
        0
    } else {
        (((facts[a as usize] * invs[b as usize]) % m) * invs[(a - b) as usize]) % m
    }
}

macro_rules! parse {
    ($iter: ident) => {
        $iter.next().unwrap().parse().unwrap()
    };
    ($iter: ident,2) => {
        (parse!($iter), parse!($iter))
    };
    ($iter: ident,3) => {
        (parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident,4) => {
        (parse!($iter), parse!($iter), parse!($iter), parse!($iter))
    };
    ($iter: ident, $n: ident) => {
        $iter.take($n).map(|e| e.parse().unwrap()).collect();
    };
}

fn solve(x: u64, y: u64, c: u64) -> u64 {
    (1..x)
        .map(|d| (d * ((((((x - d) * y) % MOD) * y) % MOD) * c) % MOD) % MOD)
        .fold(0, |a, b| (a + b) % MOD)
}

fn main() {
    let mut s = String::new();
    stdin().read_to_string(&mut s).unwrap();
    let mut iter = s.split_whitespace();
    let (n, m, k): (u64, u64, u64) = parse!(iter, 3);

    let facts = get_factorials(200001, MOD);
    let invs = get_facinvs(200001, MOD);
    let c = combmod(n * m - 2, k - 2, MOD, &facts, &invs);
    let mut res = solve(n, m, c) + solve(m, n, c);
    res %= MOD;
    println!("{}", res)
}

