pub fn main() {
    let i = stdin();
    let mut o = Vec::new();
    run(i.lock(), &mut o);
    stdout().write_all(&o).unwrap();
}

pub fn run<R: BufRead, W: Write>(i: R, o: &mut W) {
    let mut i = CpReader::new(i);
    let (n, m, k) = i.read::<(usize, usize, usize)>();
    writeln!(o, "{}", solve(n, m, k)).unwrap();
}
fn solve(n: usize, m: usize, k: usize) -> usize {
    fn get(n: usize, m: usize, k: usize, facts: &ModFacts) -> Mod {
        let mut c = 0;
        for i in 1..m {
            c += (m - i) * i;
        }
        facts.comb(n * m - 2, k - 2) * n * n * c
    }
    let facts = ModFacts::new(n * m);
    (get(n, m, k, &facts) + get(m, n, k, &facts)).0
}

pub mod utils {
